    create ()
    {
        const line = new Phaser.Geom.Line(330, 150, 430, 170);

        const graphics = this.add.graphics({ lineStyle: { width: 3, color: 0xaa00aa } });

        graphics.strokeLineShape(line);

        const angleStep = 1 / 15 * Phaser.Math.PI2;

        for (let i = 0; i < 15; i++)
