    {
        const graphics = this.add.graphics();

        const color = 0xffff00;
        const thickness = 2;
        const alpha = 1;

        //  Events

        let draw = false;

        this.input.on('pointerdown', pointer =>
        {

            draw = true;

        });

        this.input.on('pointerup', () =>
        {

            draw = false;

