        this.graphics = this.add.graphics({ lineStyle: { width: 2, color: 0x00ff00 }, fillStyle: { color: 0xff0000 }});

        this.line = new Phaser.Geom.Line(100, 100, 600, 500);
        this.point = new Phaser.Geom.Rectangle(0, 0, 16, 16);
