        this.graphics.clear();

        for (let i = 0; i < this.triangles.length; i++)
        {
            Phaser.Geom.Triangle.RotateAroundPoint(this.triangles[i], this.points[i], 0.02);

            this.graphics.strokeTriangleShape(this.triangles[i]);

