enum Stage { HIDDEN, REVEALED, CLAIMED }

var transitions := {
	Stage.HIDDEN: [Stage.REVEALED],
	Stage.REVEALED: [Stage.CLAIMED],
	Stage.CLAIMED: [Stage.HIDDEN]
}

func can_move(from: int, to: int) -> bool:
	if not transitions.has(from):
		return false
	return to in transitions[from]

func _init():
	assert(can_move(Stage.HIDDEN, Stage.REVEALED), "HIDDEN -> REVEALED should be legal")
	assert(not can_move(Stage.REVEALED, Stage.HIDDEN), "REVEALED -> HIDDEN should be illegal")
	print("transitions verified for Stage")
	quit()
```

