// Interpreting: the CORE of breakout is a ball clearing a grid of bricks on collision. Building the collision/clear logic.
class Breakout{constructor(n){this.bricks=new Set();for(let i=0;i<n;i++)this.bricks.add(i);this.score=0;}hit(i){if(this.bricks.has(i)){this.bricks.delete(i);this.score+=10;return true;}return false;}get cleared(){return this.bricks.size===0;}}
const b=new Breakout(4);assert(b.hit(0)&&b.score===10,'clears brick');assert(!b.hit(0),'already gone');for(let i=1;i<4;i++)b.hit(i);assert(b.cleared,'all cleared');console.log('ok');
```

