function getRepTier(faction) {
  const r = getRep(faction);
  if (r >= 67) return 'revered';
  if (r >= 34) return 'trusted';
  if (r >= 1)  return 'acquaintance';
  return 'unknown';
}

function getRep(faction) {
  return REPUTATION[faction] ?? 0;
}

const REPUTATION = {
  town:      50,  // starts neutral — player lives here
  hoboCamp:  0,   // unknown until visited
  badlands:  0,   // unknown until visited (Crane tracks separately)
  mine:      0,   // unlocked by exploring
  // Future zones — initialized at 0, unlocked when zones are built
  city:      0,
  ocean:     0,
  secondFarm:0,
  jungle:    0,   // Eastern Expansion — The Verdant Debt
};

function getRepSellMult() {
  const tier = getRepTier('town');
  if (tier === 'revered')     return 1.20;
  if (tier === 'trusted')     return 1.10;
  if (tier === 'acquaintance')return 1.00;
  return 0.92; // unknown — strangers get worse prices
}
