```javascript
const actionTimer = {
  active: false,
  elapsed: 0,
  duration: 1.0,       // seconds total for this action
  label: '',
  onComplete: null,    // callback fired when timer reaches duration
  cancelOnMove: true,
  _wasMoving: false,
};

function cancelAction(reason) {
  if (!actionTimer.active) return;
  actionTimer.active = false;
  actionTimer.onComplete = null;
  document.getElementById('actionProgress').classList.remove('show');
  if (reason) showMsg(reason, 1400);
}

function showMsg(txt, dur=2800) {
  _msgQueue.push({ txt, dur, isTip: false });
  if (!_msgShowing) _pumpMsgQueue();
}

const _msgQueue = [];

let _msgShowing = false;

function _pumpMsgQueue() {
  if (_msgQueue.length === 0) { _msgShowing = false; return; }
  _msgShowing = true;
  const next = _msgQueue.shift();
  const el = document.getElementById('msgBanner');
  if (next.isTip) el.classList.add('tip'); else el.classList.remove('tip');
  el.textContent = next.txt; el.style.opacity = '1';
  msgTimer2 = next.dur;
}

let msgTimer2 = 0;

function updateActionTimer(dt, isMoving) {
  if (!actionTimer.active) return;
  if (actionTimer.cancelOnMove && isMoving) {
    cancelAction('');   // silent cancel on move — just stop bar
    return;
  }
  actionTimer.elapsed += dt;
  const pct = Math.min(100, (actionTimer.elapsed / actionTimer.duration) * 100);
  document.getElementById('apFill').style.width = pct + '%';
  if (actionTimer.elapsed >= actionTimer.duration) {
    actionTimer.active = false;
    document.getElementById('actionProgress').classList.remove('show');
    const cb = actionTimer.onComplete;
    actionTimer.onComplete = null;
