function revealAround(px, py, radius, grid, gw, gh) {
  const tx = Math.floor(px / T);
  const ty = Math.floor(py / T);
  const r2 = radius * radius;
  let revealed = false;
  for (let dy = -radius; dy <= radius; dy++) {
