  ctx.fillStyle='rgba(0,0,0,.18)';
  for(let i=0;i<3;i++) ctx.fillRect(bsx+3,bsy2+3+i*(Math.floor((bh-6)/3)),bw-6,1);
  // Gunwale highlight
  ctx.fillStyle='rgba(255,255,255,.07)'; ctx.fillRect(bsx,bsy2,bw,2);
