    ctx.fillStyle='rgba(35,30,25,.6)';
    ctx.fillRect(sx+T-8,sy+T-9,5,4);
  } else if (t === TL.COPPER_VEIN) {
    ctx.fillStyle='#5a2808'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    // Copper ore — orange-brown irregular patches
