    ctx.fillStyle=`rgba(220,230,255,${sp})`;
    ctx.fillRect(sx+8,sy+8,2,1);
  } else if (t === TL.SINGING_VEIN) {
    ctx.fillStyle='#1a1018'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    const spd = Date.now()*.00085;
    const vp = 0.3+Math.sin(spd+sx*.3+sy*.5)*0.35;
