const T = 32;

let _soundEnabled = true;

function getDahCtx() {
  if (!_dahAudioCtx) _dahAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  // Browsers suspend AudioContext until a user gesture — resume it on every call so
  // sounds work after the first interaction regardless of when the context was created
  if (_dahAudioCtx.state === 'suspended') _dahAudioCtx.resume();
  return _dahAudioCtx;
}

let _soundVol = 0.5;

const _msgQueue = [];

let _msgShowing = false;

function _pumpMsgQueue() {
  if (_msgQueue.length === 0) { _msgShowing = false; return; }
  _msgShowing = true;
  const next = _msgQueue.shift();
  const el = document.getElementById('msgBanner');
  if (next.isTip) el.classList.add('tip'); else el.classList.remove('tip');
  el.textContent = next.txt; el.style.opacity = '1';
  msgTimer2 = next.dur;
}

let _dahAudioCtx = null;

let msgTimer2 = 0;

