const BGM = { running:false, mode:null, masterGain:null, reverbInput:null, seqTimer:null };

function bgmMasterLevel() { return Math.max(0.18, (_soundVol||0.8)*0.62); }

function getDahCtx() {
  if (!_dahAudioCtx) _dahAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  // Browsers suspend AudioContext until a user gesture — resume it on every call so
