function generateJGWeeklyBills(day) {
  if (typeof gameState._jgDebt === 'undefined') return;
  const currentWeek = getJGWeekNumber(day);
  const start = gameState._jgDebtStartDay || day;
  for (let w = 1; w <= Math.min(currentWeek, JG_DEBT_TOTAL_WEEKS); w++) {
    if (jgWeeklyBills.find(b => b.week === w)) continue;
    const minPay = getJGWeeklyMinPayment(w);
    const due = start + (w - 1) * JG_DEBT_WEEK_LENGTH;
    jgWeeklyBills.push({ week: w, minPayment: minPay, due, paid: false, paidAmount: 0 });
  }
}

function getJGWeekNumber(day) {
  const start = gameState._jgDebtStartDay || day;
  return Math.floor((day - start) / JG_DEBT_WEEK_LENGTH) + 1;
}

function getJGTotalPaid() {
  return jgDebtPaidLog.reduce((s, e) => s + e.amount, 0);
}

function getJGTotalDebt() {
  if (typeof gameState._jgDebt === 'undefined') return 0; // not yet started
  return Math.max(0, gameState._jgDebt);
}

const JG_DEBT_TOTAL_WEEKS  = 40;

function getJGWeeklyMinPayment(week) {
  return JG_DEBT_BASE_WEEKLY + (week - 1) * JG_DEBT_WEEKLY_STEP;
}

const JG_DEBT_TOTAL        = 145000;

let jgWeeklyBills  = [];

