    if (!p.tilled || !p.crop || p.wilted) continue;
    if (Math.random() < 0.20) { // 20% per plot
      p.wilted = true;
      damaged++;
    }
  }
  if (damaged > 0) {
    showMsg(`💀 Something moved through the cleared zone overnight. ${damaged} crop${damaged > 1 ? 's' : ''} wilted. The Hollowed are still watching.`);
  }
