  const p=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(x,y,w,h);};
  const D=HAT[0],M=HAT[1],L=HAT[2];
  const band=shadeColor(D,-15);
  if(dir==='down'||dir==='up'){
    // Crown: 10w × 6h, centered on sx
    p(sx-5,by-39,10,1,B);
    p(sx-5,by-39,10,6,B); p(sx-4,by-39,8,5,M); p(sx-3,by-38,5,3,L);
