const HC_W = 60;

function setHCT(x,y,t){ if(x>=0&&x<HC_W&&y>=0&&y<HC_H) hcMap[y*HC_W+x]=t; }

const TL = { GRASS:0, DIRT:1, STONE:2, WATER:3, SAND:4, ROAD:5,
  FARM_DRY:6, FARM_TILLED:7, FARM_WATERED:8, BUILDING:9, WALL:10,
  TREE:11, MINE:12, SIGN:13, DEEP_WATER:14, BUSH:15, ROCK:16,
  FLOWERS:17, TOWN_FLOOR:18, CRATE:19, FENCE:20, WELL:21,
  BARN_CLOSED:22, BARN_OPEN:23, FENCE_GATE:24, FEED_TROUGH:25, PEN_FLOOR:26,
  // Mine interior tiles
  MINE_FLOOR:27, MINE_WALL:28, COAL_VEIN:29, COPPER_VEIN:30,
  IRON_VEIN:31, GOLD_VEIN:32, CRYSTAL_VEIN:33, MINE_EXIT:34, MINE_SHAFT_DOWN:35, MINE_SHAFT_UP:36,
  WORKBENCH:37, FORGE:38, FISHING_SPOT:39, CAMPFIRE:40, BADLANDS_PORTAL:41, SPRINKLER:42,
  // Floor 4 — The Unmapped
  SILVER_VEIN:43, SINGING_VEIN:44, HIDDEN_SHAFT:45, HOBO_PORTAL:46, OCEAN_PORTAL:47 };

const HC = {
  DIRT:     TL.DIRT,
  GRASS:    TL.GRASS,
  STONE:    TL.STONE,
  ROAD:     TL.ROAD,
  WATER:    TL.WATER,
  CAMPFIRE: TL.CAMPFIRE,
  CRATE:    TL.CRATE,
  WELL:     TL.WELL,
  TREE:     TL.TREE,
  BUSH:     TL.BUSH,
  ROCK:     TL.ROCK,
  FENCE:    TL.FENCE,
  BUILDING: TL.TOWN_FLOOR, // lean-to floors
  WALL:     TL.WALL,
  EXIT:     99, // south exit marker
};

const hcMap = new Uint8Array(HC_W * HC_H);

function buildHoboCamp() {
  // Base — patchy dirt and grass only (no STONE/BUSH in base — those are placed explicitly)
  for(let y=0;y<HC_H;y++) for(let x=0;x<HC_W;x++){
    const n=Math.random();
    setHCT(x,y, n<.55?TL.DIRT:TL.GRASS);
  }

  // Water — creek along north edge (y=2,3) — placed BEFORE path so bridge overwrites
  for(let x=0;x<HC_W;x++) setHCT(x,2,TL.WATER);
  for(let x=0;x<HC_W;x++) setHCT(x,3,TL.WATER);
  // y=0,1 — open dirt approach from portal
  for(let x=0;x<HC_W;x++) setHCT(x,0,TL.DIRT);
  for(let x=0;x<HC_W;x++) setHCT(x,1,TL.DIRT);

  // Main north-south road — runs full height, bridge overwrites creek
  for(let y=0;y<HC_H;y++) for(let x=27;x<32;x++) setHCT(x,y,TL.ROAD);
