    ctx.beginPath(); ctx.arc(220, 58, r, 0, Math.PI*2); ctx.fill();
  });
  // Mesa silhouettes
  function mesa(pts, col) {
    ctx.fillStyle = col; ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
