    const goldColor = e.goldDelta >= 0 ? '#80d040' : '#e07050';
    const goldStr = e.goldDelta >= 0 ? `+$${e.goldDelta.toLocaleString()}` : `-$${Math.abs(e.goldDelta).toLocaleString()}`;
    const snap = e.snapshot || {};

    // Activity chips
