const badlandsMap = new Uint8Array(BL_W * BL_H);

function buildBadlandsNodes() {
  for(let y=0;y<BL_H;y++) for(let x=0;x<BL_W;x++) {
    const t=getBLT(x,y);
    const def=BL_NODE_DEFS.find(d=>d.tile===t);
    if(def) badlandsNodes[x+','+y]={ x, y, def, depleted:false, respawnDay:0 };
  }
}
