        o.connect(g); g.connect(ctx.destination);
        o.type='sawtooth'; o.frequency.setValueAtTime(180,t);
        o.frequency.exponentialRampToValueAtTime(60,t+.1);
        g.gain.setValueAtTime(0.12*vol,t);
