const economy = {
  prices:     resetPrices(),
  seedPrices: { carrot:3, corn:7, pumpkin:14, glowroot:28, tomato:5, dustwheat:11, sunblossom:40, pepper:4, melon:18, potato:4, lavender:15, cactusFruit:12, blueberry:3, garlic:4, strawberry:8, onion:6, watermelon:22, rosehip:18, moonshroom:14 },
  mult:       resetMult(),
  event: null, evDaysLeft: 0,
  hist: resetHist(),
};

const BASE_PRICES = { carrot:14, corn:34, pumpkin:68, glowroot:140, tomato:25, dustwheat:55, sunblossom:200, pepper:20, melon:90, potato:18, lavender:75, cactusFruit:55, blueberry:16, garlic:22, strawberry:38, onion:30, watermelon:110, rosehip:85, moonshroom:70, stone:6, wood:10, herb:20, egg:12, wool:28, milk:45, pork:60, rabbitFur:35, goatMilk:55, horseshoe:80, banditScarf:30, wolfPelt:45, burrowerCarapace:22, raiderBadge:90, snakeFang:18, scorpionStinger:200, coyoteHide:38, coal:12, copperOre:28, ironOre:55, goldOre:130, crystal:280, copperBar:72, ironBar:145, goldBar:340, torch:8, woolBlanket:90, copperFitting:55, ironSpike:48, leatherStrip:38, plank:8, rope:22, cloth:18, pepperStew:65, potatoMash:45, berryJam:38, lavenderTea:50, porkRoast:95, goatCheese:75, garlicBread:55, watermelonSlice:60, rosehipTonic:110, mushroomSoup:130, strawberryPreserves:65, fishStew:90,
  // Overworld pond fish
  commonFish:18, perch:32, catfish:55, bassfish:70, sunfish:28, snapperTurtle:45, junkBoot:2,
  // Hobo camp creek fish
  crawdad:22, mudcat:40, rustNail:3, oldFlask:35, surveyorCompass:180, deedFragment:280,
  // Kept for legacy saves
  goldenfish:220, ancientCoin:150, singingStone:480,
  // Ocean cooked meals
  saltChowder:110, crabBisque:125, grilledGrouper:145, swordfishSteak:220, oysterPlate:75 };

function resetPrices() {
  const p = {};
  for (const k in BASE_PRICES) {
    if (k !== 'junkBoot') p[k] = BASE_PRICES[k];
  }
  return p;
}

function resetMult() {
  const m = {};
  for (const k in BASE_PRICES) m[k] = 1;
  return m;
}

function resetHist() {
  const h = {};
  for (const k in BASE_PRICES) if (k !== 'junkBoot') h[k] = [];
  return h;
}

function renderHistory(body) {
  const items = [
    {id:'carrot',name:'Carrot',icon:'🥕'},{id:'corn',name:'Corn',icon:'🌽'},
    {id:'pumpkin',name:'Pumpkin',icon:'🎃'},{id:'glowroot',name:'Glowroot',icon:'✨'},
  ];
  let h = `<div style="font-size:9px;color:#6a5020;margin-bottom:10px">PRICE HISTORY — last 10 days</div>`;
  for (const item of items) {
    const hist = economy.hist[item.id] || [];
    const cur  = economy.prices[item.id];
    const all  = [...hist, cur];
    const mx   = Math.max(...all, 1);
    const W=220, H=40;
    let pts = '';
    all.forEach((p,i) => { const x=i/(all.length-1||1)*W; const y=H-(p/mx*H*.9); pts+=(i===0?'M':'L')+x.toFixed(1)+','+y.toFixed(1); });
    const col = cur>(BASE_PRICES[item.id]||1)*1.1 ? '#60e060' : cur<(BASE_PRICES[item.id]||1)*.9 ? '#e06060' : '#d4b870';
    h += `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;padding:7px;background:rgba(255,255,255,.02);border-radius:3px;">
      <span style="font-size:14px;width:20px">${item.icon}</span>
      <span style="font-size:10px;color:#c0a060;width:60px">${item.name}</span>
      <svg width="${W}" height="${H}" style="flex-shrink:0"><path d="${pts}" stroke="${col}" stroke-width="1.5" fill="none"/></svg>
      <span style="font-size:11px;color:${col};min-width:34px;text-align:right">$${cur}</span>
    </div>`;
  }
  body.innerHTML = h;
}
