function updateParticles(dt) {
  for (let i=gameState.particles.length-1;i>=0;i--) {
    const p=gameState.particles[i]; p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=75*dt; p.life-=dt*1.3;
    if (p.life<=0) gameState.particles.splice(i,1);
  }
}
