  // Any dirt tile inside the farm fence (x=2..32, y=2..32) is farmable,
  // as long as it's not occupied by a solid structure or placed feature.
  if (tx < 2 || tx > 32 || ty < 2 || ty > 32) return false;
  const t = getT(tx, ty);
  if (SOLID.has(t)) return false;
  if (t === TL.BUILDING || t === TL.ROAD || t === TL.CAMPFIRE) return false;
  return true;
}

function plotKey(tx,ty){ return tx+','+ty; }

function getT(x,y){ if(x<0||x>=MAP_W||y<0||y>=MAP_H) return TL.STONE; return tileMap[y*MAP_W+x]; }

const SOLID = new Set([2,3,9,10,11,14,15,16,19,20,21,22,28,37,38,42]);

function farmhandDoRevive() {
  const targets = Object.entries(plots).filter(([,p]) => p.wilted);
  const cost = Math.max(8, targets.length * 8);
  if (player.gold < cost) { showMsg(`⚠️ Need $${cost} to hire.`); return; }
  player.gold -= cost;
  let done = 0;
  for (const [k, p] of targets) {
    p.wilted = false; p.watered = true; p.wateredToday = true; p.growthProgress = Math.max(0, p.growthProgress - 0.1);
    const [tx,ty] = k.split(',').map(Number);
    setT(tx, ty, TL.FARM_WATERED);
    done++;
  }
  showMsg(`🧑‍🌾 Jed revived ${done} wilted crop${done>1?'s':''}. ($${cost} paid)`);
  refreshFarmhandUI();
}
