    pens.forEach(pen => {
      const penCx = (pen.x + pen.w/2)*T, penCy = (pen.y + pen.h/2)*T;
      if (Math.hypot(e.x - penCx, e.y - penCy) < 3*T) {
        pen.animals.forEach(aid => {
          const a = getAnimalById(aid);
          if (a && a.state !== 'panic') { a.state = 'panic'; a.panicTimer = 12; }
        });
      }
    });
  });

