    ctx.closePath(); ctx.fill();
  } else if (t === TL.SILVER_VEIN) {
    ctx.fillStyle='#1e2028'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    const sp = 0.5+Math.sin(Date.now()*.002+sx*.7)*0.3;
