    ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.rect(sx+4,sy+4,T-8,T-8); ctx.stroke();
    // Faint inner glow
    ctx.fillStyle=`rgba(180,120,240,${vp*0.2})`;
    ctx.fillRect(sx+8,sy+8,T-16,T-16);
  }
}
