const T = 32;

function getEffectiveSlotCount() { return player._slotCount || INV_SIZE; }

const inventory = {
  slots: Array(INV_MAX_SIZE).fill(null),  // allocate max; use getEffectiveSlotCount() for access
  seeds: { carrotSeed:0, cornSeed:0, pumpkinSeed:0, glowrootSeed:0, tomatoSeed:0, dustwheatSeed:0, sunblossomSeed:0 },
  water: 10, waterCap: 10,
  get totalWeight() {
    let w = 0;
    const _eff = getEffectiveSlotCount ? getEffectiveSlotCount() : INV_SIZE;
    for (let _twi=0;_twi<_eff;_twi++) { const s=this.slots[_twi]; if(s) w+=((ITEMS[s.itemId]&&ITEMS[s.itemId].weight)||0)*s.qty; }
    return Math.round(w*10)/10;
  }
};

const INV_SIZE = 32;

const INV_MAX_SIZE = 56;

function canCraftRecipe(recipe) {
  // Station check
  if (recipe.station === 'forge' && !player._mineForge) return { ok:false, reason:'Requires Mine Forge upgrade.' };
  if (recipe.station === 'workbench') return { ok:false, reason:'Requires a Workbench (coming soon).' };
  // Stamina check
  if (player.stamina < recipe.staminaCost) return { ok:false, reason:`Need ${recipe.staminaCost} stamina.` };
  // Ingredient check
  for (const ing of recipe.ingredients) {
    const have = countItem(ing.id);
    if (have < ing.qty) {
      const name = ITEMS[ing.id]?.name || ing.id;
      return { ok:false, reason:`Need ${ing.qty}× ${name} (have ${have}).` };
    }
  }
  return { ok:true, reason:'' };
}
