            onmouseover="this.style.background='rgba(180,140,60,.25)'" onmouseout="this.style.background='rgba(180,140,60,.12)'">
            PAY $${a.toLocaleString()}
          </button>`).join('')}
        ${player.gold > 0 && player.gold < debt ? `
          <button onclick="payDebt(${player.gold})" style="padding:7px 16px;font-size:10px;font-family:'Courier New',monospace;cursor:pointer;border-radius:3px;background:rgba(80,160,60,.1);border:1px solid rgba(80,160,60,.4);color:#80d060"
            onmouseover="this.style.background='rgba(80,160,60,.22)'" onmouseout="this.style.background='rgba(80,160,60,.1)'">
            PAY ALL ($${player.gold.toLocaleString()})
          </button>` : ''}
        ${player.gold >= debt ? `
          <button onclick="payDebt(${debt})" style="padding:7px 16px;font-size:10px;font-family:'Courier New',monospace;cursor:pointer;border-radius:3px;background:rgba(60,200,60,.15);border:1px solid rgba(60,200,60,.6);color:#80ff80;font-weight:bold"
            onmouseover="this.style.background='rgba(60,200,60,.28)'" onmouseout="this.style.background='rgba(60,200,60,.15)'">
            ✓ CLEAR ALL DEBT ($${debt.toLocaleString()})
          </button>` : ''}
      </div>`;
  } else {
    h += `<div style="text-align:center;padding:20px;font-size:12px;color:#60d040;font-family:'Courier New',monospace;letter-spacing:.08em">✓ DEBT CLEARED — THIS LAND IS YOURS</div>`;
  }

  // Weekly payment schedule
  h += `<div style="font-size:9px;color:#6a5020;margin-bottom:6px;letter-spacing:.04em">WEEKLY BILL SCHEDULE</div>
    <div style="max-height:160px;overflow-y:auto;margin-bottom:12px">`;
  const allBills = [];
  for (let w = 1; w <= Math.max(currentWeek + 3, 8); w++) {
    const amt = getWeeklyBillAmount(w);
    const existing = weeklyBills.find(b => b.week === w);
    const isPaid = (existing && existing.paid) || false;
    const isBilled = !!existing;
