  for(let i=0;i<60;i++){ const wx=2+Math.floor(Math.random()*(MAP_W-4)),wy=38+Math.floor(Math.random()*34); if(getT(wx,wy)!==TL.TREE) setT(wx,wy,TL.ROCK); }
  for(let y=58;y<76;y++) for(let x=58;x<78;x++) setT(x,y,TL.STONE);
