const resourceNodes = {};

const gameState = {
  day:1, timeOfDay:6*60, dayLength:24*60, daySpeed:2.5,
  isNight:false, zone:'Farm',
  camera:{x:0,y:0}, season:'Dry Summer', particles:[],
  stormActive:false, stormSheltering:false,
  inMine:false, mineFloor:0,
};

const MINE_FLOORS = 3;

const mineResourceNodes = [{}, {}, {}];

function setMineT(floor, x, y, t) {
  if (x >= 0 && x < MINE_W && y >= 0 && y < MINE_H)
    mineFloorMaps[floor][y * MINE_W + x] = t;
}

const MINE_W = 48;

const MINE_H = 48;

const mineFloorMaps = [
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
];

function respawnNodes() {
  for (const key in resourceNodes) {
    const n = resourceNodes[key];
    if (n.depleted && n.respawnDay !== Infinity && gameState.day >= n.respawnDay) {
      n.depleted = false;
    }
  }
  // Also respawn mine nodes
  for (let fl = 0; fl < MINE_FLOORS; fl++) {
    for (const key in mineResourceNodes[fl]) {
      const n = mineResourceNodes[fl][key];
      if (n.depleted && gameState.day >= n.respawnDay) {
        n.depleted = false;
        setMineT(fl, n.x, n.y, n.def.tile);
      }
    }
  }
}
