    if (getMineT(fl, cx, cy) !== node.def.tile) { node.depleted = true; continue; }
    return { key, node };
  }
  return null;
}

function getEffectiveMiningMult(type) {
  if (type === 'stone') return player._miningMult || 1;
  if (type === 'wood')  return player._woodMult   || 1;
  return 1;
}

function checkToolForNode(nodeDef) {
  const loot = nodeDef.loot;
  if (loot === 'stone') {
    if (!hasPickaxe()) return { ok:false, msg:'⛏ You need a Pickaxe to mine stone — buy one at the market [M] → Upgrades.' };
  }
  if (loot === 'wood') {
    if (!hasAxe()) return { ok:false, msg:'🪓 You need an Axe to chop wood — buy one at the market [M] → Upgrades.' };
  }
  // herbs: any tool/item is fine
  return { ok:true };
}

function getGatherDuration(type) {
  if (type === 'stone') return Math.max(0.25, (player._gatherCd || 1.0) * 2.2);
  if (type === 'wood')  return Math.max(0.25, (player._woodCd  || 1.0) * 2.2);
  if (type === 'herb')  return 0.9;  // herbs are quick regardless
  return 1.0;
}

function getNearbyNode() {
  const px = Math.floor(player.x/T), py = Math.floor(player.y/T);
  // Prioritise the tile the player is facing, then full adjacent ring
  const nodeOffs = { down:[0,1], up:[0,-1], left:[-1,0], right:[1,0] };
  const [ox,oy] = nodeOffs[player.facing]||[0,1];
  const orderedChecks = [
    [px+ox,   py+oy  ],   // 1 tile ahead
    [px+ox*2, py+oy*2],   // 2 tiles ahead
    [px,      py     ],   // own tile
    [px+1,py],[px-1,py],[px,py+1],[px,py-1], // full ring
    [px+1,py+1],[px-1,py-1],[px+1,py-1],[px-1,py+1],
  ];
  for (const [cx,cy] of orderedChecks) {
    const key = cx+','+cy;
    const node = resourceNodes[key];
    if (!node || node.depleted) continue;
    // Verify the tile on the map still matches what this node expects
    if (getT(cx, cy) !== node.def.tile) { node.depleted = true; continue; }
    return { key, node };
  }
  return null;
}

const MINE_W = 48;

