let enemies = [];

const T = 32;

const canvas = document.getElementById('gameCanvas');

const ctx = canvas.getContext('2d');

const gameState = {
  day:1, timeOfDay:6*60, dayLength:24*60, daySpeed:2.5,
  isNight:false, zone:'Farm',
  camera:{x:0,y:0}, season:'Dry Summer', particles:[],
  stormActive:false, stormSheltering:false,
  inMine:false, mineFloor:0,
};

function drawEnemies(cx, cy) {
  for (const e of enemies) {
    const sx = e.x - cx, sy = e.y - cy;
    if (sx < -T*2 || sx > canvas.width+T*2 || sy < -T*2 || sy > canvas.height+T*2) continue;

    if (e.hidden) {
      // Burrower underground — draw subtle ground ripple
      ctx.globalAlpha = 0.3 + Math.sin(Date.now()*0.004)*0.1;
      ctx.fillStyle = '#604030';
      ctx.beginPath(); ctx.ellipse(sx, sy+4, 10, 5, 0, 0, Math.PI*2); ctx.fill();
      ctx.globalAlpha = 1;
      continue;
    }

    // Flash white on hit
    ctx.globalAlpha = e.flashTimer > 0 ? 0.5 : 1;

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.beginPath(); ctx.ellipse(sx, sy+8, 8, 4, 0, 0, Math.PI*2); ctx.fill();

    ctx.globalAlpha = e.flashTimer > 0 ? 0.5 : 1;
    const eFlash = e.flashTimer > 0;

    if (e.type === 'bandit') {
      // Dark vest body
      ctx.fillStyle = eFlash ? '#fff' : '#503828';
      ctx.fillRect(sx-7, sy-10, 14, 15);
      // Bandana-head
      ctx.fillStyle = eFlash ? '#fff' : '#d4a060';
      ctx.fillRect(sx-5, sy-19, 10, 10);
      ctx.fillStyle = eFlash ? '#fff' : '#c03020'; // red bandana
      ctx.fillRect(sx-5, sy-15, 10, 4);
      // Hat brim
      ctx.fillStyle = eFlash ? '#fff' : '#302010';
      ctx.fillRect(sx-7, sy-20, 14, 3);
      ctx.fillRect(sx-4, sy-26, 8, 7);
      // Weapon glint
      ctx.fillStyle = eFlash ? '#fff' : '#c0c0c0';
      ctx.fillRect(sx+7, sy-8, 2, 9);
      // Legs
      ctx.fillStyle = eFlash ? '#fff' : '#302818';
      ctx.fillRect(sx-6, sy+5, 5, 8); ctx.fillRect(sx+1, sy+5, 5, 8);

    } else if (e.type === 'wolf') {
      // Low crouching body
      ctx.fillStyle = eFlash ? '#fff' : '#707080';
      ctx.beginPath(); ctx.ellipse(sx, sy+2, 9, 6, 0, 0, Math.PI*2); ctx.fill();
      // Darker back stripe
      ctx.fillStyle = eFlash ? '#fff' : '#404050';
      ctx.fillRect(sx-5, sy-2, 10, 4);
      // Head — pushed forward (facing right by default)
      ctx.fillStyle = eFlash ? '#fff' : '#808090';
      ctx.beginPath(); ctx.ellipse(sx+10, sy-2, 7, 6, 0.3, 0, Math.PI*2); ctx.fill();
      // Snout
      ctx.fillStyle = eFlash ? '#fff' : '#606070';
      ctx.beginPath(); ctx.ellipse(sx+16, sy, 4, 3, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#181818';
      ctx.beginPath(); ctx.arc(sx+19, sy-1, 1.2, 0, Math.PI*2); ctx.fill(); // nose
      // Eyes glow yellow at night
      ctx.fillStyle = gameState.isNight ? '#d0e020' : '#d0c080';
      ctx.beginPath(); ctx.arc(sx+12, sy-4, 2, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.arc(sx+12, sy-4, 1, 0, Math.PI*2); ctx.fill();
      // Ears
      ctx.fillStyle = eFlash ? '#fff' : '#606070';
      ctx.beginPath(); ctx.moveTo(sx+9,sy-7); ctx.lineTo(sx+7,sy-13); ctx.lineTo(sx+13,sy-9); ctx.fill();
      // Tail
      ctx.strokeStyle = eFlash ? '#fff' : '#707080'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(sx-9, sy); ctx.quadraticCurveTo(sx-16, sy-4, sx-14, sy-10); ctx.stroke();
      // Legs
      ctx.fillStyle = eFlash ? '#fff' : '#606070';
      ctx.fillRect(sx-4, sy+6, 3, 7); ctx.fillRect(sx+2, sy+6, 3, 7);

    } else if (e.type === 'burrower') {
      // Segmented insect body
      ctx.fillStyle = eFlash ? '#fff' : '#604828';
      ctx.beginPath(); ctx.ellipse(sx, sy, 8, 6, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = eFlash ? '#fff' : '#806040';
      ctx.beginPath(); ctx.ellipse(sx, sy-5, 6, 4, 0, 0, Math.PI*2); ctx.fill();
      // Head with mandibles
      ctx.fillStyle = eFlash ? '#fff' : '#503818';
      ctx.beginPath(); ctx.ellipse(sx, sy-11, 5, 4, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = eFlash ? '#fff' : '#c08030';
      ctx.beginPath(); ctx.moveTo(sx-6, sy-12); ctx.lineTo(sx-10, sy-16); ctx.lineTo(sx-4, sy-13); ctx.fill();
      ctx.beginPath(); ctx.moveTo(sx+6, sy-12); ctx.lineTo(sx+10, sy-16); ctx.lineTo(sx+4, sy-13); ctx.fill();
      // Red eyes
      ctx.fillStyle = '#e02020';
      ctx.beginPath(); ctx.arc(sx-3, sy-12, 1.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(sx+3, sy-12, 1.5, 0, Math.PI*2); ctx.fill();
      // Legs
      ctx.strokeStyle = eFlash ? '#fff' : '#604828'; ctx.lineWidth = 1.5;
      for(let i=-1;i<=1;i+=1){ ctx.beginPath(); ctx.moveTo(sx-8, sy+i*3); ctx.lineTo(sx-14, sy+i*3-3); ctx.stroke(); ctx.beginPath(); ctx.moveTo(sx+8, sy+i*3); ctx.lineTo(sx+14, sy+i*3-3); ctx.stroke(); }

    } else if (e.type === 'raider') {
      // Bigger, heavily armoured bandit
      ctx.fillStyle = eFlash ? '#fff' : '#401818';
      ctx.fillRect(sx-9, sy-12, 18, 18);
      // Armour plate
      ctx.fillStyle = eFlash ? '#fff' : '#606870';
      ctx.fillRect(sx-8, sy-10, 16, 10);
      // Head / helmet
      ctx.fillStyle = eFlash ? '#fff' : '#d4a060';
      ctx.fillRect(sx-6, sy-21, 12, 10);
      ctx.fillStyle = eFlash ? '#fff' : '#505860'; // metal helmet
      ctx.fillRect(sx-7, sy-23, 14, 5);
      ctx.fillRect(sx-7, sy-18, 14, 3); // visor band
      // Axe
      ctx.fillStyle = eFlash ? '#fff' : '#c0c0c0';
      ctx.fillRect(sx+9, sy-15, 3, 14);
      ctx.fillRect(sx+9, sy-16, 7, 6);
      // Legs
      ctx.fillStyle = eFlash ? '#fff' : '#401818';
      ctx.fillRect(sx-7, sy+6, 6, 9); ctx.fillRect(sx+1, sy+6, 6, 9);
      // Boots
      ctx.fillStyle = eFlash ? '#fff' : '#302010';
      ctx.fillRect(sx-7, sy+14, 6, 4); ctx.fillRect(sx+1, sy+14, 6, 4);

    } else if (e.type === 'snake') {
      // S-curve body
      const wob = Math.sin(Date.now()*.004+e.id)*3;
      ctx.strokeStyle = eFlash ? '#fff' : '#508038'; ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(sx-12, sy+4);
      ctx.quadraticCurveTo(sx-4, sy-6+wob, sx+4, sy+4);
      ctx.quadraticCurveTo(sx+10, sy+10-wob, sx+14, sy+2);
      ctx.stroke();
      // Head
      ctx.fillStyle = eFlash ? '#fff' : '#406830';
      ctx.beginPath(); ctx.ellipse(sx+14, sy+2, 6, 4, 0.4, 0, Math.PI*2); ctx.fill();
      // Forked tongue
      ctx.strokeStyle = '#e03030'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(sx+20, sy+2); ctx.lineTo(sx+24, sy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(sx+20, sy+2); ctx.lineTo(sx+24, sy+4); ctx.stroke();
      // Eye
      ctx.fillStyle = '#d0e020';
      ctx.beginPath(); ctx.arc(sx+15, sy, 2, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.arc(sx+15, sy, 0.8, 0, Math.PI*2); ctx.fill();

    } else {
      // Generic fallback
      ctx.fillStyle = eFlash ? '#fff' : e.def.color;
      ctx.fillRect(sx-7, sy-10, 14, 14);
      ctx.fillStyle = eFlash ? '#fff' : '#d4a870';
      ctx.fillRect(sx-5, sy-18, 10, 9);
    }

    ctx.globalAlpha = 1;

    // HP bar
    const hpPct = e.hp / e.maxHp;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(sx-12, sy-26, 24, 3);
    ctx.fillStyle = hpPct > 0.5 ? '#60d040' : hpPct > 0.25 ? '#d0a020' : '#d03020';
    ctx.fillRect(sx-12, sy-26, 24*hpPct, 3);
  }
  ctx.globalAlpha = 1;
}
