  const tx = Math.floor(player.x/T), ty = Math.floor(player.y/T);
  // Check tiles adjacent to player
  const checks = [[tx,ty],[tx,ty+1],[tx,ty-1],[tx+1,ty],[tx-1,ty],[tx+2,ty],[tx-2,ty],[tx,ty+2]];
  for (const [cx,cy] of checks) {
