function drawMineTile(t, sx, sy) {
  const c = MINE_TILE_COLORS[t] || MINE_TILE_COLORS[TL.MINE_WALL];
  ctx.fillStyle = c[0]; ctx.fillRect(sx, sy, T, T);
  if (t === TL.MINE_FLOOR) {
    if (Math.random() < 0.05) { ctx.fillStyle = '#4a4038'; ctx.fillRect(sx+4,sy+4,3,2); }
  } else if (t === TL.MINE_WALL) {
    ctx.fillStyle='#0e0c0b'; ctx.fillRect(sx+2,sy+2,T-4,T-4);
    ctx.fillStyle='#221e1c'; ctx.fillRect(sx+4,sy+4,T-8,T-8);
  } else if (t === TL.COAL_VEIN) {
    ctx.fillStyle='#1a1818'; ctx.fillRect(sx+4,sy+4,T-8,T-8);
    ctx.fillStyle='#302a28'; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,6,0,Math.PI*2); ctx.fill();
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.fillText('🪨',sx+T/2,sy+T/2+5);
  } else if (t === TL.COPPER_VEIN) {
    ctx.fillStyle='#5a2808'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    ctx.fillStyle='#c06020'; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,5,0,Math.PI*2); ctx.fill();
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.fillText('🟤',sx+T/2,sy+T/2+5);
  } else if (t === TL.IRON_VEIN) {
    ctx.fillStyle='#252830'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    ctx.fillStyle='#708090'; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,5,0,Math.PI*2); ctx.fill();
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.fillText('⚫',sx+T/2,sy+T/2+5);
  } else if (t === TL.GOLD_VEIN) {
    ctx.fillStyle='#503010'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    const glow = 0.5+Math.sin(Date.now()*.003)*0.3;
    ctx.fillStyle=`rgba(220,160,20,${glow})`; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,5,0,Math.PI*2); ctx.fill();
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.fillText('🟡',sx+T/2,sy+T/2+5);
  } else if (t === TL.CRYSTAL_VEIN) {
    ctx.fillStyle='#0e0c20'; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    const pulse = 0.4+Math.sin(Date.now()*.005+sx)*0.4;
    ctx.fillStyle=`rgba(80,140,240,${pulse})`; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,7,0,Math.PI*2); ctx.fill();
    ctx.font='14px serif'; ctx.textAlign='center'; ctx.fillText('💎',sx+T/2,sy+T/2+5);
  } else if (t === TL.MINE_EXIT) {
    ctx.fillStyle='#1a3018'; ctx.fillRect(sx+2,sy+2,T-4,T-4);
    ctx.fillStyle='#40a840'; ctx.fillRect(sx+T/2-3,sy+2,6,T-4);
    ctx.font='16px serif'; ctx.textAlign='center'; ctx.fillText('🚪',sx+T/2,sy+T/2+6);
