    BGM.masterGain = ctx.createGain();
    BGM.masterGain.gain.value = bgmMasterLevel();
    BGM.masterGain.connect(ctx.destination);
  }
  if (!BGM.reverbInput) {
    try {
      // Simple delay reverb
      const rv = ctx.createGain(); rv.gain.value = 0.16; rv.connect(BGM.masterGain);
      const d1 = ctx.createDelay(1); d1.delayTime.value = 0.13;
      const fb = ctx.createGain(); fb.gain.value = 0.25;
