      const rv = ctx.createGain(); rv.gain.value = 0.16; rv.connect(BGM.masterGain);
      const d1 = ctx.createDelay(1); d1.delayTime.value = 0.13;
      const fb = ctx.createGain(); fb.gain.value = 0.25;
      d1.connect(fb); fb.connect(d1); d1.connect(rv);
      BGM.reverbInput = d1;
    } catch(e) {}
  }
}

function bgmCtx() { return getDahCtx(); }

function bgmMasterLevel() { return Math.max(0.12, (_soundVol||0.8)*0.38); }

function scheduleDayLoop(startTime) {
  if (!BGM.running || BGM.mode !== 'day') return;
  bgmEnsureSetup();
  const V=0.60, BPM=80, B=60/BPM, BAR=B*4, BARS=8, t=startTime;

  // I-IV-V-I chord roots for bass and strum
  const bass_r = [N.D2, N.G2, N.A2, N.D2, N.D2, N.G2, N.A2, N.D2];
  const chord_r= [N.D3, N.G3, N.A3, N.D3, N.D3, N.G3, N.A3, N.D3];

  for (let bar=0; bar<BARS; bar++) {
    const bT=t+bar*BAR;
    // BOOM on beats 1 and 3
    wBass(bass_r[bar],       bT,         0.72, V*0.88);
    wBass(bass_r[bar]*1.5,   bT+B*2,     0.60, V*0.65);
    // CHICK: chord strum on beats 2 and 4
    strum(chord_r[bar], bT+B,     V*0.52);
    strum(chord_r[bar], bT+B*3,   V*0.46);
    // Snare ghost
    perc(bT+B,   V*0.28, true);
    perc(bT+B*3, V*0.24, true);
    // Light hi-hat 8th notes
    for(let e=0;e<8;e++) perc(bT+e*B*0.5, V*0.10, false);
  }

  // Melody — singable D major tune, 8 bars
  // [bar, beat, freq, dur_in_beats]
  const mel = [
    [0,0,N.D4,1],[0,1,N.E4,0.5],[0,1.5,N.Fs4,0.5],[0,2,N.A4,2],
    [1,0,N.A4,0.5],[1,0.5,N.G4,0.5],[1,1,N.Fs4,0.5],[1,1.5,N.E4,2.5],
    [2,0,N.G4,0.75],[2,0.75,N.Fs4,0.75],[2,1.5,N.E4,0.5],[2,2,N.D4,2],
    [3,0,N.D4,0.5],[3,0.5,N.E4,0.5],[3,1,N.D4,3],
    [4,0,N.Fs4,1],[4,1,N.A4,0.5],[4,1.5,N.B4,0.5],[4,2,N.A4,2],
    [5,0,N.G4,0.5],[5,0.5,N.Fs4,1],[5,1.5,N.E4,2.5],
    [6,0,N.E4,0.5],[6,0.5,N.Fs4,0.5],[6,1,N.G4,0.5],[6,1.5,N.A4,2.5],
    [7,0,N.Fs4,0.75],[7,0.75,N.E4,0.75],[7,1.5,N.D4,2.5],
  ];
  for (const [bar,beat,freq,db] of mel)
    banjo(freq, t+bar*BAR+beat*B, db*B*0.86, V*0.75);

  const dur=BARS*BAR;
  BGM.seqTimer = setTimeout(()=>scheduleDayLoop(t+dur), (dur-0.4)*1000);
}

function scheduleNightLoop(startTime) {
  if (!BGM.running || BGM.mode !== 'night') return;
  bgmEnsureSetup();
  const V=0.52, BPM=56, B=60/BPM, BAR=B*4, BARS=4, t=startTime;

  const mel = [
    [0,0,N.Am3,3],[0,3.5,N.C4,0.5],
    [1,0,N.Em4,2],[1,2.5,N.C4,1.5],
    [2,0,N.Am3,2.5],[2,3,N.Em3,1],
    [3,0,N.Am2,4],
  ];

  for (let bar=0; bar<BARS; bar++) {
    const bT=t+bar*BAR;
    wBass(N.Am2, bT, 1.1, V*0.75);
    if (bar%2===0) wBass(N.Em3, bT+B*2, 0.9, V*0.48);
    if (bar%2===1) strum(N.Am3, bT+B*2, V*0.28);
    // wind texture
    try {
      const wc=bgmCtx(), ws=Math.floor(wc.sampleRate*BAR);
      const wb=wc.createBuffer(1,ws,wc.sampleRate);
      const wd=wb.getChannelData(0);
      for(let i=0;i<ws;i++) wd[i]=(Math.random()*2-1)*Math.sin(i/ws*Math.PI);
      const wsrc=wc.createBufferSource(); wsrc.buffer=wb;
      const wf=wc.createBiquadFilter(); wf.type='bandpass'; wf.frequency.value=280+Math.random()*180; wf.Q.value=0.45;
      const wg=wc.createGain(); wg.gain.value=V*0.055;
      wsrc.connect(wf); wf.connect(wg); wg.connect(BGM.masterGain);
      wsrc.start(bT); wsrc.stop(bT+BAR+0.1);
    } catch(e) {}
  }
  for (const [bar,beat,freq,db] of mel)
    banjo(freq, t+bar*BAR+beat*B, db*B*0.82, V*0.62);

  const dur=BARS*BAR;
  BGM.seqTimer = setTimeout(()=>scheduleNightLoop(t+dur), (dur-0.4)*1000);
}

function scheduleCombatLoop(startTime) {
  if (!BGM.running || BGM.mode !== 'combat') return;
  bgmEnsureSetup();
  const V=0.56, BPM=96, B=60/BPM, BAR=B*4, BARS=4, t=startTime;

  for (let bar=0; bar<BARS; bar++) {
    const bT=t+bar*BAR;
    wBass(N.Am2,   bT,        0.55, V*0.88);
    wBass(N.D2*2,  bT+B*1.5,  0.45, V*0.62);
    wBass(N.Am2,   bT+B*2,    0.50, V*0.72);
    wBass(N.Em3,   bT+B*3,    0.45, V*0.58);
    perc(bT+B,   V*0.48, true);
    perc(bT+B*3, V*0.44, true);
    for(let e=0;e<8;e++) perc(bT+e*B*0.5, V*0.13, false);
    banjo(N.C4,  bT+B*0.5, B*0.28, V*0.44);
    banjo(N.Em4*0.944, bT+B*1,   B*0.28, V*0.40);
    banjo(N.C4,  bT+B*2.5, B*0.28, V*0.44);
    banjo(N.D4,  bT+B*3.5, B*0.22, V*0.38);
  }

  const dur=BARS*BAR;
  BGM.seqTimer = setTimeout(()=>scheduleCombatLoop(t+dur), (dur-0.4)*1000);
}

const SETTINGS_DEFAULTS = {
  daySpeed:    'normal',
  difficulty:  'normal',
  autoSave:    true,
  showControls:true,
  showWeight:  true,
  masterVol:   80,
  musicOn:     true,
};

function getDahCtx() {
  if (!_dahAudioCtx) _dahAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  return _dahAudioCtx;
}

let _soundVol = 0.5;

const N = {
  A2:110, D2:73.4, G2:98, E2:82.4,
  D3:147, E3:165, Fs3:185, G3:196, A3:220, B3:247,
  D4:294, E4:330, Fs4:370, G4:392, A4:440, B4:494, D5:587,
  // A minor
  C4:261.6, Am2:110, Em3:165, Am3:220, Cm4:261.6, Em4:329.6, Am4:440,
};

function wBass(freq, time, durSec, vol) {
  try {
    const ctx = bgmCtx();
    const o = ctx.createOscillator();
    const o2= ctx.createOscillator();
    const g = ctx.createGain(); const g2=ctx.createGain();
    const env=ctx.createGain();
    o.type='sine';  o.frequency.value=freq;
    o2.type='sine'; o2.frequency.value=freq*2;
    g.gain.value=0.82; g2.gain.value=0.18;
    env.gain.setValueAtTime(0,time);
    env.gain.linearRampToValueAtTime(vol, time+0.014);
    env.gain.setValueAtTime(vol*0.8, time+durSec*0.5);
    env.gain.exponentialRampToValueAtTime(0.0001, time+durSec);
    o.connect(g); o2.connect(g2); g.connect(env); g2.connect(env);
    env.connect(BGM.masterGain);
    o.start(time); o.stop(time+durSec+0.02);
    o2.start(time); o2.stop(time+durSec+0.02);
  } catch(e) {}
}

function strum(rootFreq, time, vol) {
  // major triad spread strum
  [1, 1.26, 1.498, 2].forEach((r,i) => banjo(rootFreq*r, time+i*0.016, 0.55, vol*0.42));
}

function perc(time, vol, isSnare) {
  try {
    const ctx=bgmCtx();
    const sz=Math.floor(ctx.sampleRate*0.09);
    const buf=ctx.createBuffer(1,sz,ctx.sampleRate);
    const d=buf.getChannelData(0);
    for(let i=0;i<sz;i++) d[i]=Math.random()*2-1;
    const src=ctx.createBufferSource(); src.buffer=buf;
    const f=ctx.createBiquadFilter();
    f.type=isSnare?'bandpass':'highpass';
    f.frequency.value=isSnare?220:6500; f.Q.value=isSnare?0.7:0.5;
    const g=ctx.createGain();
    g.gain.setValueAtTime(vol,time);
    g.gain.exponentialRampToValueAtTime(0.0001,time+(isSnare?0.2:0.05));
    src.connect(f); f.connect(g); g.connect(BGM.masterGain);
    src.start(time); src.stop(time+0.25);
  } catch(e) {}
}

function banjo(freq, time, durSec, vol) {
  try {
    const ctx = bgmCtx();
    const osc = ctx.createOscillator();
    const lp  = ctx.createBiquadFilter();
    const env = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.value = freq * (1+(Math.random()-0.5)*0.004);
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(2600, time);
    lp.frequency.exponentialRampToValueAtTime(900, time + durSec*0.35);
    lp.Q.value = 1.4;
    env.gain.setValueAtTime(0, time);
    env.gain.linearRampToValueAtTime(vol, time + 0.009);
    env.gain.exponentialRampToValueAtTime(vol*0.28, time + durSec*0.18);
    env.gain.exponentialRampToValueAtTime(0.0001, time + durSec);
    osc.connect(lp); lp.connect(env);
    env.connect(BGM.masterGain);
    if (BGM.reverbInput) env.connect(BGM.reverbInput);
    osc.start(time); osc.stop(time + durSec + 0.02);
  } catch(e) {}
}

let _dahAudioCtx = null;

function bgmPoll(dt) {
  if (!BGM.running) return;
  _bgmPollTimer -= dt;
  if (_bgmPollTimer > 0) return;
  _bgmPollTimer = 3;
  const h=(gameState.timeOfDay||0)/60;
  const isNight = h>=20||h<6;
  const hasCombat = isNight && enemies.some(e=>Math.hypot(player.x-e.x,player.y-e.y)<320);
  let target = isNight ? (hasCombat?'combat':'night') : 'day';
  if (BGM.mode !== target) bgmSetMode(target);
}
