      </div>
      <div style="text-align:right;flex-shrink:0">
        <div style="font-size:9px;color:#a07040;margin-bottom:3px">${oreHeld} ore · ${batchesAvail} batch${batchesAvail!==1?'es':''}</div>
        <button onclick="smeltOre('${recipe.ore}','${recipe.bar}',${recipe.oreQty},1)" style="padding:4px 10px;font-size:9px;font-family:'Courier New',monospace;cursor:pointer;border-radius:3px;background:rgba(200,100,20,.15);border:1px solid rgba(200,100,20,.${canSmelt?'5':'2'});color:${canSmelt?'#e0a030':'#604020'}" ${!canSmelt?'disabled':''}>SMELT 1</button>
        ${batchesAvail>1?`<button onclick="smeltOre('${recipe.ore}','${recipe.bar}',${recipe.oreQty},${batchesAvail})" style="margin-left:4px;padding:4px 10px;font-size:9px;font-family:'Courier New',monospace;cursor:pointer;border-radius:3px;background:rgba(200,100,20,.25);border:1px solid rgba(200,100,20,.6);color:#e0c050" ${!canSmelt?'disabled':''}>ALL (${batchesAvail})</button>`:''}
      </div>
    </div>`;
  }
  body.innerHTML = h || '<div style="color:#504020;font-size:9px;padding:12px">No ore to smelt. Mine ore first!</div>';
}
