  const rows = [
    ['Day', `${day}`],
    ['Gold', `$${player.gold} (${goldStr})`],
    ['Crops ready', `${cropsReady}`],
    ['Crops growing', `${cropsGrowing}`],
    ['Wilted', `${wilted}`],
    ['Carry weight', `${inventory.totalWeight}/${getEffectiveWeightCap()}kg`],
    ['Water', `${inventory.water}/${inventory.waterCap}`],
