  woods:[[87,110,131,155,131,110],[73,92,110,131,110,92]],
  night:[[55,69,82,98,82,69],[46,58,69,82,69,58]],
  boss:[[196,0,196,220,0,196,174,0],[147,0,147,165,0,147,131,0]],
};

let curMusicKey='chapel';

let musicSeq=0;

let musicRow=0;

function note(freq,dur,type='square',vol=0.15,delay=0){
  if(!ACtx) return;
  const o=ACtx.createOscillator();
  const g=ACtx.createGain();
  const now=ACtx.currentTime+delay;
  o.connect(g); g.connect(ACtx.destination);
  o.type=type; o.frequency.setValueAtTime(freq,now);
  g.gain.setValueAtTime(0,now);
  g.gain.linearRampToValueAtTime(vol,now+0.01);
  g.gain.exponentialRampToValueAtTime(0.001,now+dur);
  o.start(now); o.stop(now+dur+0.05);
}

function tickMusic(){
  if(!ACtx||!musicOn) return;
  musicTimer++;
  if(musicTimer%18!==0) return;
  const track=MUSIC[curMusicKey]||MUSIC.chapel;
  const row=track[musicSeq%track.length];
  const f=row[musicRow%row.length];
  if(f>0) note(f,0.28,'square',0.06);
  // bass
  if(musicRow%2===0) note(f/2,0.35,'triangle',0.05);
  musicRow++;
  if(musicRow>=row.length){ musicRow=0; musicSeq++; }
}
