  // pews (as brick rows)
  [[4,7,6],[4,9,6],[4,11,6],[21,7,6],[21,9,6],[21,11,6]].forEach(([c,r,w])=>{
    for(let i=c;i<c+w;i++) cm[r*CW+i]=T.BRICK;
  });
  // side walls creating rooms
  for(let r=14;r<25;r++){cm[r*CW+6]=T.WALL;cm[r*CW+25]=T.WALL;}
  cm[18*CW+6]=T.DOOR; cm[18*CW+25]=T.DOOR;
