  // rubble corners
  cm[2*CW+2]=T.RUBBLE; cm[2*CW+29]=T.RUBBLE;
  // Stair down to catacombs (south-center)
  cm[23*CW+15]=T.STAIR_D; cm[23*CW+16]=T.STAIR_D;
  // sign
  cm[8*CW+14]=T.SIGN;

  S.maps.chapel={
