  for(let i=0;i<GH;i++){gm[i*GW]=T.WALL;gm[i*GW+GW-1]=T.WALL;}
  for(let r=1;r<GH-1;r++) for(let c=1;c<GW-1;c++) gm[r*GW+c]=T.FLOOR;
