    case T.DOOR:{
      ctx.fillStyle='#5c2a00';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle='#7a3800';
      ctx.fillRect(px+2,py+2,12,12);
      ctx.fillStyle='#b88000';
      ctx.fillRect(px+7,py+7,2,2);
      ctx.fillStyle='#d8b000';
      ctx.fillRect(px+7,py+7,1,1);
      break;}
    case T.ALTAR:{
      ctx.fillStyle=dark?'#200808':'#181010';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle=dark?'#600010':C.MIDGRY;
      ctx.fillRect(px+2,py+2,12,10);
      ctx.fillStyle=dark?C.BLOOD:C.SILV;
      ctx.fillRect(px+3,py+3,10,7);
      if(!dark&&fl){ctx.fillStyle=C.AMBRE;ctx.fillRect(px+3,py+1,2,2);ctx.fillRect(px+11,py+1,2,2);}
      if(dark){ctx.fillStyle='#aa0000';ctx.fillRect(px+6,py+4,4,3);}
      break;}
    case T.GRAVE:{
      ctx.fillStyle=dark?'#12081a':'#0e1030';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle=dark?'#4a1850':C.MIDGRY;
      ctx.fillRect(px+4,py+2,8,2); ctx.fillRect(px+6,py+1,4,4);
      ctx.fillRect(px+3,py+4,10,9);
      ctx.fillStyle=dark?'#300a36':'#2a2a30';
      ctx.fillRect(px+3,py+4,9,8);
      break;}
    case T.TREE:{
