function tickBells(){
  if(S.phase!==PH.NIGHT) return;
  const map=S.maps[S.curMap]; if(!map||!map.bellPos) return;
  // every 300 frames at night, damage the bell
  if(S.fc%300===0&&S.bellHealth[S.curMap]>0){
    const p=S.player;
    const bx=map.bellPos.x*TW, by=map.bellPos.y*TW;
    const dist=Math.hypot(p.x-bx,p.y-by);
    if(dist>80){
      // Player not defending — bell takes damage
      S.bellHealth[S.curMap]--;
      playBellDie();
      spawnParts(bx,by,'curse',8);
      S.nightWarn=180;
      if(S.bellHealth[S.curMap]<=0){
        startDlg([['','A bell has gone silent. The curse spreads deeper.']],()=>{});
        S.player.curse=Math.min(S.player.maxCurse,S.player.curse+20);
        playCurse();
      }
    } else {
      // Player is near bell — it rings
      playBell();
      spawnParts(bx,by,'holy',6);
    }
  }
  // Wraiths drawn to bell
  if(S.fc%120===0){
    for(const e of S.enemies){
      if(e.type==='bell_wraith'&&map.bellPos){
        // pull toward bell
        e.targetBell=true;
      }
    }
  }
}
