  BRN:'#5c2a00', DKGRN:'#003d00', MIDGRN:'#006b00', SICKGRN:'#4a6b00',
  DKGRY:'#1a1a1a', MIDGRY:'#3a3a3a', LTGRY:'#7a7a7a', SILV:'#bcbcbc',
  WHT:'#f8f8f8', YLW:'#d8b000', GOLD:'#b88000', PURP:'#2d004a',
  DKPUR:'#180028', FLAME:'#e05000', AMBRE:'#d87800', TAN:'#c09860',
  SKIN:'#d89060', BONE:'#c8b078', FOGBLU:'#182858', TEAL:'#006868',
};

const W=256;

const H=224;

function endBoss(){
  doTransition(()=>{
    S.scene=SC.ENDING;
    S.ending=0; // sacrifice ending (default)
    // if player has hammer = ending 3 (bell hammer = freed souls)
    if(S.player.weapon===3) S.ending=3;
    // if curse max = ending 2 hollow
    else if(S.player.curse>=S.player.maxCurse) S.ending=2;
    S.fc=0;
  });
}

let ACtx=null;

function doTransition(cb){
  if(S.scene===SC.TRANSITION) return;
  S.prevScene=S.scene;
  S.scene=SC.TRANSITION;
  S.transAlpha=0; S.transDir=1; S.transCb=cb;
}

function playerAtk(){
  const p=S.player;
  if(p.atkT>0) return;
  p.atkT=p.atkDur+(p.weapon===2?8:p.weapon===3?10:0);
  playAtk();
  const reach=p.weapon===1?30:p.weapon===2?18:p.weapon===3?22:14;
  let ax=p.x,ay=p.y,aw=TW,ah=TW;
  if(p.facing===0){ay-=reach;ah=reach;}
  else if(p.facing===1){ax+=TW;aw=reach;}
  else if(p.facing===2){ay+=TW;ah=reach;}
  else{ax-=reach;aw=reach;}

  let hit=false;
  for(const e of S.enemies){
    if(e.dead) continue;
    if(ax<e.x+14&&ax+aw>e.x&&ay<e.y+14&&ay+ah>e.y){
      const dmg=p.weapon===3?4:p.weapon===2?3:p.weapon===1?2:1;
      e.hp-=dmg;
      e.hitF=10;
      hit=true;
      // knockback
      const kdx=e.x-p.x, kdy=e.y-p.y;
      const kd=Math.hypot(kdx,kdy)||1;
      e.knockX=kdx/kd*3.5; e.knockY=kdy/kd*3.5;
      spawnParts(e.x+8,e.y+8,'blood',5);
      playHit();
      if(e.hp<=0){
        e.dead=true;
        spawnParts(e.x+8,e.y+8,'blood',10);
        spawnParts(e.x+8,e.y+8,'smoke',4);
        shake(6);
        playDie();
        S.player.curse=Math.max(0,S.player.curse-2); // killing reduces curse slightly
      } else shake(3);
    }
  }

  // Bell Hammer holy area effect
  if(p.weapon===3){
    const bpos=S.maps[S.curMap]?.bellPos;
    if(bpos&&Math.hypot(p.x-bpos.x*TW,p.y-bpos.y*TW)<60){
      if(S.bellHealth[S.curMap]<3){
        S.bellHealth[S.curMap]=Math.min(3,S.bellHealth[S.curMap]+1);
        playBell();
        spawnParts(bpos.x*TW,bpos.y*TW,'holy',10);
        startDlg([['','The bell rings again... for now.']],()=>{});
      }
    }
  }

  // Boss combat handled in boss tick
  if(S.scene===SC.BOSS&&S.boss){
    bossTakeDamage(ax,ay,aw,ah);
  }
}
