  S.enemies.push({...c,type,x,y,vx:0,vy:0,atkT:0,hitF:0,dead:false,
    knockX:0,knockY:0,targetBell:false});
}

function getT(m,w,mh,x,y){ if(x<0||y<0||x>=w||y>=mh) return T.WALL; return m[y*w+x]; }

const SOLID_TILES=new Set([T.WALL,T.BRICK,T.TREE,T.PILLAR,T.FENCE,T.STAIR_D,T.FORGE]);

const T={
  FLOOR:0,WALL:1,BRICK:2,DOOR:3,ALTAR:4,GRAVE:5,TREE:6,
  WATER:7,BELL:9,PILLAR:10,TORCH:11,STAIR_D:12,STAIR_U:13,
  RUBBLE:14,FENCE:15,CRACK:16,CHEST:17,SIGN:18,WELL:19,FORGE:20,
};

function loadMap(mapId,px,py){
  if(!S.maps[mapId]) return;
  S.curMap=mapId;
  S.player.x=px; S.player.y=py;
  S.enemies=[];
  if(S.phase===PH.NIGHT) spawnNightEnemies();
  const mdef=S.maps[mapId];
  S.npcs=mdef.npcs?mdef.npcs.map(n=>({...n})):[];
  S.bells=mdef.bellPos?[mdef.bellPos]:[];
  // set music
  curMusicKey=S.phase===PH.NIGHT?'night':(mdef.musicKey||'chapel');
  musicSeq=0; musicRow=0;
  // show location banner
  S.banner=mdef.name||'';
  S.bannerT=120;
  // update camera
  const map=mdef;
  const maxCX=Math.max(0,map.w*TW-W);
  const maxCY=Math.max(0,map.h*TW-(H-HH));
  S.cam.x=Math.max(0,Math.min(maxCX,(px-W/2)|0));
  S.cam.y=Math.max(0,Math.min(maxCY,(py-(H-HH)/2)|0));
}
