  const b=S.boss; if(!b||b.hitF>0) return;
  // hit hands
  for(const h of b.hands){
    if(ax<h.x+24&&ax+aw>h.x&&ay<h.y+24&&ay+ah>h.y){
      b.hp--; b.hitF=15; shake(8); playHit(); spawnParts(h.x+12,h.y+12,'blood',6);
      break;
    }
  }
  // hit main body
  if(ax<b.x+32&&ax+aw>b.x&&ay<b.y+32&&ay+ah>b.y){
    if(b.phase>=1){ b.hp-=2; b.hitF=15; shake(10); playHit(); spawnParts(b.x+16,b.y+16,'blood',8); }
  }
  if(b.hitF>0){
    if(b.hp<=20&&b.phase<1){ b.phase=1; playBell(); spawnParts(W/2,H/2,'curse',12); }
    if(b.hp<=10&&b.phase<2){ b.phase=2; playBell(); spawnParts(W/2,H/2,'curse',16); }
    if(b.hp<=0){ endBoss(); }
  }
}
