  o.type=type; o.frequency.setValueAtTime(freq,now);
  g.gain.setValueAtTime(0,now);
  g.gain.linearRampToValueAtTime(vol,now+0.01);
  g.gain.exponentialRampToValueAtTime(0.001,now+dur);
  o.start(now); o.stop(now+dur+0.05);
}

let ACtx=null;

function tickBoss(){
  const b=S.boss; if(!b) return;
  const p=S.player;
  if(b.hitF>0) b.hitF--;
  b.riseT++;

  // Hands oscillation
  const t=S.fc*0.03;
  b.hands[0].x=(W/2-60)+Math.sin(t)*20;
  b.hands[0].y=80+Math.cos(t*0.7)*15;
  b.hands[1].x=(W/2+28)+Math.sin(t+Math.PI)*20;
  b.hands[1].y=80+Math.cos(t*0.7+Math.PI)*15;

  // Skull bob
  if(b.phase>=1){
    b.skullY=70+Math.sin(S.fc*0.04)*8;
  }

  // Attack patterns
  if(b.atkT>0){b.atkT--;} else {
    b.atkT=b.phase===2?50:b.phase===1?80:120;
    // Hand slam
    if(b.atkPat%3===0){
      // Hand lunges toward player
      for(const h of b.hands){
        const ddx=p.x-h.x, ddy=p.y-h.y;
        const dd=Math.hypot(ddx,ddy)||1;
        // just check collision
        if(Math.hypot(p.x-h.x,p.y-h.y)<28){ damagePlayer(2,h.x,h.y); }
      }
    }
    // Projectile bells
    if(b.atkPat%5===2&&b.phase>=1){
      const dx=p.x-W/2, dy=p.y-b.y;
      const d=Math.hypot(dx,dy)||1;
      S.particles.push({x:W/2+16,y:b.y+30,vx:dx/d*2.5,vy:dy/d*2.5,
        life:60,maxLife:60,col:C.GOLD,sz:4,proj:true,dmg:1});
    }
    b.atkPat++;
  }

  // Darkness rising during phase 2
  if(b.phase===2){
    // extra darkness handled in render
    if(S.fc%60===0) spawnParts(W/2+(Math.random()*80-40),H/2+(Math.random()*60-30),'curse',3);
  }

  // Projectile tick
  for(let i=S.particles.length-1;i>=0;i--){
    const pt=S.particles[i];
    if(!pt.proj) continue;
    if(Math.hypot(p.x-pt.x,p.y-pt.y)<10){
      damagePlayer(pt.dmg||1,pt.x,pt.y);
      S.particles.splice(i,1);
    }
  }
}
