function drawBoss(){
  const b=S.boss; if(!b) return;
  // Arena background
  GC.fillStyle='#000000'; GC.fillRect(0,0,W,H);
  // Cathedral silhouette
  GC.fillStyle='#080808';
  GC.fillRect(0,H/2-20,W,H); // floor
  GC.fillStyle='#060606';
  // pillars
  for(let i=0;i<4;i++){
    GC.fillRect(i*(W/4),0,TW/2,H);
  }
  // chains
  GC.fillStyle='#2a2a2a';
  for(let i=0;i<6;i++){
    const cx=20+i*36;
    GC.fillRect(cx,0,2,60+(Math.sin(S.fc*0.03+i)*10)|0);
  }
  // rising darkness at phase 2
  if(b.phase===2){
    const dr=LC.createLinearGradient(0,H,0,H/2);
    dr.addColorStop(0,'rgba(30,0,30,0.7)');
    dr.addColorStop(1,'rgba(0,0,0,0)');
    LC.fillStyle=dr; LC.fillRect(0,0,W,H);
  }

  const hitC=b.hitF>0&&Math.floor(b.hitF/3)%2;

  // Phase 0+: GIANT HANDS
  for(const h of b.hands){
    const hx=h.x|0, hy=h.y|0;
    GC.fillStyle=hitC?'#ffffff':'#2a1818';
    GC.fillRect(hx,hy,24,20);
    GC.fillStyle=hitC?'#ffffff':'#1a1010';
    // fingers
    for(let f=0;f<5;f++) GC.fillRect(hx+f*5,hy-8+Math.abs(Math.sin(S.fc*0.1+f))*6|0,4,10);
    GC.fillStyle='#cc0000';
    GC.fillRect(hx+4,hy+4,3,3); GC.fillRect(hx+12,hy+4,3,3); // knuckle wounds
  }

  // Phase 1+: SKULL
  if(b.phase>=1){
    const sx=(W/2-24)|0, sy=(b.skullY|0);
    GC.fillStyle=hitC?'#ffffff':C.BONE;
    GC.fillRect(sx,sy,48,40);
    GC.fillStyle=hitC?'#888888':'#000820';
    GC.fillRect(sx+4,sy+8,14,14); GC.fillRect(sx+30,sy+8,14,14); // eye sockets
    GC.fillStyle=hitC?'#ff0000':'#cc0000';
    GC.fillRect(sx+8,sy+10,6,6); GC.fillRect(sx+34,sy+10,6,6); // red eyes
    // Crown of broken bells
    GC.fillStyle=C.GOLD;
    for(let i=0;i<5;i++) GC.fillRect(sx+4+i*9,sy-8,6,10);
    // Jaw rattle
    const jaw=Math.floor(S.fc/8)%2;
    GC.fillStyle=C.BONE; GC.fillRect(sx+6,sy+30+jaw,36,12);
    GC.fillStyle='#000'; for(let t2=0;t2<4;t2++) GC.fillRect(sx+10+t2*8,sy+30+jaw,4,10);
    // Chains
    GC.fillStyle='#3a3a3a';
    for(let c=0;c<3;c++) GC.fillRect(sx+8+c*16,sy+40,4,H-sy-40);
  }

