    GC.fillStyle=`rgba(30,0,0,${norm*0.4})`; GC.fillRect(0,0,W,H);
  } else if(S.ending===3){ // true ending — golden light
    const gl=GC.createRadialGradient(W/2,H/2,10,W/2,H/2,130);
    gl.addColorStop(0,`rgba(180,140,0,${norm*0.3})`);
    gl.addColorStop(1,'rgba(0,0,0,0)');
    GC.fillStyle=gl; GC.fillRect(0,0,W,H);
  }

  ptext(GC,end.title,(W-ptw(end.title))/2|0,30,`rgba(${hex2rgb(end.col)},${norm})`);
  // underline
  GC.fillStyle=`rgba(${hex2rgb(end.col)},${norm*0.5})`;
  GC.fillRect(4,40,W-8,1);

  for(let i=0;i<end.lines.length;i++){
    const la=Math.min(1,Math.max(0,(S.fc-60-i*40)/40));
    if(la>0) ptext(GC,end.lines[i],(W-ptw(end.lines[i]))/2|0,60+i*14,`rgba(${hex2rgb(C.SILV)},${la*0.9})`);
  }

  if(S.fc>200&&Math.floor(S.fc/28)%2) ptext(GC,'PRESS ENTER',72,H-20,C.SILV);
  if(jp('Enter')){ resetGame(); }
}
