function loadMap(mapId,px,py){
  if(!S.maps[mapId]) return;
  S.curMap=mapId;
  S.player.x=px; S.player.y=py;
  S.enemies=[];
  if(S.phase===PH.NIGHT) spawnNightEnemies();
  const mdef=S.maps[mapId];
  S.npcs=mdef.npcs?mdef.npcs.map(n=>({...n})):[];
  S.bells=mdef.bellPos?[mdef.bellPos]:[];
  // set music
  curMusicKey=S.phase===PH.NIGHT?'night':(mdef.musicKey||'chapel');
  musicSeq=0; musicRow=0;
  // show location banner
  S.banner=mdef.name||'';
  S.bannerT=120;
  // update camera
  const map=mdef;
  const maxCX=Math.max(0,map.w*TW-W);
  const maxCY=Math.max(0,map.h*TW-(H-HH));
  S.cam.x=Math.max(0,Math.min(maxCX,(px-W/2)|0));
  S.cam.y=Math.max(0,Math.min(maxCY,(py-(H-HH)/2)|0));
}

let curMusicKey='chapel';

let musicSeq=0;

let musicRow=0;

function spawnNightEnemies(){
  const map=S.maps[S.curMap]; if(!map) return;
  S.enemies=[];
  const count=Math.min(8,2+S.day);
  const pool=['gravewalker'];
  if(S.day>=2) pool.push('husk_dog');
  if(S.day>=3) pool.push('bell_wraith');
  for(let i=0;i<count;i++){
    let ex,ey,tries=0;
    do{
      ex=(1+Math.floor(Math.random()*(map.w-2)))*TW;
      ey=(1+Math.floor(Math.random()*(map.h-2)))*TW;
      tries++;
    }while(tries<30&&isSolid(ex+8,ey+8));
    spawnEnemy(pool[Math.floor(Math.random()*pool.length)],ex,ey);
  }
}

