        ctx.fillRect(px + 8,  py + 5,  2,  2);
        ctx.fillRect(px + 6,  py + 7,  6,  2);
        ctx.fillRect(px + 4,  py + 9,  9,  2);  /* widest row */
        ctx.fillRect(px + 6,  py + 11, 6,  2);
        ctx.fillRect(px + 8,  py + 13, 2,  1);
