        ctx.fillStyle = '#484868';
        ctx.fillRect(px + 2,  py + 4,  2, 2);
        ctx.fillRect(px + 12, py + 4,  2, 2);
        ctx.fillRect(px + 2,  py + 12, 2, 2);
        ctx.fillRect(px + 12, py + 12, 2, 2);
      }
    }
  }
}
