```javascript
const NES = Object.freeze({
  W:       256,
  H:       224,
  TILE:     16,    // 16×16px tiles
  FPS:      60,
  FRAME_MS: 1000 / 60,
});

function tileIsSolid(id)  { return TILE_PROPS[id] ? TILE_PROPS[id].solid  : false; }

function tileAt(mapData, tx, ty) {
  if (tx < 0 || ty < 0 || tx >= mapData.cols || ty >= mapData.rows) return T.SOLID;
  return mapData.data[ty * mapData.cols + tx];
}

function tileIsOneway(id) { return TILE_PROPS[id] ? TILE_PROPS[id].oneway : false; }

const TILE_PROPS = (function() {
  const p = [];
  const def = (id, solid, oneway, hazard, trigger) =>
    (p[id] = { solid, oneway, hazard, trigger: trigger || null });
  def(T.AIR,      false, false, false);
  def(T.SOLID,    true,  false, false);
  def(T.PLATFORM, false, true,  false);
  def(T.SPIKE,    false, false, true);
  def(T.LORE,     false, false, false, 'lore');
  def(T.WEAPON,   false, false, false, 'weapon');
  def(T.DOOR_UP,  false, false, false, 'door_up');
  def(T.DOOR_L,   false, false, false, 'door_l');
  def(T.DOOR_R,   false, false, false, 'door_r');
  def(T.DOOR_D,   false, false, false, 'door_d');
  return p;
})();

const T = Object.freeze({
  AIR: 0, SOLID: 1, PLATFORM: 2, SPIKE: 3,
  LORE: 5, WEAPON: 6, DOOR_UP: 7, DOOR_L: 8, DOOR_R: 9, DOOR_D: 10,
});

function resolveCollision(entity, mapData) {
  const T16 = NES.TILE;
  let { x, y, w, h, vx, vy } = entity;
  let onGround = false, hitCeiling = false, hitWallL = false, hitWallR = false;

  /* ── X axis ── */
  x += vx;
  if (vx !== 0) {
    const left  = (x / T16) | 0;
    const right = ((x + w - 1) / T16) | 0;
    const top   = ((y + 1) / T16) | 0;
    const bot   = ((y + h - 2) / T16) | 0;
    if (vx > 0) {
      /* moving right — check right edge at top and bottom of entity */
      if (tileIsSolid(tileAt(mapData, right, top)) ||
          tileIsSolid(tileAt(mapData, right, bot))) {
        x = right * T16 - w;
        vx = 0; hitWallR = true;
      }
    } else {
      /* moving left — check left edge */
      if (tileIsSolid(tileAt(mapData, left, top)) ||
          tileIsSolid(tileAt(mapData, left, bot))) {
        x = (left + 1) * T16;
        vx = 0; hitWallL = true;
      }
    }
  }

  /* ── Y axis ── */
  y += vy;
  {
    const left  = ((x + 1) / T16) | 0;
    const right = ((x + w - 2) / T16) | 0;
    const top   = (y / T16) | 0;
    const bot   = ((y + h) / T16) | 0;

    if (vy >= 0) {
      /* falling or standing — check bottom edge; include one-way platforms */
      const tL = tileAt(mapData, left,  bot);
      const tR = tileAt(mapData, right, bot);
      const solidDown = tileIsSolid(tL) || tileIsSolid(tR) ||
        ((tileIsOneway(tL) || tileIsOneway(tR)) && ((y - vy) + h) <= bot * T16);
      if (solidDown) {
        y = bot * T16 - h;
        vy = 0; onGround = true;
      }
    } else {
      /* rising — check top edge, solid only */
      if (tileIsSolid(tileAt(mapData, left,  top)) ||
          tileIsSolid(tileAt(mapData, right, top))) {
        y = (top + 1) * T16;
        vy = 0; hitCeiling = true;
      }
    }
  }

  return { x, y, vx, vy, onGround, hitCeiling, hitWallL, hitWallR };
}
