const ENEMY_CFG = Object.freeze({
  skeleton: {
    w: 14, h: 22, hp: 2,
    speed: 0.8, aggroRange: 96, lungeVx: 2.8,
    gravity: true, contactDamage: 1,
  },
  bat: {
    w: 14, h: 12, hp: 1,
    diveSpeed: 2.4, aggroRange: 80,
    gravity: false, contactDamage: 1,
    ampX: 36, ampY: 10,
  },
  armored_guard: {
    w: 14, h: 22, hp: 3,
    speed: 0.45, aggroRange: 80,
    gravity: true, contactDamage: 2,
  },
});

const PHYS = Object.freeze({
  GRAVITY:      0.35,
  MAX_FALL:     8,
  WALK:         1.5,
  JUMP:         -6.5,    /* 60px max height: row-7(48px)✓ row-5 via row-7(32px)✓ */
  KB_X:         3.5,
  KB_Y:         -3.0,
  KB_FRAMES:    20,
  IFRAME_DUR:   60,
  /* ATTACK_DUR removed — weapon recovery is in WEAPON_DEF[name].recovery */
  PLAYER_W:     14,
  PLAYER_H:     22,
});

function resolveCollision(entity, mapData) {
  const T16 = NES.TILE;
  let { x, y, w, h, vx, vy } = entity;
  let onGround = false, hitCeiling = false, hitWallL = false, hitWallR = false;

  /* ── X axis ── */
  x += vx;
  if (vx !== 0) {
    const left  = (x / T16) | 0;
    const right = ((x + w - 1) / T16) | 0;
    const top   = ((y + 1) / T16) | 0;
    const bot   = ((y + h - 2) / T16) | 0;
    if (vx > 0) {
      /* moving right — check right edge at top and bottom of entity */
      if (tileIsSolid(tileAt(mapData, right, top)) ||
          tileIsSolid(tileAt(mapData, right, bot))) {
        x = right * T16 - w;
        vx = 0; hitWallR = true;
      }
    } else {
      /* moving left — check left edge */
      if (tileIsSolid(tileAt(mapData, left, top)) ||
          tileIsSolid(tileAt(mapData, left, bot))) {
        x = (left + 1) * T16;
        vx = 0; hitWallL = true;
      }
    }
  }

  /* ── Y axis ── */
  y += vy;
  {
    const left  = ((x + 1) / T16) | 0;
    const right = ((x + w - 2) / T16) | 0;
    const top   = (y / T16) | 0;
    const bot   = ((y + h) / T16) | 0;

    if (vy >= 0) {
      /* falling or standing — check bottom edge; include one-way platforms */
      const tL = tileAt(mapData, left,  bot);
      const tR = tileAt(mapData, right, bot);
      const solidDown = tileIsSolid(tL) || tileIsSolid(tR) ||
        ((tileIsOneway(tL) || tileIsOneway(tR)) && ((y - vy) + h) <= bot * T16);
      if (solidDown) {
        y = bot * T16 - h;
        vy = 0; onGround = true;
      }
    } else {
      /* rising — check top edge, solid only */
      if (tileIsSolid(tileAt(mapData, left,  top)) ||
          tileIsSolid(tileAt(mapData, right, top))) {
        y = (top + 1) * T16;
        vy = 0; hitCeiling = true;
      }
    }
  }

  return { x, y, vx, vy, onGround, hitCeiling, hitWallL, hitWallR };
}

function enemyWouldFall(enemy, dir, md) {
  const edgeX  = dir === 1 ? enemy.x + enemy.w + 2 : enemy.x - 2;
  const floorY = enemy.y + enemy.h + 4;
  return !tileIsSolid(tileAt(md, (edgeX / NES.TILE) | 0, (floorY / NES.TILE) | 0));
}

const NES = Object.freeze({
  W:       256,
  H:       224,
  TILE:     16,    // 16×16px tiles
  FPS:      60,
  FRAME_MS: 1000 / 60,
});

function tileAt(mapData, tx, ty) {
  if (tx < 0 || ty < 0 || tx >= mapData.cols || ty >= mapData.rows) return T.SOLID;
  return mapData.data[ty * mapData.cols + tx];
}

function tileIsSolid(id)  { return TILE_PROPS[id] ? TILE_PROPS[id].solid  : false; }

const TILE_PROPS = (function() {
  const p = [];
  const def = (id, solid, oneway, hazard, trigger) =>
    (p[id] = { solid, oneway, hazard, trigger: trigger || null });
  def(T.AIR,      false, false, false);
  def(T.SOLID,    true,  false, false);
  def(T.PLATFORM, false, true,  false);
  def(T.SPIKE,    false, false, true);
  def(T.LORE,     false, false, false, 'lore');
  def(T.WEAPON,   false, false, false, 'weapon');
  def(T.DOOR_UP,  false, false, false, 'door_up');
  def(T.DOOR_L,   false, false, false, 'door_l');
  def(T.DOOR_R,   false, false, false, 'door_r');
  def(T.DOOR_D,   false, false, false, 'door_d');
  return p;
})();

function tileIsOneway(id) { return TILE_PROPS[id] ? TILE_PROPS[id].oneway : false; }

const T = Object.freeze({
  AIR: 0, SOLID: 1, PLATFORM: 2, SPIKE: 3,
  LORE: 5, WEAPON: 6, DOOR_UP: 7, DOOR_L: 8, DOOR_R: 9, DOOR_D: 10,
});

function updateEnemyGround(enemy, md, player) {
  const cfg = ENEMY_CFG[enemy.type];

  /* ── Dead flash ── */
  if (enemy.state === 'dead') {
    if (++enemy.stateTimer >= 30) enemy.dead = true;
    return;
  }

  /* ── Hurt — knockback + brief stun ── */
  if (enemy.state === 'hurt') {
    enemy.stateTimer++;
    enemy.vx *= 0.75;
    enemy.vy += PHYS.GRAVITY;
    if (enemy.vy > PHYS.MAX_FALL) enemy.vy = PHYS.MAX_FALL;
    const res = resolveCollision(enemy, md);
    enemy.x = res.x; enemy.y = res.y; enemy.vx = res.vx; enemy.vy = res.vy;
    if (enemy.stateTimer >= 14) {
      enemy.state      = enemy.hp <= 0 ? 'dead' : 'patrol';
      enemy.stateTimer = 0;
      if (enemy.state === 'patrol') enemy.vx = 0;
    }
    return;
  }

  const hasPlayer = !!(player && player.hp > 0);
  const pdx       = hasPlayer ? (player.x + (player.w >> 1)) - (enemy.x + (enemy.w >> 1)) : 0;
  const sameFloor = hasPlayer &&
    Math.abs((player.y + player.h) - (enemy.y + enemy.h)) < 40;

  /* ─────────────────────────────────────────────────────────────
     SKELETON: patrol → alert (18fr pause) → attack (22fr lunge)
  ───────────────────────────────────────────────────────────── */
  if (enemy.type === 'skeleton') {
    if (enemy.state === 'patrol') {
      enemy.vx = enemy.facing * cfg.speed;
      if (hasPlayer && sameFloor && Math.abs(pdx) < cfg.aggroRange) {
        enemy.facing     = pdx > 0 ? 1 : -1;
        enemy.state      = 'alert';
        enemy.stateTimer = 0;
        enemy.vx = 0;
      }
    } else if (enemy.state === 'alert') {
      enemy.stateTimer++;
      enemy.vx = 0;
      if (hasPlayer) enemy.facing = pdx > 0 ? 1 : -1;
      if (enemy.stateTimer >= 18) {
        enemy.state      = 'attack';
        enemy.stateTimer = 0;
        enemy.vx         = enemy.facing * cfg.lungeVx;
      }
    } else if (enemy.state === 'attack') {
      /* Decelerate lunge over the 22 frames rather than running full speed */
      enemy.vx *= 0.93;
      if (++enemy.stateTimer >= 22) {
        enemy.state      = 'patrol';
        enemy.stateTimer = 0;
        enemy.vx = 0;
      }
    }
  }

  /* ─────────────────────────────────────────────────────────────
     ARMORED GUARD: patrol → chase (continuous pursuit, 150fr max)
     No lunge. Slow, heavy, persistent.
  ───────────────────────────────────────────────────────────── */
  if (enemy.type === 'armored_guard') {
    if (enemy.state === 'patrol') {
      enemy.vx = enemy.facing * cfg.speed;
      if (hasPlayer && sameFloor && Math.abs(pdx) < cfg.aggroRange) {
        enemy.facing     = pdx > 0 ? 1 : -1;
        enemy.state      = 'chase';
        enemy.stateTimer = 0;
      }
    } else if (enemy.state === 'chase') {
      enemy.stateTimer++;
      if (hasPlayer) enemy.facing = pdx > 0 ? 1 : -1;
      enemy.vx = enemy.facing * cfg.speed;
      const lostPlayer = !hasPlayer || !sameFloor;
      if (lostPlayer && enemy.stateTimer > 30) {
        enemy.state      = 'patrol';
        enemy.stateTimer = 0;
      }
    }
  }

  /* ── Gravity + collision ── */
  enemy.vy += PHYS.GRAVITY;
  if (enemy.vy > PHYS.MAX_FALL) enemy.vy = PHYS.MAX_FALL;
  const res = resolveCollision(enemy, md);
  enemy.x = res.x; enemy.y = res.y;
  enemy.vx = res.vx; enemy.vy = res.vy;

  /* ── Turn logic — only ONE flip per frame ── */
  const inAttack = enemy.state === 'attack';
  const inChase  = enemy.state === 'chase';

  if (inAttack && (res.hitWallL || res.hitWallR)) {
    /* Lunge cancelled by wall */
    enemy.state      = 'patrol';
    enemy.stateTimer = 0;
    enemy.facing    *= -1;
    enemy.vx = 0;

  } else if (inChase && (res.hitWallL || res.hitWallR)) {
    /* Chase hits wall — turn and keep going */
    enemy.facing *= -1;
    enemy.vx = enemy.facing * cfg.speed;

  } else if (!inAttack && !inChase) {
    /* Patrol: wall, pit, and door checks — only one flip allowed */
    let turned = false;
    if (res.hitWallL || res.hitWallR) {
      enemy.facing *= -1;
      turned = true;
    }
    if (!turned && res.onGround && enemyWouldFall(enemy, enemy.facing, md)) {
      enemy.facing *= -1;
      turned = true;
    }
    if (!turned) {
      const ftx = ((enemy.x + (enemy.facing === 1 ? enemy.w + 1 : -1)) / NES.TILE) | 0;
      const fty = ((enemy.y + enemy.h * 0.5) / NES.TILE) | 0;
      const fid = tileAt(md, ftx, fty);
      if (!tileIsSolid(fid) && TILE_PROPS[fid] && TILE_PROPS[fid].trigger) {
        enemy.facing *= -1;
      }
    }
    /* Only restore patrol speed — alert and other non-moving states keep their own vx */
    if (enemy.state === 'patrol') enemy.vx = enemy.facing * cfg.speed;
  }

  /* ── Walk animation ── */
  if (res.onGround && Math.abs(enemy.vx) > 0.1) {
    if (++enemy.animTimer >= 10) { enemy.animTimer = 0; enemy.animFrame++; }
  }
}
