  [6, 18, 32].forEach(col => {
    const ax = col * T, ay = T;
    ctx.fillStyle = zpal.solidShad;
    ctx.fillRect(ax,         ay, 3, 10);
    ctx.fillRect(ax + T - 3, ay, 3, 10);
