  // Castle stone tones
  STONE_DARK: '#1a1210',
  STONE_MID:  '#3c2e26',
  STONE_LITE: '#6b5040',
  STONE_HIGH: '#9c7a60',

  // Accent / hazard
  BLOOD_RED:  '#6d1313',
  FIRE_RED:   '#cc2200',
  GOLD:       '#d4a017',
  PALE_GOLD:  '#f0d080',

  // Player / UI
