  CLOAK_MID:  '#2a2a4a',
  CLOAK_LITE: '#4a4a8a',
  SKIN:       '#f0c090',
  SWORD_GREY: '#c0c0c0',

  // UI chrome
  HUD_BG:     '#0a0a0a',
  HUD_HEART:  '#cc0000',
  HUD_EMPTY:  '#330000',
  HUD_TEXT:   '#f0e0b0',

  // Cursor / selected
  CURSOR:     '#ffff00',
});

const NES = Object.freeze({
  W:       256,
  H:       224,
  TILE:     16,    // 16×16px tiles
  FPS:      60,
  FRAME_MS: 1000 / 60,
});

function drawDynamicPickups(ctx, zoneId, camX, camY) {
  const zone = ZONES[zoneId];
  if (!zone || !zone.mapData) return;
  const { cols, rows } = zone.mapData;
  const pulse = Math.sin(G.frame * 0.1) * 0.5 + 0.5;  /* 0–1 oscillate */

  /* Only draw tiles in the visible viewport */
