function createOffscreenCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width  = w;
  c.height = h;
  const ctx = c.getContext('2d', { alpha: false });
  ctx.imageSmoothingEnabled = false;
  return { canvas: c, ctx };
}

function zonePal(id) { return ZONE_PAL[id] || _DEFAULT_ZPAL; }

const T = Object.freeze({
  AIR: 0, SOLID: 1, PLATFORM: 2, SPIKE: 3,
  LORE: 5, WEAPON: 6, DOOR_UP: 7, DOOR_L: 8, DOOR_R: 9, DOOR_D: 10,
});

function drawTile(ctx, id, px, py, tileCol, tileRow, zpal) {
  const T16 = NES.TILE;
  switch (id) {

    case T.SOLID: {
      ctx.fillStyle = zpal.solidBase;
      ctx.fillRect(px, py, T16, T16);
      /* top highlight */
      ctx.fillStyle = zpal.solidTop;
      ctx.fillRect(px, py, T16, 2);
      /* right + bottom shadow */
      ctx.fillStyle = zpal.solidShad;
      ctx.fillRect(px + T16 - 2, py, 2, T16);
      ctx.fillRect(px, py + T16 - 2, T16, 2);
      /* brick seam — horizontal, alternates x-offset every row */
      const seamX = px + ((tileRow % 2 === 0) ? 0 : 8);
      ctx.fillRect(seamX, py + 8, 8, 1);
      break;
    }

    case T.PLATFORM: {
      /* Transparent base (air) — nothing. Just the ledge surface. */
      ctx.fillStyle = zpal.platformTop;
      ctx.fillRect(px, py, T16, 2);           /* bright lip */
      ctx.fillStyle = zpal.platformMid;
      ctx.fillRect(px, py + 2, T16, 4);       /* ledge body */
      ctx.fillStyle = zpal.platformBot;
      ctx.fillRect(px, py + 6, T16, 2);       /* underside */
      break;
    }

    case T.SPIKE: {
      ctx.fillStyle = zpal.solidShad;
      ctx.fillRect(px, py + 8, T16, 8);       /* base plate */
      /* Two spikes — pixel-art triangles via stacked fillRects */
      for (let s = 0; s < 2; s++) {
        const sx = px + 2 + s * 8;
        ctx.fillStyle = PAL.BLOOD_RED;
        ctx.fillRect(sx,     py + 12, 4, 4);  /* spike base */
        ctx.fillStyle = PAL.FIRE_RED;
        ctx.fillRect(sx + 1, py + 8,  2, 4);  /* spike mid */
        ctx.fillStyle = PAL.LIGHTGRAY;
        ctx.fillRect(sx + 1, py + 6,  2, 2);  /* spike tip */
      }
      break;
    }

    case T.DOOR_UP: {
      ctx.fillStyle = PAL.CLOAK_DARK;
      ctx.fillRect(px, py, T16, T16);
      ctx.fillStyle = PAL.STONE_MID;
      ctx.fillRect(px, py, 2, T16);            /* left pillar */
      ctx.fillRect(px + T16 - 2, py, 2, T16); /* right pillar */
      ctx.fillStyle = PAL.GOLD;
      ctx.fillRect(px + 2, py, T16 - 4, 2);   /* lintel */
      /* up arrow */
      ctx.fillStyle = PAL.PALE_GOLD;
      ctx.fillRect(px + 7, py + 4, 2, 8);
      ctx.fillRect(px + 4, py + 6, 8, 2);
      ctx.fillRect(px + 5, py + 4, 6, 2);
      break;
    }

    case T.DOOR_L: {
      ctx.fillStyle = PAL.CLOAK_DARK;
      ctx.fillRect(px, py, T16, T16);
      ctx.fillStyle = PAL.STONE_MID;
      ctx.fillRect(px, py, T16, 2);
      ctx.fillRect(px, py + T16 - 2, T16, 2);
      ctx.fillStyle = PAL.GOLD;
      ctx.fillRect(px, py + 2, 2, T16 - 4);
      ctx.fillStyle = PAL.PALE_GOLD;
      ctx.fillRect(px + 4, py + 7, 8, 2);
      ctx.fillRect(px + 4, py + 5, 2, 6);
      ctx.fillRect(px + 6, py + 5, 2, 2);
      break;
    }

    case T.DOOR_R: {
      ctx.fillStyle = PAL.CLOAK_DARK;
      ctx.fillRect(px, py, T16, T16);
      ctx.fillStyle = PAL.STONE_MID;
      ctx.fillRect(px, py, T16, 2);            /* top lintel */
      ctx.fillRect(px, py + T16 - 2, T16, 2); /* bottom sill */
      ctx.fillStyle = PAL.GOLD;
      ctx.fillRect(px + T16 - 2, py + 2, 2, T16 - 4); /* right accent */
      /* right-pointing arrow */
      ctx.fillStyle = PAL.PALE_GOLD;
      ctx.fillRect(px + 4, py + 7, 8, 2);
      ctx.fillRect(px + 10, py + 5, 2, 6);
      ctx.fillRect(px + 8,  py + 5, 2, 2);
      break;
    }

    /* LORE + WEAPON are dynamic — drawn per-frame in drawDynamicPickups */
    default: break;
  }
}

const DEBUG = true;

const G = {
  state:        STATE.TITLE,
  prevState:    STATE.TITLE,
  stateTimer:   0,          // frames since last state change
  frame:        0,          // total frames elapsed

  /* populated by Section 3 */
  player:       null,

  /* populated by Section 2 */
  camera:       null,

  /* populated by Section 2 */
  currentZoneId: null,

  /* populated by Section 5 */
  theHand:      null,

  /* populated by Section 7 */
  boss:         null,

  /* populated by Section 8 */
  audio:        null,

  /* populated by Section 9 */
  hud:          null,
  lore:         null,
};

const ZONE_PAL = {
  [ZONE_ID.ENTRY]: {
    bg:          PAL.STONE_DARK,
    solidBase:   PAL.STONE_MID,
    solidTop:    PAL.STONE_HIGH,
    solidShad:   PAL.STONE_DARK,
    platformTop: PAL.STONE_HIGH,
    platformMid: PAL.STONE_LITE,
    platformBot: PAL.STONE_MID,
  },
};

const _DEFAULT_ZPAL = ZONE_PAL[ZONE_ID.ENTRY];

const STATE = Object.freeze({
  TITLE:    'TITLE',
  PLAYING:  'PLAYING',
  PAUSED:   'PAUSED',
  DEAD:     'DEAD',
  WIN:      'WIN',
});

const ZONE_ID = Object.freeze({
  ENTRY:    'ENTRY',    // Zone 1 — The Entry Hall
  CRYPT:    'CRYPT',    // Zone 2 — The Crypt
  CLOCK:    'CLOCK',    // Zone 3 — The Clocktower
  SANCTUM:  'SANCTUM',  // Zone 4 — The Sanctum
  THRONE:   'THRONE',   // Zone 5 — The Throne Room
  BOSS:     'BOSS',     // Boss arena (separate from Zone 5)
});

function renderZone(ctx, zoneId, camX, camY) {
  const zone = ZONES[zoneId];
  if (!zone) return;

  if (!zone.staticCanvas) buildZoneStaticCanvas(zoneId);

  /* Zone has no map data yet — show a placeholder rather than crash */
  if (!zone.staticCanvas) {
    ctx.fillStyle = PAL.BLACK;
    ctx.fillRect(0, 0, NES.W, NES.H);
    ctx.fillStyle = PAL.STONE_HIGH;
    ctx.font = '8px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('[ ' + zoneId + ' ]', NES.W / 2, NES.H / 2 - 8);
    ctx.fillStyle = PAL.MIDGRAY;
    ctx.font = '6px monospace';
    ctx.fillText('COMING IN NEXT SECTION', NES.W / 2, NES.H / 2 + 8);
    ctx.textAlign = 'left';
    return;
  }

  ctx.drawImage(zone.staticCanvas, -camX, -camY);
  drawDynamicPickups(ctx, zoneId, camX, camY);
}
