    const mapH = zone && zone.mapData ? zone.mapData.rows * NES.TILE : NES.H;
    const maxX = Math.max(0, mapW - NES.W);
    const maxY = Math.max(0, mapH - NES.H);
    const cx = entity ? entity.x - NES.W / 2 + (entity.w >> 1) : this.targetX;
    const cy = entity ? entity.y - NES.H / 2 + (entity.h >> 1) : this.targetY;
    this.targetX = Math.max(0, Math.min(cx, maxX));
    this.targetY = Math.max(0, Math.min(cy, maxY));
    this.x = Math.round(this.targetX);
    this.y = Math.round(this.targetY);
