  const cap=500;
  for(let i=0;i<n&&G.particles.length<cap;i++){
    const a=Math.random()*Math.PI*2;
    const spd=opts.spd||rng(60,180);
    G.particles.push({
      x, y,
      vx: Math.cos(a)*spd,
      vy: Math.sin(a)*spd - (opts.up?50:0),
      col: col||C.rouge,
      life: 1,
      decay: rng(0.4, 1.1),   // life lost per second → 0.9–2.5s lifetime
      sz: opts.sz||rng(1.2,3),
      settles: opts.settles!==false,
    });
  }
}

const C = {
  void:'#0d0d10', iron:'#3a3d54', floor:'#1e2128',
  rouge:'#ba041c', bright:'#ff3333', gold:'#ffb703',
  white:'#f0f0f8', necro:'#4f121a', dark:'#0d0e15',
};

function triggerBioGenWave(wx, wy){
  boom(wx, wy, 30, C.gold, {spd:140, settles:false});
  const count = 2 + Math.floor(G.floor/3);
  for(let i=0; i<count; i++){
    const ang = (i/count)*Math.PI*2;
    const def = ETYPES.husk;
    G.enemies.push({
      ...def, type:'husk',
      x: wx+Math.cos(ang)*TILE*1.5,
      y: wy+Math.sin(ang)*TILE*1.5,
      hp: def.hp*(1+(G.floor-1)*0.1),
      maxHp: def.hp*(1+(G.floor-1)*0.1),
      charging:false, chargeWait:rng(0.5,1.5), chargeT:0, cdx:0, cdy:0,
      shotT:rng(1,2.5),
    });
  }
}

function playSound(type){
  if(!audioCtx) return;
  try{
    const o=audioCtx.createOscillator(), g=audioCtx.createGain();
    o.connect(g); g.connect(audioCtx.destination);
    const t=audioCtx.currentTime;
    if(type==='kill'){
      o.type='sawtooth';
      o.frequency.setValueAtTime(240,t); o.frequency.exponentialRampToValueAtTime(35,t+0.2);
      g.gain.setValueAtTime(0.35,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.2);
      o.start(t); o.stop(t+0.2);
    } else if(type==='attack'){
      o.type='square';
      o.frequency.setValueAtTime(400,t); o.frequency.exponentialRampToValueAtTime(160,t+0.07);
      g.gain.setValueAtTime(0.1,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.07);
      o.start(t); o.stop(t+0.07);
    } else if(type==='graft'){
      // Wet organic slam
      o.type='sine';
      o.frequency.setValueAtTime(60,t); o.frequency.linearRampToValueAtTime(520,t+0.18);
      g.gain.setValueAtTime(0.55,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.32);
      o.start(t); o.stop(t+0.32);
    } else if(type==='decay'){
      o.type='sawtooth';
      o.frequency.setValueAtTime(380,t); o.frequency.exponentialRampToValueAtTime(18,t+0.55);
      g.gain.setValueAtTime(0.5,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.55);
      o.start(t); o.stop(t+0.55);
    } else if(type==='hb'){
      o.type='sine';
      o.frequency.setValueAtTime(58,t); o.frequency.exponentialRampToValueAtTime(22,t+0.14);
      g.gain.setValueAtTime(0.48,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.18);
      o.start(t); o.stop(t+0.18);
    } else if(type==='spore'){
      o.type='sine';
      o.frequency.setValueAtTime(180,t); o.frequency.exponentialRampToValueAtTime(60,t+0.3);
      g.gain.setValueAtTime(0.18,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
      o.start(t); o.stop(t+0.3);
    }
  }catch(e){}
}

function rng(a,b){ return a+Math.random()*(b-a); }

const ETYPES = {
  husk:   { name:'HUSK',    hp:40,  spd:58,  col:'#5a5a78', sz:10, rv:20, org:'ORG-02', dmg:10, contactDmg:true },
  spitter:{ name:'SPITTER', hp:30,  spd:48,  col:'#4a7a30', sz:9,  rv:20, org:'ORG-07', dmg:0,  contactDmg:false, ranged:true },
  charger:{ name:'CHARGER', hp:60,  spd:130, col:'#8a4a20', sz:12, rv:25, org:'ORG-03', dmg:18, contactDmg:true, charger:true },
  crawler:{ name:'CRAWLER', hp:25,  spd:85,  col:'#3a5a2a', sz:7,  rv:15, org:'ORG-04', dmg:6,  contactDmg:true },
  leech:  { name:'LEECH',   hp:45,  spd:72,  col:'#4a1a3a', sz:9,  rv:30, org:'ORG-05', dmg:0,  contactDmg:false, leech:true },
  brute:  { name:'BRUTE',   hp:120, spd:36,  col:'#5a3a6a', sz:16, rv:35, org:'ORG-08', dmg:14, contactDmg:true },
  // ── ELITES (2.5× HP, 1.5× dmg, elite:true flag) ──────────────
  revenant:{ name:'REVENANT', hp:100, spd:60, col:'#8a0a5a', sz:11, rv:35, org:'ORG-06', dmg:18, contactDmg:true, elite:true, teleport:true, teleWait:2, teleT:0 },
  architect:{ name:'ARCHITECT', hp:75, spd:44, col:'#2a5a8a', sz:10, rv:35, org:'ORG-01', dmg:10, contactDmg:false, elite:true, ranged:true, builder:true, buildT:3 },
};

let audioCtx = null;

function addSat(px,py,amt){
  const c=Math.floor(px/TILE), r=Math.floor(py/TILE);
  if(r<0||r>=ROWS||c<0||c>=COLS) return;
  // Acidic-Kidney: triple saturation gain on wall tiles
  const hasAcid=(G.grafts&&(G.grafts[0]==='ORG-04'||G.grafts[1]==='ORG-04'));
  const t0=G.map[r][c];
  if(hasAcid && t0===T.WALL) amt*=3;
  const prev=G.sat[r][c];
  G.sat[r][c]=Math.min(100,prev+amt);
  const s=G.sat[r][c], t=G.map[r][c];
  // Wall dissolves at 80
  if(t===T.WALL && s>=80 && prev<80){
    G.map[r][c]=T.FLOOR; G.tilesTransformed++;
    boom(c*TILE+20,r*TILE+20,10,C.iron,{spd:80,settles:false});
  }
  // Chasm bridges at 80
  if(t===T.CHASM && s>=80 && !G.chasmed[r*1000+c]){
    G.chasmed[r*1000+c]=true; G.tilesTransformed++;
  }
  // Bio-door tile itself at 60
  if(t===T.BIODOOR && s>=60){ G.doored[r*1000+c]=true; G.tilesTransformed++; }
  // Bio-door unlocks from adjacent saturation avg
  for(const [dr,dc] of [[-1,0],[1,0],[0,-1],[0,1]]){
    const nr=r+dr, nc=c+dc;
    if(nr<0||nr>=ROWS||nc<0||nc>=COLS) continue;
    if(G.map[nr][nc]!==T.BIODOOR) continue;
    let tot=0,cnt=0;
    for(const [dr2,dc2] of [[-1,0],[1,0],[0,-1],[0,1]]){
      const nr2=nr+dr2,nc2=nc+dc2;
      if(nr2>=0&&nr2<ROWS&&nc2>=0&&nc2<COLS){ tot+=G.sat[nr2][nc2]; cnt++; }
    }
    if(cnt && tot/cnt>=60) G.doored[nr*1000+nc]=true;
  }

  // Bio-Generator awakens at sat>=70 — triggers enemy wave
  if(t===T.BIO_GEN && s>=70 && !G.genAwake[r*1000+c]){
    G.genAwake[r*1000+c]=true;
    G.tilesTransformed++;
    triggerBioGenWave(c*TILE+TILE/2, r*TILE+TILE/2);
  }

  // Spore Vent activates at sat>=50
  if(t===T.SPORE_VENT && s>=50 && !G.ventActive[r*1000+c]){
    G.ventActive[r*1000+c]=true;
    G.tilesTransformed++;
    playSound('spore');
  }
}
