  if(rf<0.15&&G.ticks%10<5){
    ctx.strokeStyle=C.bright; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(px,py,G.psize+7,0,Math.PI*2); ctx.stroke();
