const enemySpeed = 2;
const spawnInterval = 2000;
const difficultyIncrease = 100;

let player = { x: 50, y: 100, width: 50, height: 50, velocityY: 0, jumping: false };
let platforms = [{ x: 0, y: 550, width: 800, height: 50 }];
let enemies = [];
let lastTime = performance.now();
let spawnTimer = spawnInterval;
let difficulty = 1;

function update(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    // Player movement
    if (keys['ArrowLeft']) player.x -= playerSpeed;
    if (keys['ArrowRight']) player.x += playerSpeed;
    if (keys['ArrowUp'] && !player.jumping) {
        player.velocityY = jumpSpeed;
        player.jumping = true;
    }

    // Apply gravity
    player.velocityY += gravity;
    player.y += player.velocityY;

    // Collision detection with platforms
    platforms.forEach(platform => {
        if (player.y + player.height <= platform.y &&
            player.y + player.height + player.velocityY > platform.y &&
            player.x + player.width > platform.x &&
            player.x < platform.x + platform.width) {
            player.y = platform.y - player.height;
            player.velocityY = 0;
            player.jumping = false;
        }
    });

    // Enemy movement and collision detection
    enemies.forEach((enemy, index) => {
        enemy.x -= enemySpeed;
        if (enemy.x + enemy.width < 0) enemies.splice(index, 1);

        // Simple collision detection with player
        if (player.x < enemy.x + enemy.width &&
            player.x + player.width > enemy.x &&
            player.y < enemy.y + enemy.height &&
