        spawnTimer = spawnInterval - difficulty * difficultyIncrease;
        enemies.push({ x: canvas.width, y: 500 - Math.random() * 200, width: 30, height: 30 });
    }

    // Increase difficulty
    if (enemies.length > difficulty) {
        difficulty++;
    }

