}

function updatePlayer() {
    if (keys.ArrowLeft) player.angle -= 0.05;
    if (keys.ArrowRight) player.angle += 0.05;
    if (keys.ArrowUp) {
        player.x += Math.cos(player.angle) * player.speed;
        player.y += Math.sin(player.angle) * player.speed;
    }

    if (keys.Space) {
        bullets.push({
            x: player.x + Math.cos(player.angle) * player.radius,
            y: player.y + Math.sin(player.angle) * player.radius,
            angle: player.angle,
            speed: bulletSpeed
        });
    }
}

function updateBullets() {
    bullets.forEach(bullet => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed;
        bullet.y += Math.sin(bullet.angle) * bullet.speed;
    });
}

function updateAsteroids() {
    asteroids.forEach(asteroid => {
        asteroid.x += Math.cos(asteroid.angle) * asteroid.speed;
        asteroid.y += Math.sin(asteroid.angle) * asteroid.speed;
    });
}

function detectCollisions() {
    asteroids.forEach((asteroid, i) => {
        bullets.forEach((bullet, j) => {
            const distX = asteroid.x - bullet.x;
            const distY = asteroid.y - bullet.y;
            const distance = Math.sqrt(distX * distX + distY * distY);
            if (distance < asteroid.size / 2) {
                asteroids.splice(i, 1);
                bullets.splice(j, 1);
                createAsteroid();
                return;
            }
        });
        const distX = asteroid.x - player.x;
        const distY = asteroid.y - player.y;
        const distance = Math.sqrt(distX * distX + distY * distY);
        if (distance < asteroid.size / 2) {
            player.health -= 10;
            if (player.health <= 0) {
                resetGame();
            }
        }
    });
}

function resetGame() {
    player.health = 100;
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    bullets.length = 0;
    asteroids.length = 0;
    spawnAsteroids();
}

function drawPlayer() {
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.beginPath();
    ctx.arc(0, 0, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.restore();
}

function drawBullets() {
    ctx.fillStyle = 'white';
    bullets.forEach(bullet => {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
        ctx.fill();
    });
}

function drawAsteroids() {
    ctx.fillStyle = 'red';
    asteroids.forEach(asteroid => {
        ctx.beginPath();
        ctx.arc(asteroid.x, asteroid.y, asteroid.size / 2, 0, Math.PI * 2);
        ctx.fill();
    });
}

function drawHealthBar() {
    ctx.fillStyle = 'green';
    ctx.fillRect(10, 10, player.health, 20);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(10, 10, 100, 20);
}

function update() {
    updatePlayer();
    updateBullets();
    updateAsteroids();
    detectCollisions();
    spawnAsteroids();
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPlayer();
    drawBullets();
    drawAsteroids();
    drawHealthBar();
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    update();
    render();

    if (player.health > 0) {
        requestAnimationFrame(gameLoop);
    }
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

let lastTime = 0;
spawnAsteroids();
requestAnimationFrame(gameLoop);
