// Maze Chase Game with Basic AI Opponent

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game settings
const TPS = 20; // Ticks Per Second
const tickDuration = 1000 / TPS;
let lastTickTime = 0;
const mazeSize = 20;
const cellSize = 30;
const wallThickness = 5;
const playerSpeed = 3;
const aiSpeed = 2;

// Colors
const wallColor = '#000';
const playerColor = '#00f';
const aiColor = '#f00';

// Maze generation
function generateMaze(size) {
    const maze = Array(size).fill().map(() => Array(size).fill(1));
    const directions = [
        { dx: 0, dy: -2, nx: 0, ny: -1 },
        { dx: 0, dy: 2, nx: 0, ny: 1 },
        { dx: -2, dy: 0, nx: -1, ny: 0 },
        { dx: 2, dy: 0, nx: 1, ny: 0 }
    ];

    function carve(x, y) {
        maze[x][y] = 0;
        const neighbors = directions.slice().sort(() => Math.random() - 0.5);
        for (const { dx, dy, nx, ny } of neighbors) {
            const newX = x + dx;
            const newY = y + dy;
            if (newX >= 0 && newX < size && newY >= 0 && newY < size && maze[newX][newY] === 1) {
                maze[x + nx][y + ny] = 0;
                carve(newX, newY);
            }
        }
    }

    carve(Math.floor(size / 2), Math.floor(size / 2));
    return maze;
}

const maze = generateMaze(mazeSize);

// Player and AI
const player = { x: mazeSize * cellSize / 2, y: mazeSize * cellSize / 2 };
const ai = { x: mazeSize * cellSize / 2, y: mazeSize * cellSize / 2 };

// Input handling
const keys = { up: false, down: false, left: false, right: false };
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp': keys.up = true; break;
        case 'ArrowDown': keys.down = true; break;
        case 'ArrowLeft': keys.left = true; break;
        case 'ArrowRight': keys.right = true; break;
    }
});
document.addEventListener('keyup', (e) => {
    switch (e.key) {
        case 'ArrowUp': keys.up = false; break;
        case 'ArrowDown': keys.down = false; break;
        case 'ArrowLeft': keys.left = false; break;
        case 'ArrowRight': keys.right = false; break;
    }
});

// Collision detection
function isWall(x, y) {
    const cellX = Math.floor(x / cellSize);
    const cellY = Math.floor(y / cellSize);
    return maze[cellX][cellY] === 1;
}

// AI movement
function aiMove() {
    const directions = [
        { dx: 0, dy: -1 }, // up
        { dx: 0, dy: 1 },  // down
        { dx: -1, dy: 0 }, // left
        { dx: 1, dy: 0 }   // right
    ];
    let bestDirection = null;
    let bestDistance = Infinity;
    for (const { dx, dy } of directions) {
        const newX = ai.x + dx * playerSpeed;
        const newY = ai.y + dy * playerSpeed;
        if (!isWall(newX, newY)) {
            const distance = Math.hypot(newX - player.x, newY - player.y);
            if (distance < bestDistance) {
                bestDistance = distance;
                bestDirection = { dx, dy };
            }
        }
    }
    if (bestDirection) {
        ai.x += bestDirection.dx * aiSpeed;
        ai.y += bestDirection.dy * aiSpeed;
    }
}

// Game loop
function gameLoop(currentTime) {
    const deltaTime = currentTime - lastTickTime;
    if (deltaTime >= tickDuration) {
        lastTickTime = currentTime - (deltaTime % tickDuration);

        // Player movement
        if (keys.up && !isWall(player.x, player.y - playerSpeed)) player.y -= playerSpeed;
        if (keys.down && !isWall(player.x, player.y + playerSpeed)) player.y += playerSpeed;
        if (keys.left && !isWall(player.x - playerSpeed, player.y)) player.x -= playerSpeed;
        if (keys.right && !isWall(player.x + playerSpeed, player.y)) player.x += playerSpeed;

        // AI movement
        aiMove();
    }

    // Rendering
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw maze
    for (let i = 0; i < mazeSize; i++) {
        for (let j = 0; j < mazeSize; j++) {
            if (maze[i][j] === 1) {
                ctx.fillStyle = wallColor;
                ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
            }
        }
    }

    // Draw player
    ctx.fillStyle = playerColor;
    ctx.fillRect(player.x - playerSpeed / 2, player.y - playerSpeed / 2, playerSpeed, playerSpeed);

    // Draw AI
    ctx.fillStyle = aiColor;
    ctx.fillRect(ai.x - aiSpeed / 2, ai.y - aiSpeed / 2, aiSpeed, aiSpeed);

    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
