const asteroids = [];
const bullets = [];
let score = 0;
let gameOver = false;

class Asteroid {
  constructor(x, y, r) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.a = Math.random() * Math.PI * 2;
    this.speed = Math.random() * 2 + 1;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
    ctx.stroke();
  }

  move() {
    this.x += Math.cos(this.a) * this.speed;
    this.y += Math.sin(this.a) * this.speed;
    if (this.x < 0 || this.x > canvas.width) this.x = (this.x + canvas.width) % canvas.width;
    if (this.y < 0 || this.y > canvas.height) this.y = (this.y + canvas.height) % canvas.height;
  }
}

class Bullet {
  constructor(x, y, a) {
    this.x = x;
    this.y = y;
    this.a = a;
    this.speed = 10;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 2, 0, Math.PI * 2);
    ctx.fill();
  }

  move() {
    this.x += Math.cos(this.a) * this.speed;
    this.y += Math.sin(this.a) * this.speed;
  }
}

function createAsteroids(num) {
  for (let i = 0; i < num; i++) {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const r = Math.random() * 20 + 10;
    asteroids.push(new Asteroid(x, y, r));
  }
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.a);
  ctx.beginPath();
  ctx.moveTo(10, 0);
  ctx.lineTo(-10, -5);
  ctx.lineTo(-10, 5);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

function drawBullets() {
  bullets.forEach(bullet => {
    bullet.draw();
    bullet.move();
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.draw();
    asteroid.move();
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, ai) => {
    bullets.forEach((bullet, bi) => {
      const dx = asteroid.x - bullet.x;
      const dy = asteroid.y - bullet.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < asteroid.r) {
        bullets.splice(bi, 1);
        asteroids.splice(ai, 1);
        score += Math.round(100 / asteroid.r);
        if (Math.random() < 0.5) {
          asteroids.push(new Asteroid(asteroid.x, asteroid.y, asteroid.r / 2));
          asteroids.push(new Asteroid(asteroid.x, asteroid.y, asteroid.r / 2));
