// BallDropGame
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const drag = 0.95;
const ballRadius = 10;
const groundY = canvas.height - ballRadius;
const maxCombo = 10;
let combo = 0;
let highScore = 0;
let isGameOver = false;

class Ball {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.vx = Math.random() * 4 - 2;
        this.vy = Math.random() * 3 - 1.5;
    }

    update() {
        this.vy += gravity;
        this.x += this.vx;
        this.y += this.vy;
        this.vx *= drag;

        if (this.y + this.vy > groundY) {
            this.vy = -this.vy * 0.7;
            this.y = groundY;
            combo = combo > 0 ? combo + 1 : 1;
            highScore = Math.max(highScore, combo);
            if (combo >= maxCombo) {
                isGameOver = true;
            }
        }

        if (this.x - this.vx < 0 || this.x - this.vx > canvas.width) {
            this.vx = -this.vx;
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, ballRadius, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
        ctx.closePath();
    }
}

const balls = [];
const numBalls = 5;
for (let i = 0; i < numBalls; i++) {
    balls.push(new Ball(Math.random() * canvas.width, Math.random() * canvas.height));
}

function drawText(text, x, y, color, font = '20px Arial') {
    ctx.fillStyle = color;
    ctx.font = font;
    ctx.fillText(text, x, y);
}

function drawScores() {
    drawText(`Combo: ${combo}`, 10, 30, 'black');
    drawText(`High Score: ${highScore}`, 10, 60, 'black');
}

function drawGameOver() {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawText('Game Over!', canvas.width / 2 - 100, canvas.height / 2, 'red', '40px Arial');
    drawText(`High Score: ${highScore}`, canvas.width / 2 - 100, canvas.height / 2 + 50, 'black');
}

function gameLoop() {
    if (isGameOver) {
        drawGameOver();
        return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (let ball of balls) {
        ball.update();
        ball.draw();
    }

    drawScores();

    requestAnimationFrame(gameLoop);
}

gameLoop();
