  windowWidth = window.innerWidth;
  windowHeight = window.innerHeight;
  canvas.width = windowWidth * devicePixelRatio;
  canvas.height = windowHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
