  ctx.font = '24px Arial';
  ctx.fillStyle = '#000';
  ctx.fillText(`Combo: x${comboMultiplier}`, 10, 30);
}

function drawPlot(x, y, size, crop) {
  ctx.fillStyle = '#f0f0c0';
  ctx.fillRect(x, y, size, size);
  ctx.fillStyle = crop ? '#00a000' : '#808080';
  ctx.fillRect(x + 2, y + 2, size - 4, size - 4);
}

function harvestPlot(x, y, size) {
  const now = Date.now();
  if (now - lastHarvestTime < harvestInterval) {
    comboMultiplier++;
  } else {
    comboMultiplier = 1;
  }
  lastHarvestTime = now;
  alert(`Harvested with combo x${comboMultiplier}!`);
  drawPlot(x, y, size, false);
}

function handleMouseDown(event) {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  const plotSize = 50;
  const plotX = Math.floor(x / plotSize) * plotSize;
  const plotY = Math.floor(y / plotSize) * plotSize;
  harvestPlot(plotX, plotY, plotSize);
}

