const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gridSize = 4;
const cellSize = 100;
const padding = 10;
const colors = {
  2: '#eee4da',
  4: '#ede0c8',
  8: '#f2b179',
  16: '#f59563',
  32: '#f67c5f',
  64: '#f65e3b',
  128: '#edcf72',
  256: '#edcc61',
  512: '#edc850',
  1024: '#edc53f',
  2048: '#edc22e',
  default: '#ccc0b3'
};

let board = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore'), 10) : 0;

function getRandomEmptyCell() {
  const emptyCells = [];
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (board[i][j] === 0) {
        emptyCells.push([i, j]);
      }
    }
  }
  return emptyCells[Math.floor(Math.random() * emptyCells.length)] || [0, 0];
}

function addNewTile() {
  const [i, j] = getRandomEmptyCell();
  board[i][j] = Math.random() > 0.9 ? 4 : 2;
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#aaa';
  for (let i = 0; i <= gridSize; i++) {
    ctx.beginPath();
    ctx.moveTo(i * cellSize, 0);
    ctx.lineTo(i * cellSize, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * cellSize);
    ctx.lineTo(canvas.width, i * cellSize);
    ctx.stroke();
  }
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const value = board[i][j];
      if (value !== 0) {
        ctx.fillStyle = colors[value] || colors.default;
        ctx.fillRect(j * cellSize + padding, i * cellSize + padding, cellSize - padding * 2, cellSize - padding * 2);
        ctx.font = 'bold 24px Arial';
        ctx.fillStyle = '#776e65';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value, j * cellSize + cellSize / 2, i * cellSize + cellSize / 2);
      }
    }
  }
}

function move(direction) {
  let moved = false;
  let newBoard = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
  for (let i = 0; i < gridSize; i++) {
    let row = [];
    for (let j = 0; j < gridSize; j++) {
      const value = direction === 'up' ? board[j][i] : direction === 'down' ? board[gridSize - 1 - j][i] : direction === 'left' ? board[i][j] : board[i][gridSize - 1 - j];
      if (value !== 0) {
        row.push(value);
      }
    }
    row = merge(row);
    for (let j = 0; j < gridSize; j++) {
      const value = direction === 'up' ? row[j] : direction === 'down' ? row[gridSize - 1 - j] : direction === 'left' ? row[j] : row[gridSize - 1 - j];
      if (value !== (direction === 'up' ? board[j][i] : direction === 'down' ? board[gridSize - 1 - j][i] : direction === 'left' ? board[i][j] : board[i][gridSize - 1 - j])) {
        moved = true;
      }
      newBoard[i][j] = value;
    }
  }
  if (moved) {
    board = newBoard;
    addNewTile();
    if (checkGameOver()) {
      alert('Game Over! Your score: ' + score);
      resetGame();
    }
  }
}

function merge(row) {
  for (let i = 0; i < row.length - 1; i++) {
    if (row[i] !== 0 && row[i] === row[i + 1]) {
      row[i] *= 2;
      row[i + 1] = 0;
      score += row[i];
    }
  }
  return row.filter(x => x !== 0);
}

function checkGameOver() {
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (board[i][j] === 0) {
        return false;
      }
      if ((i < gridSize - 1 && board[i][j] === board[i + 1][j]) || (j < gridSize - 1 && board[i][j] === board[i][j + 1])) {
        return false;
      }
    }
  }
  return true;
}

function resetGame() {
  board = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
  score = 0;
  addNewTile();
  addNewTile();
}

function update() {
  ctx.fillStyle = '#faf8ef';
  ctx.fillRect(0, 0, canvas.width, cellSize);
  ctx.font = 'bold 24px Arial';
  ctx.fillStyle = '#776e65';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('Score: ' + score, 10, cellSize / 2);
  ctx.fillText('High Score: ' + highScore, canvas.width / 2, cellSize / 2);
  drawBoard();
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
  requestAnimationFrame(update);
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':
      move('up');
      break;
    case 'ArrowDown':
      move('down');
      break;
    case 'ArrowLeft':
      move('left');
      break;
    case 'ArrowRight':
      move('right');
      break;
  }
});

addNewTile();
addNewTile();
update();
