const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let windowWidth = window.innerWidth;
let windowHeight = window.innerHeight;
canvas.width = windowWidth * devicePixelRatio;
canvas.height = windowHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

let isRunning = false;
let score = 0;
let spawnInterval = 2000;
let lastSpawnTime = 0;
let enemies = [];

class Runner {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.speed = 5;
  }

  update() {
    this.y += this.speed;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
}

class Enemy {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.speed = 3;
  }

  update() {
    this.y += this.speed;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
}

const runner = new Runner(windowWidth / 2, windowHeight - 100, 50);

function spawnEnemy() {
  const x = Math.random() * (windowWidth - 50);
  const y = -50;
  const size = 30;
  enemies.push(new Enemy(x, y, size));
}

function update() {
  if (!isRunning) return;
  const now = Date.now();
  if (now - lastSpawnTime > spawnInterval) {
    spawnEnemy();
    lastSpawnTime = now;
    spawnInterval = Math.max(spawnInterval - 100, 500); // Ramp up difficulty
  }

  runner.update();
  enemies.forEach(enemy => {
    enemy.update();
    if (checkCollision(runner, enemy)) {
      gameOver();
    }
  });

  // Remove enemies that have moved off screen
  enemies = enemies.filter(enemy => enemy.y < windowHeight);
}

function draw() {
  ctx.clearRect(0, 0, windowWidth, windowHeight);

  runner.draw();
  enemies.forEach(enemy => enemy.draw());

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function checkCollision(runner, enemy) {
  return (
    runner.x < enemy.x + enemy.size &&
    runner.x + runner.size > enemy.x &&
    runner.y < enemy.y + enemy.size &&
    runner.y + runner.size > enemy.y
  );
}

function gameOver() {
  isRunning = false;
  alert(`Game Over! Your Score: ${score}`);
  score = 0;
  enemies = [];
  runner.y = windowHeight - 100;
  spawnInterval = 2000;
}

function startGame() {
  isRunning = true;
  lastSpawnTime = Date.now();
  requestAnimationFrame(gameLoop);
}

function gameLoop() {
  update();
  draw();
  if (isRunning) requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', startGame);

function resize() {
  windowWidth = window.innerWidth;
  windowHeight = window.innerHeight;
  canvas.width = windowWidth * devicePixelRatio;
  canvas.height = windowHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
