const paddle = {
  x: canvas.width / 2 - 50,
  y: canvas.height - 20,
  width: 100,
  height: 10,
  speed: 7
};

const ball = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  speedX: 5,
  speedY: 5
};

const bricks = [];
const brickRows = 5;
const brickCols = 10;
const brickWidth = 50;
const brickHeight = 20;
const brickPadding = 10;
const brickOffsetTop = 30;
const brickOffsetLeft = 30;

for (let row = 0; row < brickRows; row++) {
  bricks[row] = [];
  for (let col = 0; col < brickCols; col++) {
    bricks[row][col] = { x: 0, y: 0, status: 1 };
  }
}

const powerUps = [];
const powerUpTypes = ['grow', 'shrink', 'fast', 'slow'];
const powerUpSpeed = 3;

function drawPaddle() {
  ctx.beginPath();
  ctx.rect(paddle.x, paddle.y, paddle.width, paddle.height);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawBricks() {
  for (let row = 0; row < brickRows; row++) {
    for (let col = 0; col < brickCols; col++) {
      if (bricks[row][col].status === 1) {
        const brickX = (col * (brickWidth + brickPadding)) + brickOffsetLeft;
        const brickY = (row * (brickHeight + brickPadding)) + brickOffsetTop;
        bricks[row][col].x = brickX;
        bricks[row][col].y = brickY;
        ctx.beginPath();
        ctx.rect(brickX, brickY, brickWidth, brickHeight);
        ctx.fillStyle = '#0095DD';
        ctx.fill();
        ctx.closePath();
      }
    }
  }
}

function drawPowerUps() {
  for (let i = 0; i < powerUps.length; i++) {
    const powerUp = powerUps[i];
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = powerUp.type === 'grow' ? 'green' : powerUp.type === 'shrink' ? 'red' : powerUp.type === 'fast' ? 'blue' : 'orange';
    ctx.fill();
    ctx.closePath();
  }
}

function collisionDetection() {
  for (let row = 0; row < brickRows; row++) {
    for (let col = 0; col < brickCols; col++) {
      const b = bricks[row][col];
      if (b.status === 1) {
        if (ball.x > b.x && ball.x < b.x + brickWidth && ball.y > b.y && ball.y < b.y + brickHeight) {
          ball.speedY = -ball.speedY;
          b.status = 0;
          const powerUpType = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
          powerUps.push({ x: b.x + brickWidth / 2, y: b.y, type: powerUpType });
        }
      }
    }
  }

  if (ball.x + ball.speedX > canvas.width - ball.radius || ball.x + ball.speedX < ball.radius) {
    ball.speedX = -ball.speedX;
  }
  if (ball.y + ball.speedY < ball.radius) {
    ball.speedY = -ball.speedY;
  } else if (ball.y + ball.speedY > canvas.height - ball.radius) {
    if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
      ball.speedY = -ball.speedY;
    } else {
      clearInterval(interval);
      alert('GAME OVER');
      document.location.reload();
    }
  }
}

function powerUpCollisionDetection() {
  for (let i = 0; i < powerUps.length; i++) {
    const powerUp = powerUps[i];
    if (powerUp.y + powerUpSpeed > canvas.height) {
      powerUps.splice(i, 1);
    } else if (powerUp.x > paddle.x && powerUp.x < paddle.x + paddle.width && powerUp.y > paddle.y && powerUp.y < paddle.y + paddle.height) {
      switch (powerUp.type) {
        case 'grow':
          paddle.width += 20;
          break;
        case 'shrink':
          paddle.width -= 20;
          if (paddle.width < 20) paddle.width = 20;
          break;
        case 'fast':
          ball.speedX *= 1.5;
          ball.speedY *= 1.5;
          break;
        case 'slow':
          ball.speedX /= 1.5;
          ball.speedY /= 1.5;
          break;
      }
      powerUps.splice(i, 1);
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBricks();
  drawBall();
  drawPaddle();
  drawPowerUps();
  collisionDetection();
  powerUpCollisionDetection();

  if (rightPressed && paddle.x < canvas.width - paddle.width) {
    paddle.x += paddle.speed;
  } else if (leftPressed && paddle.x > 0) {
    paddle.x -= paddle.speed;
  }

  ball.x += ball.speedX;
  ball.y += ball.speedY;

  for (let i = 0; i < powerUps.length; i++) {
    powerUps[i].y += powerUpSpeed;
  }

  requestAnimationFrame(draw);
}

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);

let rightPressed = false;
let leftPressed = false;

function keyDownHandler(e) {
  if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = true;
  } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = true;
  }
}

function keyUpHandler(e) {
  if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = false;
  } else if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = false;
  }
}

const interval = setInterval(draw, 10);
