const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const POWER_UPS = ['speed', 'health', 'strength'];

let lastTime = 0;
let fixedTimeStep = 1000 / 60; // 60 FPS
let accumulator = 0;

class Tile {
  constructor(x, y, type) {
    this.x = x;
    this.y = y;
    this.type = type;
  }

  draw() {
    ctx.fillStyle = this.type === 'wall' ? '#333' : '#fff';
    ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  }
}

class PowerUp {
  constructor(x, y, type) {
    this.x = x;
    this.y = y;
    this.type = type;
  }

  draw() {
    ctx.fillStyle = 'gold';
    ctx.beginPath();
    ctx.arc(this.x * TILE_SIZE + TILE_SIZE / 2, this.y * TILE_SIZE + TILE_SIZE / 2, TILE_SIZE / 4, 0, Math.PI * 2);
    ctx.fill();
  }
}

let tiles = [];
let powerUps = [];

function generateRoom() {
  tiles = [];
  powerUps = [];

  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      if (y === 0 || y === ROOM_HEIGHT - 1 || x === 0 || x === ROOM_WIDTH - 1) {
        tiles.push(new Tile(x, y, 'wall'));
      } else {
        tiles.push(new Tile(x, y, 'floor'));
      }
    }
  }

  for (let i = 0; i < 5; i++) {
    let x, y;
    do {
      x = Math.floor(Math.random() * (ROOM_WIDTH - 2)) + 1;
      y = Math.floor(Math.random() * (ROOM_HEIGHT - 2)) + 1;
    } while (powerUps.some(pu => pu.x === x && pu.y === y));

    powerUps.push(new PowerUp(x, y, POWER_UPS[Math.floor(Math.random() * POWER_UPS.length)]));
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  tiles.forEach(tile => tile.draw());
  powerUps.forEach(powerUp => powerUp.draw());
}

function update(deltaTime) {
  // Update logic here (if needed)
}

function gameLoop(timestamp) {
  let currentTime = timestamp;
  let deltaTime = currentTime - lastTime;

  lastTime = currentTime;
  accumulator += deltaTime;

  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  draw();

  requestAnimationFrame(gameLoop);
}

generateRoom();
requestAnimationFrame(gameLoop);
