const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;

const state = {
  current: 'menu',
  grid: [],
  score: 0,
  tiles: [],
  direction: null
};

const colors = {
  2: '#eee4da',
  4: '#ede0c8',
  8: '#f2b179',
  16: '#f59563',
  32: '#f67c5f',
  64: '#f65e3b',
  128: '#edcf72',
  256: '#edcc61',
  512: '#edc850',
  1024: '#edc53f',
  2048: '#edc22e'
};

function resetGame() {
  state.grid = Array(4).fill().map(() => Array(4).fill(0));
  state.tiles = [];
  state.score = 0;
  addRandomTile();
  addRandomTile();
}

function addRandomTile() {
  const emptyCells = [];
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      if (state.grid[i][j] === 0) {
        emptyCells.push({ i, j });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { i, j } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    state.grid[i][j] = Math.random() < 0.9 ? 2 : 4;
    state.tiles.push({ x: j, y: i, value: state.grid[i][j] });
  }
}

function move(direction) {
  let moved = false;
  const newGrid = Array(4).fill().map(() => Array(4).fill(0));
  const newTiles = [];

  for (let row = 0; row < 4; row++) {
    let lastMerged = null;
    let newRow = Array(4).fill(0);

    for (let col = 0; col < 4; col++) {
      let idx = col;
      if (direction === 'up') idx = row;
      if (direction === 'down') idx = 3 - row;
      if (direction === 'left') idx = col;
      if (direction === 'right') idx = 3 - col;

      if (state.grid[row][idx] !== 0) {
        if (lastMerged !== null && state.grid[row][idx] === state.grid[row][lastMerged] && newRow[lastMerged] === 0) {
          newRow[lastMerged] = state.grid[row][idx] * 2;
          state.score += state.grid[row][idx] * 2;
          lastMerged = null;
          moved = true;
        } else {
          newRow[newRow.lastIndexOf(0)] = state.grid[row][idx];
          lastMerged = newRow.lastIndexOf(0);
          moved = true;
        }
      }
    }

    for (let col = 0; col < 4; col++) {
      let idx = col;
      if (direction === 'up') idx = row;
      if (direction === 'down') idx = 3 - row;
      if (direction === 'left') idx = col;
      if (direction === 'right') idx = 3 - col;

      newGrid[row][idx] = newRow[col];
      if (newGrid[row][idx] !== 0) {
        newTiles.push({ x: idx, y: row, value: newGrid[row][idx] });
      }
    }
  }

  state.grid = newGrid;
  state.tiles = newTiles;
  if (moved) {
    addRandomTile();
    checkGameOver();
  }
}

function checkGameOver() {
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      if (state.grid[i][j] === 0) return;
      if (i > 0 && state.grid[i][j] === state.grid[i - 1][j]) return;
      if (j > 0 && state.grid[i][j] === state.grid[i][j - 1]) return;
    }
  }
  state.current = 'gameover';
}

function drawMenu() {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#000000';
  ctx.font = '36px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('2048', canvas.width / 2, canvas.height / 2 - 40);
  ctx.font = '24px Arial';
  ctx.fillText('Press Space to Start', canvas.width / 2, canvas.height / 2 + 20);
}

function drawPlaying() {
  ctx.fillStyle = '#bbada0';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#ffffff';
  ctx.font = '24px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'top';
  ctx.fillText(`Score: ${state.score}`, canvas.width - 10, 10);

  state.tiles.forEach(tile => {
    ctx.fillStyle = colors[tile.value] || '#000000';
    ctx.fillRect(tile.x * 100 + 10, tile.y * 100 + 10, 80, 80);
    ctx.fillStyle = '#ffffff';
    ctx.font = '24px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(tile.value, tile.x * 100 + 50, tile.y * 100 + 50);
  });
}

function drawPaused() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#ffffff';
  ctx.font = '36px Arial';
  ctx.textAlign = 'center';
