let lastTime = 0;

class Block {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.color = `hsl(${Math.random() * 360}, 100%, 50%)`;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  }

  update(dt) {
    this.y += GRAVITY * dt;
    if (this.y > ROWS) {
      this.y = ROWS;
    }
  }
}

class Particle {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
    this.size = Math.random() * 2 + 1;
    this.lifetime = 0.5 + Math.random() * 0.5; // seconds
    this.alpha = 1;
  }

  draw() {
    ctx.fillStyle = `rgba(${this.color}, ${this.alpha})`;
    ctx.beginPath();
    ctx.arc(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, this.size, 0, Math.PI * 2);
    ctx.fill();
  }

  update(dt) {
    this.lifetime -= dt;
    if (this.lifetime <= 0) {
      return false;
    }
    this.alpha = this.lifetime / 0.5;
    return true;
  }
}

function createBlock() {
  const x = Math.floor(Math.random() * COLS);
  blocks.push(new Block(x, -1));
  createParticles(x, -1);
}

function createParticles(x, y) {
  for (let i = 0; i < 10; i++) {
    const color = `hsl(${Math.random() * 360}, 100%, 50%)`;
    particles.push(new Particle(x, y, color));
  }
}

function update(dt) {
  blocks.forEach(block => block.update(dt));
  blocks = blocks.filter(block => block.y < ROWS);

  particles.forEach(particle => particle.update(dt));
  particles = particles.filter(particle => particle.update(dt));
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(block => block.draw());
  particles.forEach(particle => particle.draw());
}

function gameLoop(time) {
