const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

const boardSize = 8;
const cellSize = Math.min(canvas.width, canvas.height) / boardSize;
const colors = ['#FF5733', '#33FF57', '#3357FF', '#F333FF', '#33FFF3', '#F3FF33'];
let board = [];
let score = 0;
let level = 1;
let combo = 0;
let isMatching = false;

function getRandomColor() {
  return colors[Math.floor(Math.random() * colors.length)];
}

function createBoard() {
  for (let i = 0; i < boardSize; i++) {
    board[i] = [];
    for (let j = 0; j < boardSize; j++) {
      board[i][j] = getRandomColor();
    }
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize; j++) {
      ctx.fillStyle = board[i][j];
      ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(j * cellSize, i * cellSize, cellSize, cellSize);
    }
  }
}

function checkMatches() {
  let matches = [];
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize - 2; j++) {
      if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
        matches.push([[i, j], [i, j + 1], [i, j + 2]]);
        let k = j + 3;
        while (k < boardSize && board[i][k] === board[i][j]) {
          matches[matches.length - 1].push([i, k]);
          k++;
        }
      }
    }
  }
  for (let j = 0; j < boardSize; j++) {
    for (let i = 0; i < boardSize - 2; i++) {
      if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
        matches.push([[i, j], [i + 1, j], [i + 2, j]]);
        let k = i + 3;
        while (k < boardSize && board[k][j] === board[i][j]) {
          matches[matches.length - 1].push([k, j]);
          k++;
        }
      }
    }
  }
  return matches;
}

function removeMatches(matches) {
  matches.forEach(match => {
    match.forEach(([i, j]) => {
      board[i][j] = null;
    });
  });
}

function fillBoard() {
  for (let j = 0; j < boardSize; j++) {
    let nullCount = 0;
    for (let i = boardSize - 1; i >= 0; i--) {
      if (board[i][j] === null) {
        nullCount++;
      } else if (nullCount > 0) {
        board[i + nullCount][j] = board[i][j];
        board[i][j] = null;
      }
    }
    for (let i = nullCount - 1; i >= 0; i--) {
      board[i][j] = getRandomColor();
    }
  }
}

function updateBoard() {
  const matches = checkMatches();
  if (matches.length > 0) {
    isMatching = true;
    score += matches.length * combo * 10;
    combo++;
    removeMatches(matches);
    setTimeout(() => {
      fillBoard();
      updateBoard();
    }, 200);
  } else {
    isMatching = false;
    combo = 0;
  }
}

function handleSwap(i, j, k, l) {
  [board[i][j], board[k][l]] = [board[k][l], board[i][j]];
  const matches = checkMatches();
  if (matches.length > 0) {
    score += matches.length * combo * 10;
    combo++;
    removeMatches(matches);
    fillBoard();
    updateBoard();
  } else {
    [board[i][j], board[k][l]] = [board[k][l], board[i][j]];
  }
}

let selected = null;

canvas.addEventListener('click', (e) => {
  if (isMatching) return;
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor(((e.clientX - rect.left) / dpr - (e.clientX - rect.left) % cellSize) / cellSize);
  const y = Math.floor(((e.clientY - rect.top) / dpr - (e.clientY - rect.top) % cellSize) / cellSize);
  if (selected) {
    const [i, j] = selected;
    if (Math.abs(i - y) + Math.abs(j - x) === 1) {
      handleSwap(i, j, y, x);
    }
    selected = null;
  } else {
    selected = [y, x];
  }
});

function gameLoop() {
  updateBoard();
  drawBoard();
  requestAnimationFrame(gameLoop);
}

function newGame() {
  createBoard();
  score = 0;
  level = 1;
  combo = 0;
  gameLoop();
}

newGame();
