// Top-down arena shooter with keyboard and pointer controls
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.style.width = '100%';
canvas.style.height = '100%';
let dpr = window.devicePixelRatio || 1;
canvas.width = canvas.clientWidth * dpr;
canvas.height = canvas.clientHeight * dpr;
ctx.scale(dpr, dpr);

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 20,
    speed: 5,
    angle: 0,
    bullets: []
};

const enemies = [];
for (let i = 0; i < 5; i++) {
    enemies.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        size: 15,
        speed: 3
    });
}

const keys = {};

function handleKeys() {
    if (keys['ArrowUp'] || keys['w']) {
        player.y -= player.speed;
    }
    if (keys['ArrowDown'] || keys['s']) {
        player.y += player.speed;
    }
    if (keys['ArrowLeft'] || keys['a']) {
        player.x -= player.speed;
    }
    if (keys['ArrowRight'] || keys['d']) {
        player.x += player.speed;
    }
    if (keys[' ']) {
        player.bullets.push({
            x: player.x + player.size * Math.cos(player.angle),
            y: player.y + player.size * Math.sin(player.angle),
            size: 5,
            speed: 10,
            angle: player.angle
        });
        keys[' '] = false;
    }
}

function handlePointer(event) {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;
    player.angle = Math.atan2(mouseY - player.y, mouseX - player.x);
}

function updateBullets() {
    player.bullets.forEach(bullet => {
        bullet.x += bullet.speed * Math.cos(bullet.angle);
        bullet.y += bullet.speed * Math.sin(bullet.angle);
    });
    player.bullets = player.bullets.filter(bullet => 
        bullet.x > 0 && bullet.x < canvas.width && 
        bullet.y > 0 && bullet.y < canvas.height
    );
}

function checkCollisions() {
    enemies.forEach((enemy, i) => {
        player.bullets.forEach((bullet, j) => {
            if (Math.hypot(bullet.x - enemy.x, bullet.y - enemy.y) < enemy.size + bullet.size) {
                enemies.splice(i, 1);
                player.bullets.splice(j, 1);
            }
        });
    });
}

function drawPlayer() {
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.fillStyle = 'blue';
    ctx.fillRect(-player.size / 2, -player.size / 2, player.size, player.size);
    ctx.restore();
}

function drawBullets() {
    ctx.fillStyle = 'red';
    player.bullets.forEach(bullet => {
        ctx.fillRect(bullet.x - bullet.size / 2, bullet.y - bullet.size / 2, bullet.size, bullet.size);
    });
}

function drawEnemies() {
    ctx.fillStyle = 'green';
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x - enemy.size / 2, enemy.y - enemy.size / 2, enemy.size, enemy.size);
    });
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    handleKeys();
    updateBullets();
    checkCollisions();
    drawPlayer();
    drawBullets();
    drawEnemies();
    requestAnimationFrame(update);
}

document.addEventListener('keydown', event => keys[event.key] = true);
document.addEventListener('keyup', event => keys[event.key] = false);
document.addEventListener('mousemove', handlePointer);
document.addEventListener('touchmove', event => {
    event.preventDefault();
    handlePointer(event.touches[0]);
}, { passive: false });

update();
```

