  towerDefense.enemies.push({ x, y, width: 20, height: 20, health: 5 });
}

function spawnEnemies() {
  if (towerDefense.waveTimer > towerDefense.waveInterval) {
    for (let i = 0; i < towerDefense.wave; i++) {
      createEnemy();
    }
    towerDefense.wave++;
    towerDefense.waveTimer = 0;
  }
}

function moveEnemies() {
  towerDefense.enemies.forEach(enemy => {
    enemy.x -= towerDefense.enemySpeed;
  });
}

function drawEnemies() {
  towerDefense.enemies.forEach(enemy => {
    ctx.fillStyle = 'red';
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
  });
}

function placeTower(x, y) {
  const gridX = Math.floor(x / 40);
  const gridY = Math.floor(y / 40);
  if (towerDefense.grid[gridY][gridX] === null && towerDefense.money >= towerDefense.towerCost) {
    towerDefense.grid[gridY][gridX] = { x: gridX * 40, y: gridY * 40, width: 40, height: 40 };
    towerDefense.towers.push(towerDefense.grid[gridY][gridX]);
    towerDefense.money -= towerDefense.towerCost;
  }
}

function drawTowers() {
  towerDefense.towers.forEach(tower => {
    ctx.fillStyle = 'blue';
    ctx.fillRect(tower.x, tower.y, tower.width, tower.height);
  });
}

function shootBullets() {
  towerDefense.towers.forEach(tower => {
    const target = towerDefense.enemies.find(enemy => {
      return enemy.x + enemy.width > tower.x && enemy.x < tower.x + tower.width &&
             enemy.y + enemy.height > tower.y && enemy.y < tower.y + tower.height;
    });
    if (target) {
      towerDefense.bullets.push({ x: tower.x + tower.width / 2, y: tower.y + tower.height / 2, target });
    }
  });
}

