const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;

const gridSize = 20;
const gridWidth = canvas.width / gridSize;
const gridHeight = canvas.height / gridSize;

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let powerUp = { x: 5, y: 5 };
let powerUpActive = false;
let powerUpTimer = 0;
let score = 0;

function getRandomPosition() {
  return {
    x: Math.floor(Math.random() * gridWidth),
    y: Math.floor(Math.random() * gridHeight)
  };
}

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function drawGrid() {
  ctx.strokeStyle = '#ddd';
  for (let i = 0; i < gridWidth; i++) {
    ctx.beginPath();
    ctx.moveTo(i * gridSize, 0);
    ctx.lineTo(i * gridSize, canvas.height);
    ctx.stroke();
  }
  for (let j = 0; j < gridHeight; j++) {
    ctx.beginPath();
    ctx.moveTo(0, j * gridSize);
    ctx.lineTo(canvas.width, j * gridSize);
    ctx.stroke();
  }
}

function update() {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (head.x < 0 || head.x >= gridWidth || head.y < 0 || head.y >= gridHeight) {
    gameOver();
    return;
  }

  for (let i = 0; i < snake.length; i++) {
    if (head.x === snake[i].x && head.y === snake[i].y) {
      gameOver();
      return;
    }
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    food = getRandomPosition();
    if (Math.random() > 0.75) {
      powerUp = getRandomPosition();
      powerUpActive = true;
      powerUpTimer = 0;
    }
  } else {
    snake.pop();
  }

  if (powerUpActive && head.x === powerUp.x && head.y === powerUp.y) {
    powerUpActive = false;
    // Power-up effect: double growth for 5 seconds
    const originalLength = snake.length;
    setTimeout(() => {
      while (snake.length > originalLength) {
        snake.pop();
      }
    }, 5000);
  }

  if (powerUpActive) {
    powerUpTimer++;
    if (powerUpTimer >= 120) { // 5 seconds
      powerUpActive = false;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawGrid();
  drawRect(food.x, food.y, 'red');
  if (powerUpActive) {
    drawRect(powerUp.x, powerUp.y, 'blue');
  }
  snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 10);
}

function gameOver() {
  alert(`Game Over! Your score: ${score}`);
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  food = getRandomPosition();
  powerUp = getRandomPosition();
  score = 0;
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
  }
});

gameLoop();
