// Snake-style grid game with basic AI opponent
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const gridSize = 20;
const tileCount = canvas.width / gridSize;

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let aiSnake = [{ x: 18, y: 18 }];
let aiDirection = { x: 0, y: 0 };

function drawRect(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function getRandomFoodPosition() {
    return {
        x: Math.floor(Math.random() * tileCount),
        y: Math.floor(Math.random() * tileCount)
    };
}

function updateSnake() {
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
        food = getRandomFoodPosition();
    } else {
        snake.pop();
    }
}

function updateAISnake() {
    const head = { x: aiSnake[0].x + aiDirection.x, y: aiSnake[0].y + aiDirection.y };
    aiSnake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
        food = getRandomFoodPosition();
    } else {
        aiSnake.pop();
    }
    // Basic AI: Move towards the food
    if (aiSnake[0].x < food.x) aiDirection.x = 1;
    else if (aiSnake[0].x > food.x) aiDirection.x = -1;
    else aiDirection.x = 0;

    if (aiSnake[0].y < food.y) aiDirection.y = 1;
    else if (aiSnake[0].y > food.y) aiDirection.y = -1;
    else aiDirection.y = 0;
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawRect(food.x, food.y, 'red');
    snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
    aiSnake.forEach(segment => drawRect(segment.x, segment.y, 'blue'));
}

function gameLoop() {
    updateSnake();
    updateAISnake();
    draw();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = { x: 0, y: -1 };
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = { x: 0, y: 1 };
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = { x: -1, y: 0 };
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = { x: 1, y: 0 };
            break;
    }
});

gameLoop();
