  gravity: 0.5,
  jumpPower: -10
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 200;
let pipeInterval = 150;
let lastPipeTime = 0;

const particles = [];
const particleCount = 5;
const particleSize = 2;

function drawRect(x, y, width, height, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, width, height);
}

function drawCircle(x, y, radius, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();
}

function updatePlayer() {
  player.velocity += player.gravity;
  player.y += player.velocity;

  if (player.y + player.height > canvas.height) {
    player.y = canvas.height - player.height;
    player.velocity = 0;
  }
}

function updatePipes() {
  if (Date.now() - lastPipeTime > pipeInterval) {
    const pipeHeight = Math.random() * (canvas.height - pipeGap);
    pipes.push({
      x: canvas.width,
      y: 0,
      height: pipeHeight
    });
    pipes.push({
      x: canvas.width,
      y: pipeHeight + pipeGap,
      height: canvas.height - pipeHeight - pipeGap
    });
    lastPipeTime = Date.now();
    pipeInterval = Math.max(100, pipeInterval - 5);
  }

  pipes.forEach(pipe => {
    pipe.x -= 2;
  });

  pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);
}

function checkCollision() {
  return pipes.some(pipe => {
    return (player.x < pipe.x + pipeWidth &&
            player.x + player.width > pipe.x &&
            (player.y < pipe.y + pipe.height ||
             player.y + player.height > pipe.y + pipe.height));
  });
}

function createParticles(x, y) {
  for (let i = 0; i < particleCount; i++) {
    particles.push({
      x: x + player.width / 2,
      y: y + player.height / 2,
      dx: (Math.random() - 0.5) * 2,
      dy: (Math.random() - 0.5) * 2,
      size: particleSize
    });
  }
}

function updateParticles() {
  particles.forEach((particle, index) => {
    particle.x += particle.dx;
    particle.y += particle.dy;
    particle.size *= 0.95;

    if (particle.size < 0.1) {
      particles.splice(index, 1);
    }
  });
}

function drawParticles() {
  particles.forEach(particle => {
    drawCircle(particle.x, particle.y, particle.size, 'rgba(255, 255, 255, 0.8)');
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawRect(player.x, player.y, player.width, player.height, 'blue');

  pipes.forEach(pipe => {
    drawRect(pipe.x, pipe.y, pipeWidth, pipe.height, 'green');
  });

  drawParticles();
}

function gameLoop() {
  if (checkCollision()) {
    alert('Game Over!');
    location.reload();
    return;
  }

  updatePlayer();
  updatePipes();
  updateParticles();
  draw();

  requestAnimationFrame(gameLoop);
}

