// Snake Game with Combo Multiplier
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const grid = 20;
const cols = canvas.width / grid;
const rows = canvas.height / grid;
let snake;
let food;
let combo = 0;
let score = 0;
let lastTime = 0;
let direction = { x: 0, y: 0 };
let reverse = false;

function init() {
    snake = [{ x: 10, y: 10 }];
    food = { x: Math.floor(Math.random() * cols), y: Math.floor(Math.random() * rows) };
    combo = 0;
    score = 0;
    direction = { x: 0, y: 0 };
    reverse = false;
}

function update(time) {
    const delta = time - lastTime;
    if (delta < 100) return;
    lastTime = time;

    if (reverse) {
        direction = { x: -direction.x, y: -direction.y };
        reverse = false;
    }

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= cols || head.y < 0 || head.y >= rows || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
        init();
        return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        score += combo + 1;
        combo++;
        food = { x: Math.floor(Math.random() * cols), y: Math.floor(Math.random() * rows) };
    } else {
        snake.pop();
    }

    if (combo > 5) {
        combo = 0;
        reverse = true;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x * grid, segment.y * grid, grid, grid);
    });

    ctx.fillStyle = 'red';
    ctx.fillRect(food.x * grid, food.y * grid, grid, grid);

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score} Combo: ${combo}`, 10, 30);
}

function gameLoop(time) {
    update(time);
    draw();
    requestAnimationFrame(gameLoop);
}

init();
gameLoop(0);

document.addEventListener('keydown', e => {
    const key = e.key;
    if (key === 'ArrowUp' && direction.y === 0) {
        direction = { x: 0, y: -1 };
    } else if (key === 'ArrowDown' && direction.y === 0) {
        direction = { x: 0, y: 1 };
    } else if (key === 'ArrowLeft' && direction.x === 0) {
        direction = { x: -1, y: 0 };
    } else if (key === 'ArrowRight' && direction.x === 0) {
        direction = { x: 1, y: 0 };
    }
});
