  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const radius = getRandomInt(10, 30);
  const angle = Math.random() * Math.PI * 2;
  const speed = getRandomInt(1, 3);
  asteroids.push({ x, y, radius, angle, speed });
}

function drawPlayer() {
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'blue';
  ctx.fill();
  ctx.closePath();
}

function drawBullets() {
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 3, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.closePath();
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();
  });
}

function drawHealthBar() {
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, player.health * 8, 20);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(10, 10, player.health * 8, 20);
}

function updatePlayer() {
  player.x += player.speed * Math.cos(player.angle);
  player.y += player.speed * Math.sin(player.angle);

  if (player.x < 0) player.x = canvas.width;
  if (player.x > canvas.width) player.x = 0;
  if (player.y < 0) player.y = canvas.height;
  if (player.y > canvas.height) player.y = 0;
}

function updateBullets() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    bullets[i].x += Math.cos(bullets[i].angle) * 5;
    bullets[i].y += Math.sin(bullets[i].angle) * 5;

    if (bullets[i].x < 0 || bullets[i].x > canvas.width || bullets[i].y < 0 || bullets[i].y > canvas.height) {
      bullets.splice(i, 1);
    }
  }
}

function updateAsteroids() {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    asteroids[i].x += Math.cos(asteroids[i].angle) * asteroids[i].speed;
    asteroids[i].y += Math.sin(asteroids[i].angle) * asteroids[i].speed;

    if (asteroids[i].x < 0 || asteroids[i].x > canvas.width || asteroids[i].y < 0 || asteroids[i].y > canvas.height) {
      asteroids.splice(i, 1);
    }
  }
}

function checkCollisions() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    for (let j = asteroids.length - 1; j >= 0; j--) {
      const dx = bullets[i].x - asteroids[j].x;
      const dy = bullets[i].y - asteroids[j].y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance < bullets[i].radius + asteroids[j].radius) {
        bullets.splice(i, 1);
        asteroids.splice(j, 1);
        break;
      }
    }
  }

  for (let i = asteroids.length - 1; i >= 0; i--) {
    const dx = player.x - asteroids[i].x;
    const dy = player.y - asteroids[i].y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance < player.radius + asteroids[i].radius) {
      player.health -= 10;
      asteroids.splice(i, 1);
      if (player.health <= 0) {
        respawnPlayer();
      }
    }
  }
}

function respawnPlayer() {
  player.x = canvas.width / 2;
  player.y = canvas.height / 2;
  player.health = 100;
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer();
  updateBullets();
  updateAsteroids();
  checkCollisions();

  drawPlayer();
  drawBullets();
  drawAsteroids();
  drawHealthBar();

  requestAnimationFrame(gameLoop);
}

function shootBullet() {
  bullets.push({
    x: player.x + Math.cos(player.angle) * player.radius,
    y: player.y + Math.sin(player.angle) * player.radius,
    angle: player.angle
  });
}

canvas.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
      player.angle -= 0.05;
      break;
    case 'ArrowRight':
      player.angle += 0.05;
      break;
    case 'ArrowUp':
