class Fish {
  constructor(x, y, speed) {
    this.x = x;
    this.y = y;
    this.speed = speed;
    this.width = 20;
    this.height = 10;
  }

  update() {
    this.y += this.speed;
    if (this.y > canvas.height) {
      this.y = -this.height;
      this.x = Math.random() * canvas.width;
    }
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Enemy {
  constructor(x, y, speed) {
    this.x = x;
    this.y = y;
    this.speed = speed;
    this.width = 30;
    this.height = 15;
  }

  update() {
    this.x += this.speed;
    if (this.x > canvas.width) {
      this.x = -this.width;
      this.y = Math.random() * canvas.height;
    }
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }

  collidesWith(fish) {
    return (
      this.x < fish.x + fish.width &&
      this.x + this.width > fish.x &&
      this.y < fish.y + fish.height &&
      this.y + this.height > fish.y
    );
  }
}

class Game {
  constructor() {
    this.fish = new Fish(canvas.width / 2, canvas.height - 50, 2);
    this.enemies = [];
    this.spawnTimer = 0;
    this.spawnInterval = 2000;
    this.difficultyMultiplier = 1.1;
  }

  update(deltaTime) {
    this.fish.update();
    this.enemies.forEach(enemy => enemy.update());
    this.spawnTimer += deltaTime;
    if (this.spawnTimer >= this.spawnInterval) {
      this.spawnTimer = 0;
      this.spawnInterval *= this.difficultyMultiplier;
      const x = Math.random() * canvas.width;
      const y = Math.random() * canvas.height;
      const speed = 1 + Math.random() * 2;
      this.enemies.push(new Enemy(x, y, speed));
    }
    this.enemies = this.enemies.filter(enemy => !enemy.collidesWith(this.fish));
  }

  draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    this.fish.draw();
    this.enemies.forEach(enemy => enemy.draw());
  }
}

const game = new Game();

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTimestamp;
  lastTimestamp = timestamp;
  game.update(deltaTime);
  game.draw();
  requestAnimationFrame(gameLoop);
}

