                            tiles[y][newX] = tiles[y][x];
                            tiles[y][x] = 0;
                            moved = true;
                        }
                    }
                }
            }
        }
    } else if (dir === 'right') {
        for (let y = 0; y < gridSize; y++) {
            for (let x = gridSize - 2; x >= 0; x--) {
                if (tiles[y][x] !== 0) {
                    for (let newX = x + 1; newX < gridSize; newX++) {
                        if (tiles[y][newX] !== 0) {
                            if (tiles[y][newX] === tiles[y][x]) {
