const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gameState = {
    state: 'menu',
    score: 0,
    player: {
        x: canvas.width / 2,
        y: canvas.height / 2,
        radius: 10,
        speed: 5
    },
    enemies: [],
    bullets: [],
    lastTime: performance.now(),
    fixedTimeStep: 1000 / 60,
    accumulator: 0
};

const spawnEnemy = () => {
    const x = Math.random() < 0.5 ? -50 : canvas.width + 50;
    const y = Math.random() * canvas.height;
    const direction = x < 0 ? 1 : -1;
    gameState.enemies.push({ x, y, radius: 10, speed: 2 * direction });
};

const update = (delta) => {
    const { player, enemies, bullets } = gameState;

    switch (gameState.state) {
        case 'playing':
            // Player movement
            if (keys['ArrowUp'] && player.y > 0) player.y -= player.speed;
            if (keys['ArrowDown'] && player.y < canvas.height) player.y += player.speed;
            if (keys['ArrowLeft'] && player.x > 0) player.x -= player.speed;
            if (keys['ArrowRight'] && player.x < canvas.width) player.x += player.speed;

            // Shoot bullets
            if (keys['Space'] && bullets.length === 0) {
                bullets.push({ x: player.x, y: player.y, radius: 3, speed: 10 });
            }

            // Update bullets
            bullets.forEach((bullet, index) => {
                bullet.x += bullet.speed;
                if (bullet.x > canvas.width) {
                    bullets.splice(index, 1);
                }
            });

            // Update enemies
            enemies.forEach((enemy, index) => {
                enemy.x += enemy.speed;
                if (enemy.x < -50 || enemy.x > canvas.width + 50) {
                    enemies.splice(index, 1);
                }
            });

            // Collision detection
            enemies.forEach((enemy, enemyIndex) => {
                bullets.forEach((bullet, bulletIndex) => {
                    const dx = enemy.x - bullet.x;
                    const dy = enemy.y - bullet.y;
                    const distance = Math.sqrt(dx * dx + dy * dy);
                    if (distance < enemy.radius + bullet.radius) {
                        enemies.splice(enemyIndex, 1);
                        bullets.splice(bulletIndex, 1);
                        gameState.score++;
                    }
                });
            });

            // Check for enemy collision with player
            enemies.forEach((enemy) => {
                const dx = player.x - enemy.x;
                const dy = player.y - enemy.y;
                const distance = Math.sqrt(dx * dx + dy * dy);
                if (distance < player.radius + enemy.radius) {
                    gameState.state = 'gameover';
                }
            });

            // Spawn new enemies
            if (Math.random() < 0.05) {
                spawnEnemy();
            }
            break;
        case 'gameover':
            // Reset game state
            if (keys['Enter']) {
                gameState.state = 'menu';
                gameState.score = 0;
                gameState.enemies = [];
                gameState.bullets = [];
            }
            break;
    }
};

const render = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    switch (gameState.state) {
        case 'menu':
            ctx.font = '30px Arial';
            ctx.fillStyle = 'white';
            ctx.fillText('Press Enter to Start', canvas.width / 2 - 150, canvas.height / 2);
            break;
        case 'playing':
            // Draw player
            ctx.beginPath();
            ctx.arc(gameState.player.x, gameState.player.y, gameState.player.radius, 0, Math.PI * 2);
            ctx.fillStyle = 'blue';
            ctx.fill();

            // Draw enemies
            gameState.enemies.forEach((enemy) => {
                ctx.beginPath();
                ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
                ctx.fillStyle = 'red';
                ctx.fill();
            });

            // Draw bullets
            gameState.bullets.forEach((bullet) => {
                ctx.beginPath();
                ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
                ctx.fillStyle = 'yellow';
                ctx.fill();
            });

            // Draw score
            ctx.font = '20px Arial';
            ctx.fillStyle = 'white';
            ctx.fillText(`Score: ${gameState.score}`, 10, 30);
            break;
        case 'gameover':
            ctx.font = '30px Arial';
            ctx.fillStyle = 'white';
            ctx.fillText('Game Over', canvas.width / 2 - 70, canvas.height / 2 - 30);
            ctx.fillText(`Final Score: ${gameState.score}`, canvas.width / 2 - 100, canvas.height / 2 + 30);
            ctx.fillText('Press Enter to Restart', canvas.width / 2 - 150, canvas.height / 2 + 60);
            break;
    }
};

const mainLoop = (currentTime) => {
    const delta = currentTime - gameState.lastTime;
    gameState.lastTime = currentTime;
    gameState.accumulator += delta;

    while (gameState.accumulator >= gameState.fixedTimeStep) {
        update(gameState.fixedTimeStep);
        gameState.accumulator -= gameState.fixedTimeStep;
    }

    render();
    requestAnimationFrame(mainLoop);
};

const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.key] = true;
});

document.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

mainLoop(performance.now());
