const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const bird = { x: 50, y: canvas.height / 2, vy: 0, gravity: 0.5, lift: -10 };
const pipes = [];
const gap = 150;
const pipeWidth = 75;
const pipeSpeed = 2;
const particles = [];
const particleCount = 10;

function createParticle(x, y) {
  for (let i = 0; i < particleCount; i++) {
    particles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * 3,
      vy: (Math.random() - 0.5) * 3,
      size: Math.random() * 3 + 1,
      life: Math.random() * 20 + 10
    });
  }
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.life--;
    if (p.life <= 0) {
      particles.splice(i, 1);
    }
  }
}

function drawParticles() {
  ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
  particles.forEach(p => {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  });
}

function createPipe() {
  const height = Math.random() * (canvas.height - gap) + gap / 2;
  pipes.push({ x: canvas.width, top: 0, bottom: height });
  pipes.push({ x: canvas.width, top: height + gap, bottom: canvas.height });
}

function updatePipes() {
  for (let i = pipes.length - 1; i >= 0; i--) {
    const p = pipes[i];
    p.x -= pipeSpeed;
    if (p.x + pipeWidth < 0) {
      pipes.splice(i, 1);
    }
  }
}

function drawPipes() {
  ctx.fillStyle = 'green';
  pipes.forEach(p => {
    ctx.fillRect(p.x, p.top, pipeWidth, p.bottom - p.top);
  });
}

function checkCollision() {
  const birdBox = { x: bird.x, y: bird.y, width: 10, height: 10 };
  for (const p of pipes) {
    const pipeBox = { x: p.x, y: p.top, width: pipeWidth, height: p.bottom - p.top };
    if (birdBox.x < pipeBox.x + pipeBox.width &&
        birdBox.x + birdBox.width > pipeBox.x &&
        birdBox.y < pipeBox.y + pipeBox.height &&
        birdBox.y + birdBox.height > pipeBox.y) {
      return true;
    }
  }
  return bird.y < 0 || bird.y > canvas.height;
}

function update() {
  bird.vy += bird.gravity;
  bird.y += bird.vy;
  if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 200) {
    createPipe();
  }
  updatePipes();
  updateParticles();
  if (checkCollision()) {
    bird.y = canvas.height / 2;
    bird.vy = 0;
    pipes.length = 0;
    particles.length = 0;
    createPipe();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'skyblue';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'red';
  ctx.fillRect(bird.x, bird.y, 10, 10);
  drawPipes();
  drawParticles();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

window.addEventListener('keydown', e => {
  if (e.code === 'Space') {
    bird.vy = bird.lift;
    createParticle(bird.x, bird.y);
  }
});
