const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const GRID_WIDTH = canvas.width / BLOCK_SIZE;
const GRID_HEIGHT = canvas.height / BLOCK_SIZE;

let state = 'menu';
let score = 0;
let currentBlock;
let blocks = [];
let linesCleared = 0;

const shapes = [
  { type: 'I', color: 'cyan', coords: [[0, 0], [0, 1], [0, 2], [0, 3]] },
  { type: 'O', color: 'yellow', coords: [[0, 0], [0, 1], [1, 0], [1, 1]] },
  { type: 'T', color: 'purple', coords: [[1, 0], [0, 1], [1, 1], [2, 1]] },
  { type: 'S', color: 'green', coords: [[0, 1], [0, 2], [1, 0], [1, 1]] },
  { type: 'Z', color: 'red', coords: [[1, 1], [1, 2], [0, 0], [0, 1]] },
  { type: 'J', color: 'blue', coords: [[0, 0], [0, 1], [0, 2], [1, 2]] },
  { type: 'L', color: 'orange', coords: [[1, 0], [1, 1], [1, 2], [0, 2]] }
];

function getRandomBlock() {
  const shape = shapes[Math.floor(Math.random() * shapes.length)];
  return {
    type: shape.type,
    color: shape.color,
    coords: shape.coords.map(([x, y]) => [x + Math.floor(GRID_WIDTH / 2) - 1, y])
  };
}

function drawBlock(block, offset = [0, 0]) {
  block.coords.forEach(([x, y]) => {
    ctx.fillStyle = block.color;
    ctx.fillRect((x + offset[0]) * BLOCK_SIZE, (y + offset[1]) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = 'black';
    ctx.strokeRect((x + offset[0]) * BLOCK_SIZE, (y + offset[1]) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  });
}

function checkCollision(block, offset = [0, 0]) {
  return block.coords.some(([x, y]) => {
    x += offset[0];
    y += offset[1];
    return x < 0 || x >= GRID_WIDTH || y >= GRID_HEIGHT || (y >= 0 && blocks.some(b => b.coords.some(([bx, by]) => bx === x && by === y)));
  });
}

function clearLines() {
  let lines = 0;
  for (let y = GRID_HEIGHT - 1; y >= 0; y--) {
    if (blocks.every(b => b.coords.some(([x, by]) => by === y))) {
      lines++;
      blocks = blocks.filter(b => !b.coords.some(([x, by]) => by === y));
      blocks.forEach(b => b.coords.forEach(([x, by]) => {
        if (by < y) b.coords = b.coords.map(([bx, bpy]) => [bx, bpy + 1]);
      }));
    }
  }
  score += lines * 100;
  linesCleared += lines;
}

function update() {
  switch (state) {
    case 'menu':
      if (keysPressed['Enter']) {
        state = 'playing';
        currentBlock = getRandomBlock();
        keysPressed['Enter'] = false;
      }
      break;
    case 'playing':
      if (keysPressed['ArrowLeft'] && !checkCollision(currentBlock, [-1, 0])) {
        currentBlock.coords = currentBlock.coords.map(([x, y]) => [x - 1, y]);
      }
      if (keysPressed['ArrowRight'] && !checkCollision(currentBlock, [1, 0])) {
        currentBlock.coords = currentBlock.coords.map(([x, y]) => [x + 1, y]);
      }
      if (keysPressed['ArrowDown'] && !checkCollision(currentBlock, [0, 1])) {
        currentBlock.coords = currentBlock.coords.map(([x, y]) => [x, y + 1]);
      }
      if (keysPressed['ArrowUp']) {
        const rotated = currentBlock.coords.map(([x, y]) => [-y, x]);
        const offset = [Math.floor(GRID_WIDTH / 2) - 1, 0];
        if (!checkCollision({ coords: rotated }, offset)) {
          currentBlock.coords = rotated.map(([x, y]) => [x + offset[0], y + offset[1]]);
        }
        keysPressed['ArrowUp'] = false;
      }
      if (checkCollision(currentBlock, [0, 1])) {
        blocks.push({ ...currentBlock });
        currentBlock = getRandomBlock();
        if (checkCollision(currentBlock)) {
          state = 'gameover';
        }
        clearLines();
      } else {
        currentBlock.coords = currentBlock.coords.map(([x, y]) => [x, y + 1]);
      }
      break;
    case 'paused':
      if (keysPressed['Enter']) {
        state = 'playing';
        keysPressed['Enter'] = false;
      }
      break;
    case 'gameover':
      if (keysPressed['Enter']) {
        state = 'menu';
        score = 0;
        linesCleared = 0;
        blocks = [];
        keysPressed['Enter'] = false;
      }
      break;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#333';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  switch (state) {
    case 'menu':
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('Press Enter to Start', canvas.width / 2, canvas.height / 2);
      break;
    case 'playing':
      blocks.forEach(block => drawBlock(block));
      drawBlock(currentBlock);
      ctx.fillStyle = 'white';
      ctx.font = '18px Arial';
      ctx.fillText(`Score: ${score}`, 10, 30);
      ctx.fillText(`Lines: ${linesCleared}`, 10, 50);
      break;
    case 'paused':
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('Game Paused', canvas.width / 2, canvas.height / 2);
      ctx.fillText('Press Enter to Resume', canvas.width / 2, canvas.height / 2 + 30);
      break;
    case 'gameover':
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 30);
      ctx.fillText('Press Enter to Restart', canvas.width / 2, canvas.height / 2 + 60);
      break;
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

const keysPressed = {};
document.addEventListener('keydown', e => {
  keysPressed[e.key] = true;
});
document.addEventListener('keyup', e => {
  keysPressed[e.key] = false;
});

gameLoop();
