const gravity = 980; // pixels per second squared
const ballRadius = 20;
const initialY = 50;
const comboMultiplier = 1.5;
let combo = 0;
let balls = [];
let lastTime = 0;
let fixedTimeStep = 1000 / 60; // 60 frames per second

function Ball(x, y) {
    this.x = x;
    this.y = y;
    this.vy = 0;
    this.combo = 0;
}

Ball.prototype.update = function(dt) {
    this.vy += gravity * dt;
    this.y += this.vy * dt;

    if (this.y + ballRadius >= canvas.height) {
        this.y = canvas.height - ballRadius;
        this.vy *= -comboMultiplier;
        this.combo = Math.max(0, this.combo - 1);
        combo = Math.max(combo, this.combo + 1);
    }
};

Ball.prototype.draw = function() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, ballRadius, 0, Math.PI * 2);
    ctx.fillStyle = `hsl(${this.combo * 30}, 100%, 50%)`;
    ctx.fill();
    ctx.closePath();
};

function spawnBall() {
    balls.push(new Ball(canvas.width / 2, initialY));
}

function update(dt) {
    for (let ball of balls) {
        ball.update(dt);
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let ball of balls) {
        ball.draw();
    }
    ctx.font = '24px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(`Combo: ${combo}`, 10, 30);
}

function gameLoop(time) {
