const CANVAS_SIZE = 400;

class Match3Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.scale = window.devicePixelRatio || 1;
    this.canvas.width = CANVAS_SIZE * this.scale;
    this.canvas.height = CANVAS_SIZE * this.scale;
    this.ctx.scale(this.scale, this.scale);

    this.boardSize = 8;
    this.tileSize = CANVAS_SIZE / this.boardSize;
    this.board = this.createBoard();
    this.state = 'menu';
    this.score = 0;
    this.pauseTime = 0;

    this.init();
  }

  init() {
    this.canvas.addEventListener('click', this.handleClick.bind(this));
    requestAnimationFrame(this.gameLoop.bind(this));
  }

  createBoard() {
    const board = [];
    for (let i = 0; i < this.boardSize; i++) {
      board[i] = [];
      for (let j = 0; j < this.boardSize; j++) {
        board[i][j] = Math.floor(Math.random() * 3); // 3 types of tiles
      }
    }
    return board;
  }

  gameLoop(timestamp) {
    switch (this.state) {
      case 'playing':
        this.update(timestamp);
        break;
      case 'paused':
        this.pauseTime = timestamp;
        break;
      case 'gameover':
        // Game over logic
        break;
    }
    this.render();
    requestAnimationFrame(this.gameLoop.bind(this));
  }

  update(timestamp) {
    // Placeholder for game update logic
  }

  render() {
    this.ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

    this.ctx.font = '24px Arial';
    this.ctx.fillStyle = 'black';

    switch (this.state) {
      case 'menu':
        this.ctx.fillText('Click to Start', CANVAS_SIZE / 2 - 60, CANVAS_SIZE / 2);
        break;
      case 'playing':
        for (let i = 0; i < this.boardSize; i++) {
          for (let j = 0; j < this.boardSize; j++) {
            this.drawTile(i, j, this.board[i][j]);
          }
        }
        this.ctx.fillText(`Score: ${this.score}`, 10, 20);
        break;
      case 'paused':
        this.ctx.fillText('Paused', CANVAS_SIZE / 2 - 30, CANVAS_SIZE / 2);
        break;
      case 'gameover':
        this.ctx.fillText('Game Over', CANVAS_SIZE / 2 - 50, CANVAS_SIZE / 2);
        break;
    }
  }

  drawTile(x, y, type) {
    const color = ['#FF0000', '#00FF00', '#0000FF'][type];
    this.ctx.fillStyle = color;
    this.ctx.fillRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);
  }

  handleClick(event) {
    const rect = this.canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) / this.tileSize);
    const y = Math.floor((event.clientY - rect.top) / this.tileSize);

    switch (this.state) {
      case 'menu':
        this.state = 'playing';
        break;
      case 'playing':
        // Placeholder for tile click logic
        break;
      case 'paused':
        this.state = 'playing';
        break;
      case 'gameover':
        // Restart game logic
        break;
    }
  }
}

document.addEventListener('DOMContentLoaded', () => {
