```js
// Constants
const CANVAS_ID = 'gameCanvas';
const FPS = 60;
const TILE_SIZE = 32;
const WAVE_INTERVAL = 5000; // milliseconds between waves

// Game state
let canvas, ctx;
let tiles = [];
let enemies = [];
let player = { x: 0, y: 0, health: 100 };
let currentWave = 1;
let lastWaveTime = 0;
let isGameOver = false;

// Initialize game
function init() {
    canvas = document.getElementById(CANVAS_ID);
    ctx = canvas.getContext('2d');
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    window.addEventListener('keydown', handleKeyDown);
    createInitialTiles();
    gameLoop();
}

// Handle window resize
function resizeCanvas() {
    const dpr = window.devicePixelRatio;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}

// Create initial tiles
function createInitialTiles() {
    for (let i = 0; i < 20; i++) {
        for (let j = 0; j < 15; j++) {
            tiles.push({ x: i * TILE_SIZE, y: j * TILE_SIZE });
        }
    }
}

// Handle keydown events
function handleKeyDown(e) {
    const speed = 5;
    switch (e.key) {
        case 'ArrowUp':
            player.y = Math.max(0, player.y - speed);
            break;
        case 'ArrowDown':
            player.y = Math.min(canvas.height - TILE_SIZE, player.y + speed);
            break;
        case 'ArrowLeft':
            player.x = Math.max(0, player.x - speed);
            break;
        case 'ArrowRight':
            player.x = Math.min(canvas.width - TILE_SIZE, player.x + speed);
            break;
    }
}

// Spawn enemies for a wave
function spawnWave() {
    for (let i = 0; i < currentWave; i++) {
        enemies.push({
            x: canvas.width - TILE_SIZE,
            y: Math.random() * (canvas.height - TILE_SIZE),
            health: 10
        });
    }
}

// Game loop
function gameLoop() {
    if (isGameOver) return;

    const now = Date.now();
    if (now - lastWaveTime > WAVE_INTERVAL) {
        lastWaveTime = now;
        currentWave++;
        spawnWave();
    }

    update();
    render();
    requestAnimationFrame(gameLoop);
}

// Update game state
function update() {
    enemies.forEach(enemy => {
        enemy.x -= 2; // Move enemies left
        if (enemy.x < 0) {
            isGameOver = true;
        }
    });

    // Collision detection (simplified)
    enemies.forEach((enemy, index) => {
        if (player.x < enemy.x + TILE_SIZE &&
            player.x + TILE_SIZE > enemy.x &&
            player.y < enemy.y + TILE_SIZE &&
            player.y + TILE_SIZE > enemy.y) {
            player.health -= 1;
            enemies.splice(index, 1);
        }
    });

    if (player.health <= 0) {
        isGameOver = true;
    }
}

// Render game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Render tiles
    tiles.forEach(tile => {
        ctx.fillStyle = '#ccc';
        ctx.fillRect(tile.x, tile.y, TILE_SIZE, TILE_SIZE);
    });

    // Render enemies
    enemies.forEach(enemy => {
        ctx.fillStyle = 'red';
        ctx.fillRect(enemy.x, enemy.y, TILE_SIZE, TILE_SIZE);
    });

    // Render player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, TILE_SIZE, TILE_SIZE);

    // Render UI
    ctx.fillStyle = 'black';
    ctx.fillText(`Wave: ${currentWave}`, 10, 20);
    ctx.fillText(`Health: ${player.health}`, 10, 40);
}

// Start the game
init();
