 * @return {number}
 */
function lengthOfLongestSubstring(s) {
  let max = 0;
  let start = 0;
  const map = {};

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    if (map[char]) {
      start = map[char] + 1;
    }

    map[char] = i;
    max = Math.max(1 + i - start, max);
  }

  return max;
}
