// Breakout game with enemy spawner that ramps difficulty over time
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

let paddle = { x: canvas.width / 2, y: canvas.height - 20, width: 100, height: 10, dx: 0 };
let ball = { x: canvas.width / 2, y: canvas.height / 2, size: 10, dx: 2, dy: -2 };
let bricks = [];
let enemies = [];
let rows = 5;
let cols = 10;
let brickWidth = canvas.width / cols;
let brickHeight = 20;
let brickPadding = 5;
let brickOffsetTop = 30;
let brickOffsetLeft = 30;
let score = 0;
let level = 1;
let spawnInterval = 3000;
let spawnTimeout;

function createBricks() {
    bricks = [];
    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            let brickX = (col * (brickWidth + brickPadding)) + brickOffsetLeft;
            let brickY = (row * (brickHeight + brickPadding)) + brickOffsetTop;
            bricks.push({ x: brickX, y: brickY, width: brickWidth, height: brickHeight, visible: true });
        }
    }
}

function spawnEnemy() {
    enemies.push({
        x: Math.random() * (canvas.width - 20),
        y: 0,
        width: 20,
        height: 20,
        dy: 2
    });
    spawnTimeout = setTimeout(spawnEnemy, spawnInterval - level * 200);
}

function drawPaddle() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
}

function drawBall() {
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.size, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
    ctx.closePath();
}

function drawBricks() {
    bricks.forEach(brick => {
        if (brick.visible) {
            ctx.fillStyle = 'green';
            ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
        }
    });
}

function drawEnemies() {
    enemies.forEach(enemy => {
        ctx.fillStyle = 'orange';
        ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    });
}

function drawScore() {
    ctx.font = '20px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 8, 20);
    ctx.fillText(`Level: ${level}`, 8, 40);
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Move paddle
    if (paddle.x + paddle.width > canvas.width || paddle.x < 0) {
        paddle.dx = 0;
    } else {
        paddle.x += paddle.dx;
    }

    // Move ball
    ball.x += ball.dx;
    ball.y += ball.dy;

    // Ball collision with walls
    if (ball.x + ball.size > canvas.width || ball.x - ball.size < 0) {
        ball.dx = -ball.dx;
    }
    if (ball.y - ball.size < 0) {
        ball.dy = -ball.dy;
    }
    if (ball.y + ball.size > canvas.height) {
        resetGame();
    }

    // Ball collision with paddle
    if (ball.y + ball.size > paddle.y && ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
        ball.dy = -ball.dy;
    }

    // Ball collision with bricks
    bricks.forEach((brick, index) => {
        if (brick.visible && ball.x + ball.size > brick.x && ball.x - ball.size < brick.x + brick.width && ball.y + ball.size > brick.y && ball.y - ball.size < brick.y + brick.height) {
            brick.visible = false;
            ball.dy = -ball.dy;
            score++;
            if (score % (rows * cols) === 0) {
                level++;
                spawnInterval -= 200;
                if (spawnInterval < 500) spawnInterval = 500;
                clearTimeout(spawnTimeout);
                spawnEnemy();
            }
        }
    });

    // Enemies movement
    enemies.forEach((enemy, index) => {
        enemy.y += enemy.dy;
        if (enemy.y + enemy.height > canvas.height) {
            enemies.splice(index, 1);
        }
        // Enemy collision with paddle
        if (enemy.y + enemy.height > paddle.y && enemy.x > paddle.x && enemy.x < paddle.x + paddle.width) {
            resetGame();
        }
    });

    // Draw
    drawPaddle();
    drawBall();
    drawBricks();
    drawEnemies();
    drawScore();

    requestAnimationFrame(update);
}

function resetGame() {
    paddle = { x: canvas.width / 2, y: canvas.height - 20, width: 100, height: 10, dx: 0 };
    ball = { x: canvas.width / 2, y: canvas.height / 2, size: 10, dx: 2, dy: -2 };
    score = 0;
    level = 1;
    spawnInterval = 3000;
    clearTimeout(spawnTimeout);
    enemies = [];
    createBricks();
}

function keyDownHandler(e) {
    if (e.key === "Right" || e.key === "ArrowRight") {
        paddle.dx = 5;
    } else if (e.key === "Left" || e.key === "ArrowLeft") {
        paddle.dx = -5;
    }
}

function keyUpHandler(e) {
    if (e.key === "Right" || e.key === "ArrowRight" || e.key === "Left" || e.key === "ArrowLeft") {
        paddle.dx = 0;
    }
}

document.addEventListener("keydown", keyDownHandler, false);
document.addEventListener("keyup", keyUpHandler, false);

createBricks();
spawnEnemy();
update();
