const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let width = window.innerWidth;
let height = window.innerHeight;
let scale = window.devicePixelRatio;

canvas.width = width * scale;
canvas.height = height * scale;
ctx.scale(scale, scale);

const gravity = 0.5;
const jumpSpeed = -10;
const player = {
  x: 50,
  y: 100,
  width: 30,
  height: 50,
  velocityY: 0,
  onGround: false
};

const platforms = [
  { x: 0, y: height - 50, width: width, height: 50 },
  { x: 200, y: height - 150, width: 200, height: 50 },
  { x: 400, y: height - 250, width: 100, height: 50 }
];

let combo = 0;
let comboMultiplier = 1;

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawPlatforms() {
  ctx.fillStyle = 'green';
  platforms.forEach(platform => {
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  });
}

function checkCollision(player, platform) {
  const playerBottom = player.y + player.height;
  const platformTop = platform.y;
  if (playerBottom <= platformTop && playerBottom >= platformTop - player.velocityY && player.x < platform.x + platform.width && player.x + player.width > platform.x) {
    player.y = platform.y - player.height;
    player.velocityY = 0;
    player.onGround = true;
  }
}

function updatePlayer() {
  player.velocityY += gravity;
  player.y += player.velocityY;

  if (player.y + player.height > height) {
    player.y = height - player.height;
    player.velocityY = 0;
    player.onGround = true;
  }

  platforms.forEach(platform => checkCollision(player, platform));

  if (player.onGround) {
    combo = 0;
    comboMultiplier = 1;
  }
}

function drawCombo() {
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Combo: ${combo}x${comboMultiplier}`, 10, 30);
}

function updateCombo() {
  if (player.onGround) {
    combo++;
    comboMultiplier = Math.min(combo, 10);
  }
}

function update() {
  ctx.clearRect(0, 0, width, height);
  updatePlayer();
  updateCombo();
  drawPlayer();
  drawPlatforms();
  drawCombo();
  requestAnimationFrame(update);
}

update();

