const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    speed: 5,
    width: 20,
    height: 20,
    color: 'blue'
};

const powerUps = [];
const powerUpTypes = ['speedBoost', 'slowDown', 'shrink', 'expand'];
const powerUpColors = { speedBoost: 'green', slowDown: 'red', shrink: 'purple', expand: 'orange' };

function createPowerUp() {
    const type = powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)];
    powerUps.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        type,
        color: powerUpColors[type],
        radius: 10
    });
}

function update() {
    if (Math.random() < 0.02) createPowerUp();

    powerUps.forEach((powerUp, index) => {
        ctx.beginPath();
        ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
        ctx.fillStyle = powerUp.color;
        ctx.fill();

        if (player.x < powerUp.x + powerUp.radius &&
            player.x + player.width > powerUp.x &&
            player.y < powerUp.y + powerUp.radius &&
            player.y + player.height > powerUp.y) {
            applyPowerUp(powerUp.type);
            powerUps.splice(index, 1);
        }
    });

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    requestAnimationFrame(update);
}

function applyPowerUp(type) {
    switch (type) {
        case 'speedBoost':
            player.speed *= 1.5;
            setTimeout(() => player.speed /= 1.5, 5000);
            break;
        case 'slowDown':
            player.speed /= 1.5;
            setTimeout(() => player.speed *= 1.5, 5000);
            break;
        case 'shrink':
            player.width /= 1.5;
            player.height /= 1.5;
            setTimeout(() => {
                player.width *= 1.5;
                player.height *= 1.5;
            }, 5000);
            break;
        case 'expand':
            player.width *= 1.5;
            player.height *= 1.5;
            setTimeout(() => {
                player.width /= 1.5;
                player.height /= 1.5;
            }, 5000);
            break;
    }
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowLeft':
            player.x -= player.speed;
            break;
        case 'ArrowRight':
            player.x += player.speed;
            break;
        case 'ArrowUp':
            player.y -= player.speed;
            break;
        case 'ArrowDown':
            player.y += player.speed;
            break;
    }
});

