// 2048-style game with wave progression
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const TILE_SIZE = 100;
const GRID_SIZE = 4;
const TARGET_SCORE = 2048;

let score = 0;
let currentLevel = 1;
let grid = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));
let nextTileValue = 2;
let lastTime = 0;
const fixedTimeStep = 1000 / 30;

function getRandomInt(max) {
    return Math.floor(Math.random() * max);
}

function addRandomTile() {
    const emptyCells = [];
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (grid[y][x] === 0) {
                emptyCells.push({ x, y });
            }
        }
    }
    if (emptyCells.length > 0) {
        const { x, y } = emptyCells[getRandomInt(emptyCells.length)];
        grid[y][x] = nextTileValue;
        nextTileValue = nextTileValue === 2 ? 4 : 2;
    }
}

function mergeTiles(row) {
    let newRow = row.filter(value => value !== 0);
    for (let i = 0; i < newRow.length - 1; i++) {
        if (newRow[i] === newRow[i + 1]) {
            newRow[i] *= 2;
            score += newRow[i];
            newRow[i + 1] = 0;
        }
    }
    newRow = newRow.filter(value => value !== 0);
    while (newRow.length < GRID_SIZE) {
        newRow.push(0);
    }
    return newRow;
}

function transposeGrid(grid) {
    return grid[0].map((_, colIndex) => grid.map(row => row[colIndex]));
}

function moveLeft(grid) {
    return grid.map(row => mergeTiles(row));
}

function moveRight(grid) {
    return grid.map(row => mergeTiles(row.slice().reverse())).map(row => row.reverse());
}

function moveUp(grid) {
    return transposeGrid(moveLeft(transposeGrid(grid)));
}

function moveDown(grid) {
    return transposeGrid(moveRight(transposeGrid(grid)));
}

function handleInput(e) {
    const oldGrid = JSON.parse(JSON.stringify(grid));
    switch (e.key) {
        case 'ArrowLeft':
            grid = moveLeft(grid);
            break;
        case 'ArrowRight':
            grid = moveRight(grid);
            break;
        case 'ArrowUp':
            grid = moveUp(grid);
            break;
        case 'ArrowDown':
            grid = moveDown(grid);
            break;
    }
    if (JSON.stringify(grid) !== JSON.stringify(oldGrid)) {
        addRandomTile();
        if (grid.flat().every(value => value !== 0)) {
            // Game over logic
        }
    }
}

document.addEventListener('keydown', handleInput);

function drawTile(x, y, value) {
    ctx.fillStyle = '#ccc';
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.fillStyle = '#000';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(value.toString(), x * TILE_SIZE + TILE_SIZE / 2, y * TILE_SIZE + TILE_SIZE / 2);
}

function drawGrid() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (grid[y][x] !== 0) {
                drawTile(x, y, grid[y][x]);
            }
        }
    }
    ctx.fillStyle = '#000';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Level: ${currentLevel}`, 10, 60);
}

function update(deltaTime) {
    // Update logic if needed
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime > fixedTimeStep) {
        update(deltaTime);
        drawGrid();
        lastTime = timestamp - (deltaTime % fixedTimeStep);
    }
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);

// Initial setup
addRandomTile();
addRandomTile();
drawGrid();
