// Fishing Mini-Game with Keyboard and Pointer Controls

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let w = window.innerWidth;
let h = window.innerHeight;
let dpr = window.devicePixelRatio;
canvas.width = w * dpr;
canvas.height = h * dpr;
canvas.style.width = `${w}px`;
canvas.style.height = `${h}px`;
ctx.scale(dpr, dpr);

const fish = {
    x: w / 2,
    y: h / 2,
    size: 50,
    speed: 2,
    direction: { x: 0, y: 0 }
};

const line = {
    length: 100,
    angle: Math.PI / 4,
    color: 'blue'
};

function drawFish() {
    ctx.beginPath();
    ctx.arc(fish.x, fish.y, fish.size, 0, Math.PI * 2);
    ctx.fillStyle = 'orange';
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'black';
    ctx.stroke();
}

function drawLine() {
    ctx.beginPath();
    ctx.moveTo(fish.x, fish.y);
    ctx.lineTo(fish.x + line.length * Math.cos(line.angle), fish.y + line.length * Math.sin(line.angle));
    ctx.strokeStyle = line.color;
    ctx.lineWidth = 3;
    ctx.stroke();
}

function update() {
    fish.x += fish.direction.x * fish.speed;
    fish.y += fish.direction.y * fish.speed;

    // Keep fish within canvas bounds
    if (fish.x - fish.size < 0) fish.x = fish.size;
    if (fish.x + fish.size > w) fish.x = w - fish.size;
    if (fish.y - fish.size < 0) fish.y = fish.size;
    if (fish.y + fish.size > h) fish.y = h - fish.size;

    ctx.clearRect(0, 0, w, h);
    drawFish();
    drawLine();
}

function handleKeyDown(e) {
    switch (e.key) {
        case 'ArrowLeft':
            fish.direction.x = -1;
            break;
        case 'ArrowRight':
            fish.direction.x = 1;
            break;
        case 'ArrowUp':
            fish.direction.y = -1;
            break;
        case 'ArrowDown':
            fish.direction.y = 1;
            break;
    }
}

function handleKeyUp(e) {
    switch (e.key) {
        case 'ArrowLeft':
        case 'ArrowRight':
            fish.direction.x = 0;
            break;
        case 'ArrowUp':
        case 'ArrowDown':
            fish.direction.y = 0;
            break;
    }
}

function handlePointerMove(e) {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    line.angle = Math.atan2(y - fish.y, x - fish.x);
}

canvas.addEventListener('pointermove', handlePointerMove);
document.addEventListener('keydown', handleKeyDown);
document.addEventListener('keyup', handleKeyUp);

function gameLoop() {
    update();
    requestAnimationFrame(gameLoop);
}

gameLoop();
