const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const player = {
  x: 50,
  y: 50,
  width: 20,
  height: 20,
  color: 'blue'
};

const enemy = {
  x: canvas.width - 50,
  y: canvas.height - 50,
  width: 20,
  height: 20,
  color: 'red'
};

const maze = [];
const mazeWidth = 20;
const mazeHeight = 15;
const cellSize = 30;

function generateMaze() {
  for (let i = 0; i < mazeHeight; i++) {
    maze[i] = [];
    for (let j = 0; j < mazeWidth; j++) {
      maze[i][j] = Math.random() > 0.7 ? 1 : 0;
    }
  }
}

function drawMaze() {
  ctx.fillStyle = 'black';
  for (let i = 0; i < mazeHeight; i++) {
    for (let j = 0; j < mazeWidth; j++) {
      if (maze[i][j]) {
        ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
      }
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawEnemy() {
  ctx.fillStyle = enemy.color;
  ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
}

function checkCollision(a, b) {
  return !(a.x + a.width < b.x || a.x > b.x + b.width || a.y + a.height < b.y || a.y > b.y + b.height);
}

let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;

function updateScore() {
  score++;
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function update() {
  let dx = 0, dy = 0;

  if (keys['ArrowUp'] && player.y > 0 && maze[Math.floor((player.y - player.height) / cellSize)][Math.floor(player.x / cellSize)] === 0) {
    dy = -1;
  }
  if (keys['ArrowDown'] && player.y + player.height < canvas.height && maze[Math.floor((player.y + player.height) / cellSize)][Math.floor(player.x / cellSize)] === 0) {
    dy = 1;
  }
  if (keys['ArrowLeft'] && player.x > 0 && maze[Math.floor(player.y / cellSize)][Math.floor((player.x - player.width) / cellSize)] === 0) {
    dx = -1;
  }
  if (keys['ArrowRight'] && player.x + player.width < canvas.width && maze[Math.floor(player.y / cellSize)][Math.floor((player.x + player.width) / cellSize)] === 0) {
    dx = 1;
  }

  player.x += dx * 5;
  player.y += dy * 5;

  if (checkCollision(player, enemy)) {
    alert(`Game Over! Your score: ${score}`);
    score = 0;
    player.x = 50;
    player.y = 50;
  }

  if (Math.random() < 0.05) {
    enemy.x = Math.random() * (canvas.width - enemy.width);
    enemy.y = Math.random() * (canvas.height - enemy.height);
    updateScore();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawMaze();
  drawPlayer();
  drawEnemy();
  drawScore();
  requestAnimationFrame(render);
}

const keys = {};
window.addEventListener('keydown', function(e) {
  keys[e.key] = true;
});
window.addEventListener('keyup', function(e) {
  keys[e.key] = false;
});

generateMaze();
render();
