const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const cards = [];
const maxHealth = 5;
let health = maxHealth;
let flippedCards = [];
let respawnCooldown = 0;

const cardImages = [
  'card1.png', 'card2.png', 'card3.png', 'card4.png', 'card5.png'
];

function loadImages(images) {
  return images.map(src => {
    const img = new Image();
    img.src = src;
    return img;
  });
}

const images = loadImages(cardImages);
images.forEach(img => img.onload = () => render());

function createBoard() {
  const numCards = cardImages.length * 2;
  const cardIndices = [];
  for (let i = 0; i < numCards; i++) {
    cardIndices.push(Math.floor(i / 2));
  }
  cardIndices.sort(() => Math.random() - 0.5);

  for (let i = 0; i < numCards; i++) {
    const index = cardIndices[i];
    const x = (i % 8) * (cardWidth + 20) + 50;
    const y = Math.floor(i / 8) * (cardHeight + 20) + 50;
    cards.push({ x, y, index, flipped: false });
  }
}

createBoard();

function flipCard(card) {
  if (flippedCards.length < 2 && !card.flipped) {
    card.flipped = true;
    flippedCards.push(card);
    if (flippedCards.length === 2) {
      setTimeout(checkForMatch, 500);
    }
  }
}

function checkForMatch() {
  const [card1, card2] = flippedCards;
  if (card1.index !== card2.index) {
    card1.flipped = card2.flipped = false;
    health--;
    if (health <= 0) {
      respawnCooldown = 3000;
    }
  } else {
    // Cards match, do nothing (they stay flipped)
  }
  flippedCards = [];
}

function respawn() {
  if (respawnCooldown > 0) {
    respawnCooldown -= 16; // 60 FPS
  } else {
    health = maxHealth;
    flippedCards = [];
    cards.forEach(card => card.flipped = false);
    createBoard();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  cards.forEach(card => {
    if (card.flipped) {
      ctx.drawImage(images[card.index], card.x, card.y, cardWidth, cardHeight);
    } else {
      ctx.fillStyle = '#ccc';
      ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
    }
  });

  ctx.fillStyle = '#000';
  ctx.font = '20px Arial';
  ctx.fillText(`Health: ${health}`, 20, 30);

  if (respawnCooldown > 0) {
    ctx.fillText(`Respawning in: ${Math.ceil(respawnCooldown / 1000)}s`, 20, 60);
  }

  requestAnimationFrame(render);
}

canvas.addEventListener('click', (event) => {
  const { offsetX, offsetY } = event;
  const card = cards.find(card => 
    offsetX > card.x && offsetX < card.x + cardWidth &&
    offsetY > card.y && offsetY < card.y + cardHeight
  );
  if (card) {
    flipCard(card);
  }
});

render();
