const ctx = canvas.getContext('2d');

const states = {
  menu: { update: menuUpdate, render: menuRender },
  playing: { update: playingUpdate, render: playingRender },
  paused: { update: pausedUpdate, render: pausedRender },
  gameover: { update: gameoverUpdate, render: gameoverRender }
};

let currentState = states.menu;

let player = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, speed: 5, dx: 0, dy: 0 };
let enemies = [];
let score = 0;
let lives = 3;

function menuUpdate() {
  if (keys['Enter']) {
    currentState = states.playing;
  }
}

function menuRender() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '36px Arial';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('Menu', canvas.width / 2, canvas.height / 2);
  ctx.fillText('Press Enter to Play', canvas.width / 2, canvas.height / 2 + 40);
}

function playingUpdate() {
  player.dx = 0;
  player.dy = 0;
  if (keys['ArrowUp']) player.dy = -player.speed;
  if (keys['ArrowDown']) player.dy = player.speed;
  if (keys['ArrowLeft']) player.dx = -player.speed;
  if (keys['ArrowRight']) player.dx = player.speed;

  player.x += player.dx;
  player.y += player.dy;

  if (player.x < player.radius) player.x = player.radius;
  if (player.x > canvas.width - player.radius) player.x = canvas.width - player.radius;
  if (player.y < player.radius) player.y = player.radius;
  if (player.y > canvas.height - player.radius) player.y = canvas.height - player.radius;

  if (Math.random() < 0.02) {
    enemies.push({ x: Math.random() * canvas.width, y: Math.random() * canvas.height, radius: 8, speed: 2 });
  }

  enemies.forEach((enemy, index) => {
    enemy.x += (player.x - enemy.x) * enemy.speed / 100;
    enemy.y += (player.y - enemy.y) * enemy.speed / 100;

    if (distance(player, enemy) < player.radius + enemy.radius) {
      lives--;
      enemies.splice(index, 1);
    }
  });

  enemies = enemies.filter(enemy => distance(player, enemy) > player.radius + enemy.radius);

  if (lives <= 0) {
    currentState = states.gameover;
  }
}

function playingRender() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  enemies.forEach(enemy => {
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'white';
  ctx.font = '24px Arial';
  ctx.fillText('Score: ' + score, 10, 30);
  ctx.fillText('Lives: ' + lives, 10, 60);
}

function pausedUpdate() {
  if (keys['Enter']) {
    currentState = states.playing;
  }
}

function pausedRender() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '36px Arial';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
  ctx.fillText('Press Enter to Resume', canvas.width / 2, canvas.height / 2 + 40);
}

function gameoverUpdate() {
  if (keys['Enter']) {
    resetGame();
    currentState = states.menu;
  }
}

function gameoverRender() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '36px Arial';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 40);
  ctx.fillText('Press Enter to Restart', canvas.width / 2, canvas.height / 2 + 80);
}

function resetGame() {
  player = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, speed: 5, dx: 0, dy: 0 };
  enemies = [];
  score = 0;
  lives = 3;
}

function distance(a, b) {
  return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

const keys = {};
document.addEventListener('keydown', (e) => { keys[e.key] = true; });
document.addEventListener('keyup', (e) => { keys[e.key] = false; });

function gameLoop() {
  currentState.update();
  currentState.render();
  requestAnimationFrame(gameLoop);
}

gameLoop();
