const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 600;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];
const powerUpTypes = ['BOMB', 'SWAP', 'MATCH'];

let board = Array.from({ length: boardSize }, () => 
    Array.from({ length: boardSize }, () => 
        Math.floor(Math.random() * colors.length)
    )
);

let powerUps = Array.from({ length: boardSize }, () => 
    Array.from({ length: boardSize }, () => 
        Math.random() < 0.1 ? powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)] : null
    )
);

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = colors[board[y][x]];
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            if (powerUps[y][x]) {
                ctx.font = '16px Arial';
                ctx.fillStyle = 'black';
                ctx.textAlign = 'center';
                ctx.fillText(powerUps[y][x], x * cellSize + cellSize / 2, y * cellSize + cellSize / 2);
            }
        }
    }
}

function match3() {
    let matches = [];

    // Check horizontal matches
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize - 2; x++) {
            if (board[y][x] !== null && board[y][x] === board[y][x + 1] && board[y][x] === board[y][x + 2]) {
                matches.push([[y, x], [y, x + 1], [y, x + 2]]);
                let i = x + 3;
                while (i < boardSize && board[y][i] === board[y][x]) {
                    matches[matches.length - 1].push([y, i]);
                    i++;
                }
            }
        }
    }

    // Check vertical matches
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < boardSize - 2; y++) {
            if (board[y][x] !== null && board[y][x] === board[y + 1][x] && board[y][x] === board[y + 2][x]) {
                matches.push([[y, x], [y + 1, x], [y + 2, x]]);
                let i = y + 3;
                while (i < boardSize && board[i][x] === board[y][x]) {
                    matches[matches.length - 1].push([i, x]);
                    i++;
                }
            }
        }
    }

    // Remove matched tiles
    matches.forEach(match => {
        match.forEach(([y, x]) => {
            board[y][x] = null;
            powerUps[y][x] = null;
        });
    });

    // Drop tiles down
    for (let x = 0; x < boardSize; x++) {
        let emptyCells = [];
        for (let y = boardSize - 1; y >= 0; y--) {
            if (board[y][x] === null) {
                emptyCells.push(y);
            } else if (emptyCells.length > 0) {
                let emptyY = emptyCells.pop();
                board[emptyY][x] = board[y][x];
                board[y][x] = null;
                powerUps[emptyY][x] = powerUps[y][x];
                powerUps[y][x] = null;
            }
        }
    }

    // Fill top with new tiles
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < boardSize; y++) {
            if (board[y][x] === null) {
                board[y][x] = Math.floor(Math.random() * colors.length);
                powerUps[y][x] = Math.random() < 0.1 ? powerUpTypes[Math.floor(Math.random() * powerUpTypes.length)] : null;
            }
        }
    }

    return matches.length > 0;
}

function animate() {
    drawBoard();
    if (match3()) {
        requestAnimationFrame(animate);
    }
}

requestAnimationFrame(animate);
