const particleSystem = {
  particles: [],
  emit(x, y, color, count = 10) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 5 + 1;
      this.particles.push({
        x, y, angle, speed, color,
        life: Math.random() * 1 + 0.5
      });
    }
  },
  update() {
    this.particles.forEach(particle => {
      particle.x += Math.cos(particle.angle) * particle.speed;
      particle.y += Math.sin(particle.angle) * particle.speed;
      particle.life -= 0.02;
    });
    this.particles = this.particles.filter(particle => particle.life > 0);
  },
  draw() {
    this.particles.forEach(particle => {
      ctx.beginPath();
      ctx.fillStyle = particle.color;
      ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
      ctx.fill();
    });
  }
};

const maze = {
  width: 20,
  height: 15,
  cellSize: 40,
  walls: [],
  generate() {
    const grid = Array.from({ length: this.height }, () =>
      Array(this.width).fill(0)
    );
    const stack = [];
    const directions = [
      { x: 0, y: -1 },
      { x: 1, y: 0 },
      { x: 0, y: 1 },
      { x: -1, y: 0 }
    ];

    function carve(x, y) {
      grid[y][x] = 1;
      stack.push({ x, y });

      while (stack.length > 0) {
        const { x, y } = stack[stack.length - 1];
        let neighbors = directions.filter(dir => {
          const nx = x + dir.x * 2;
          const ny = y + dir.y * 2;
          return nx >= 0 && nx < this.width && ny >= 0 && ny < this.height && grid[ny][nx] === 0;
        }, this);

        if (neighbors.length > 0) {
          const { x: dirX, y: dirY } = neighbors[Math.floor(Math.random() * neighbors.length)];
          grid[y + dirY][x + dirX] = 1;
          grid[y + dirY / 2][x + dirX / 2] = 1;
          stack.push({ x: x + dirX, y: y + dirY });
        } else {
          stack.pop();
        }
      }
    }

    carve.call(this, Math.floor(this.width / 2), Math.floor(this.height / 2));

    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (grid[y][x] === 0) {
          this.walls.push({ x, y });
        }
      }
    }
  },
  draw() {
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    this.walls.forEach(wall => {
      ctx.strokeRect(wall.x * this.cellSize, wall.y * this.cellSize, this.cellSize, this.cellSize);
    });
  }
};

const player = {
  x: 40,
  y: 40,
  size: 20,
  speed: 5,
  dx: 0,
  dy: 0,
  update() {
    this.x += this.dx;
    this.y += this.dy;

    if (this.x < 0) this.x = 0;
    if (this.x + this.size > canvas.width) this.x = canvas.width - this.size;
    if (this.y < 0) this.y = 0;
    if (this.y + this.size > canvas.height) this.y = canvas.height - this.size;

    maze.walls.forEach(wall => {
      if (this.x < wall.x * maze.cellSize + maze.cellSize && this.x + this.size > wall.x * maze.cellSize &&
          this.y < wall.y * maze.cellSize + maze.cellSize && this.y + this.size > wall.y * maze.cellSize) {
        if (this.dx > 0) this.x = wall.x * maze.cellSize - this.size;
        if (this.dx < 0) this.x = wall.x * maze.cellSize + maze.cellSize;
        if (this.dy > 0) this.y = wall.y * maze.cellSize - this.size;
        if (this.dy < 0) this.y = wall.y * maze.cellSize + maze.cellSize;
      }
    });
  },
  draw() {
    ctx.fillStyle = '#00F';
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
};

const chase = {
  x: maze.width * maze.cellSize - maze.cellSize,
  y: maze.height * maze.cellSize - maze.cellSize,
  size: 20,
  speed: 3,
  update() {
    const dx = player.x - this.x;
    const dy = player.y - this.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance > 0) {
      this.x += (dx / distance) * this.speed;
      this.y += (dy / distance) * this.speed;
    }

    if (distance < player.size) {
      particleSystem.emit(player.x, player.y, '#F00', 50);
    }
  },
  draw() {
    ctx.fillStyle = '#F00';
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
};

maze.generate();

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player.update();
  chase.update();

  particleSystem.update();
  particleSystem.draw();

  maze.draw();
  player.draw();
  chase.draw();

  requestAnimationFrame(gameLoop);
}

