    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

function updateBird() {
    bird.vy += bird.gravity;
    bird.y += bird.vy;
    if (bird.y > canvas.height || bird.y < 0) {
        resetGame();
    }
}

function updatePipes() {
    pipes.forEach(pipe => {
        pipe.x -= 2;
        if (pipe.x + pipeWidth < 0) {
            pipes.shift();
            score++;
            powerUpTimer = 0;
            powerUpVisible = true;
        }
    });
    if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - 200) {
        const gapY = getRandomInt(pipeGap, canvas.height - pipeGap);
        pipes.push({ x: canvas.width, top: gapY - pipeGap / 2, bottom: gapY + pipeGap / 2 });
    }
}

function updatePowerUps() {
    if (powerUpVisible) {
        powerUpTimer++;
        if (powerUpTimer > 100) {
            powerUpVisible = false;
        }
    }
    powerUps.forEach((powerUp, index) => {
        powerUp.x -= powerUpSpeed;
        if (powerUp.x + powerUpRadius < 0) {
            powerUps.splice(index, 1);
        }
    });
    if (powerUpVisible && Math.random() < 0.02) {
        powerUps.push({ x: canvas.width, y: getRandomInt(powerUpRadius, canvas.height - powerUpRadius), collected: false });
    }
}

function checkCollisions() {
    pipes.forEach(pipe => {
        if (bird.x < pipe.x + pipeWidth &&
            bird.x + bird.width > pipe.x &&
            bird.y < pipe.top &&
            bird.y + bird.height > pipe.bottom) {
            resetGame();
        }
    });
    powerUps.forEach((powerUp, index) => {
        if (!powerUp.collected && bird.x < powerUp.x + powerUpRadius &&
            bird.x + bird.width > powerUp.x &&
            bird.y < powerUp.y + powerUpRadius &&
            bird.y + bird.height > powerUp.y) {
            powerUp.collected = true;
            score += 10;
        }
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawRect(bird.x, bird.y, bird.width, bird.height, 'blue');
    pipes.forEach(pipe => {
        drawRect(pipe.x, 0, pipeWidth, pipe.top, 'green');
        drawRect(pipe.x, pipe.bottom, pipeWidth, canvas.height - pipe.bottom, 'green');
    });
    powerUps.forEach(powerUp => {
        drawCircle(powerUp.x, powerUp.y, powerUpRadius, 'red');
    });
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 10, 20);
}

function resetGame() {
    bird.y = 100;
    bird.vy = 0;
    pipes.length = 0;
    powerUps.length = 0;
    score = 0;
    powerUpVisible = false;
    powerUpTimer = 0;
}

function gameLoop() {
    updateBird();
    updatePipes();
    updatePowerUps();
    checkCollisions();
    draw();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
        bird.vy = flapStrength;
    }
});

gameLoop();
