let pixelRatio = window.devicePixelRatio || 1;
function resizeCanvas() {
  const width = window.innerWidth;
  const height = window.innerHeight;
  canvas.width = Math.floor(width * pixelRatio);
  canvas.height = Math.floor(height * pixelRatio);
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const enemies = [];
const towers = [];
const bullets = [];
const enemySpeed = 2;
const towerRange = 100;
const bulletSpeed = 5;

class Entity {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

class Enemy extends Entity {
  update() {
    this.x -= enemySpeed;
    if (this.x < -10) {
      enemies.shift();
    }
  }
  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x * pixelRatio, this.y * pixelRatio, 10 * pixelRatio, 10 * pixelRatio);
  }
}

class Tower extends Entity {
  constructor(x, y) {
    super(x, y);
    this.target = null;
  }
  update() {
    if (!this.target || this.target.x > this.x + towerRange) {
      this.target = enemies.find(e => e.x < this.x + towerRange);
    }
    if (this.target) {
      this.shoot();
    }
  }
  shoot() {
    const dx = this.target.x - this.x;
    const dy = this.target.y - this.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    const bullet = new Bullet(this.x + 5, this.y + 5, this.target.x + 5, this.target.y + 5);
    bullets.push(bullet);
  }
  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x * pixelRatio, this.y * pixelRatio, 10 * pixelRatio, 10 * pixelRatio);
  }
}

class Bullet extends Entity {
  constructor(x, y, targetX, targetY) {
    super(x, y);
    const dx = targetX - x;
    const dy = targetY - y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    this.vx = (dx / dist) * bulletSpeed;
    this.vy = (dy / dist) * bulletSpeed;
  }
  update() {
    this.x += this.vx;
    this.y += this.vy;
    const hitEnemy = enemies.find(e => Math.hypot(e.x - this.x, e.y - this.y) < 5);
    if (hitEnemy) {
      enemies.splice(enemies.indexOf(hitEnemy), 1);
      bullets.splice(bullets.indexOf(this), 1);
    }
  }
  draw() {
    ctx.fillStyle = 'black';
    ctx.fillRect(this.x * pixelRatio, this.y * pixelRatio, 5 * pixelRatio, 5 * pixelRatio);
  }
}

function spawnEnemy() {
  const y = Math.random() * (canvas.height / pixelRatio - 10);
  enemies.push(new Enemy(canvas.width / pixelRatio, y));
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  enemies.forEach(e => e.update());
  enemies.forEach(e => e.draw());
  towers.forEach(t => t.update());
  towers.forEach(t => t.draw());
  bullets.forEach(b => b.update());
  bullets.forEach(b => b.draw());
  spawnEnemy();
  requestAnimationFrame(update);
}

canvas.addEventListener('click', e => {
  const x = e.offsetX / pixelRatio;
  const y = e.offsetY / pixelRatio;
  towers.push(new Tower(x, y));
});

update();
