// Arena Shooter Game

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  width: 20,
  height: 20,
  speed: 5
};

const bullets = [];
const enemies = [];
const enemySpawns = [
  { x: 0, y: 0 },
  { x: canvas.width, y: 0 },
  { x: 0, y: canvas.height },
  { x: canvas.width, y: canvas.height }
];

let wave = 1;
let score = 0;
let lastTime = 0;

function spawnEnemies() {
  const numEnemies = wave * 5;
  for (let i = 0; i < numEnemies; i++) {
    const spawnPoint = enemySpawns[Math.floor(Math.random() * enemySpawns.length)];
    enemies.push({
      x: spawnPoint.x,
      y: spawnPoint.y,
      width: 15,
      height: 15,
      speed: 1 + wave * 0.1
    });
  }
}

function update(deltaTime) {
  // Player movement
  if (keys.right) player.x += player.speed * deltaTime;
  if (keys.left) player.x -= player.speed * deltaTime;
  if (keys.up) player.y -= player.speed * deltaTime;
  if (keys.down) player.y += player.speed * deltaTime;

  // Bullets update
  for (let i = bullets.length - 1; i >= 0; i--) {
    bullets[i].y -= 5;
    if (bullets[i].y < 0) {
      bullets.splice(i, 1);
    }
  }

  // Enemies update
  for (let i = enemies.length - 1; i >= 0; i--) {
    const enemy = enemies[i];
    const dx = enemy.x - player.x;
    const dy = enemy.y - player.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const directionX = dx / distance;
    const directionY = dy / distance;
    enemy.x -= directionX * enemy.speed * deltaTime;
    enemy.y -= directionY * enemy.speed * deltaTime;

    // Collision with player
    if (distance < player.width / 2 + enemy.width / 2) {
      alert(`Game Over! Your score: ${score}`);
      resetGame();
    }
  }

  // Collision detection
  for (let i = bullets.length - 1; i >= 0; i--) {
    for (let j = enemies.length - 1; j >= 0; j--) {
      const bullet = bullets[i];
      const enemy = enemies[j];
      if (bullet.x < enemy.x + enemy.width &&
          bullet.x + bullet.width > enemy.x &&
          bullet.y < enemy.y + enemy.height &&
          bullet.y + bullet.height > enemy.y) {
        enemies.splice(j, 1);
        bullets.splice(i, 1);
        score++;
        break;
      }
    }
  }

  // Wave progression
  if (enemies.length === 0) {
    wave++;
    spawnEnemies();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw bullets
  ctx.fillStyle = 'white';
  bullets.forEach(bullet => {
    ctx.fillRect(bullet.x, bullet.y, 3, 10);
  });

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
  });

  // Draw score and wave
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Wave: ${wave}`, 10, 60);
}

function resetGame() {
  player.x = canvas.width / 2;
  player.y = canvas.height - 50;
  bullets.length = 0;
  enemies.length = 0;
  wave = 1;
  score = 0;
  spawnEnemies();
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  update(deltaTime);
  draw();

  requestAnimationFrame(gameLoop);
}

const keys = {
  right: false,
  left: false,
  up: false,
  down: false,
  space: false
};

document.addEventListener('keydown', (e) => {
  if (e.code === 'ArrowRight') keys.right = true;
  if (e.code === 'ArrowLeft') keys.left = true;
  if (e.code === 'ArrowUp') keys.up = true;
  if (e.code === 'ArrowDown') keys.down = true;
  if (e.code === 'Space' && !keys.space) {
    keys.space = true;
    bullets.push({
      x: player.x + player.width / 2 - 1.5,
      y: player.y,
      width: 3,
      height: 10
    });
  }
});

document.addEventListener('keyup', (e) => {
  if (e.code === 'ArrowRight') keys.right = false;
  if (e.code === 'ArrowLeft') keys.left = false;
  if (e.code === 'ArrowUp') keys.up = false;
  if (e.code === 'ArrowDown') keys.down = false;
  if (e.code === 'Space') keys.space = false;
});

spawnEnemies();
requestAnimationFrame(gameLoop);
