function rightSideViewDfs(root) {
  const ans = [];

  const dfs = (node, level = 0) => {
    if (!node) return;
    if (level === ans.length) ans.push(node.value);
    dfs(node.right, level + 1); // right side first!
    dfs(node.left, level + 1);
  };

  dfs(root);
  return ans;
}
