  { enemies: 15, spawnInterval: 1000, enemySpeed: 1.5 }
];
let currentWave = 0;
let waveStartTime = performance.now();

class Entity {
  constructor(x, y, speed) {
    this.x = x;
    this.y = y;
    this.speed = speed;
  }

  update(delta) {
    this.x += this.speed * delta;
  }

  draw(ctx) {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

class Player extends Entity {
  constructor(x, y, speed) {
    super(x, y, speed);
  }

  update(delta) {
    // Player movement logic can be added here
  }
}

const player = new Player(100, canvas.height / 2, 0);
entities.push(player);

function spawnEnemy() {
  if (currentWave < waves.length) {
    const wave = waves[currentWave];
    for (let i = 0; i < wave.enemies; i++) {
      const enemy = new Entity(canvas.width, Math.random() * (canvas.height - 20), wave.enemySpeed);
      entities.push(enemy);
    }
    currentWave++;
    waveStartTime = performance.now();
  }
}

function update(delta) {
  accumulator += delta;
  while (accumulator >= TICK_LENGTH) {
    for (const entity of entities) {
      entity.update(TICK_LENGTH / 1000);
    }
    if (performance.now() - waveStartTime >= waves[currentWave - 1].spawnInterval) {
      spawnEnemy();
    }
    accumulator -= TICK_LENGTH;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const entity of entities) {
    entity.draw(ctx);
  }
}

function gameLoop() {
  const now = performance.now();
  const delta = now - lastTime;
  lastTime = now;

  update(delta);
  draw();

  requestAnimationFrame(gameLoop);
}

spawnEnemy();
gameLoop();
