// Game state
const game = {
    score: 0,
    level: 1,
    lives: 3,
    typingText: '',
    inputText: '',
    targetTextIndex: 0,
    gameOver: false,
    startTime: 0,
    elapsedTime: 0,
    frameCount: 0
};

// Generate random text
function generateRandomText(length) {
    const characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    let result = '';
    for (let i = 0; i < length; i++) {
        result += characters.charAt(Math.floor(Math.random() * characters.length));
    }
    return result;
}

// Update game state
function update() {
    if (game.gameOver) return;

    if (game.frameCount % 60 === 0) { // Update text every second
        game.typingText = generateRandomText(10);
        game.targetTextIndex = 0;
        game.startTime = performance.now();
    }

    if (game.inputText === game.typingText.substring(0, game.targetTextIndex)) {
        game.targetTextIndex++;
    }

    if (game.targetTextIndex === game.typingText.length) {
        game.score += 10 * game.level;
        game.inputText = '';
        game.targetTextIndex = 0;
        game.level++;
    }

    game.elapsedTime = (performance.now() - game.startTime) / 1000;
    if (game.elapsedTime > 10) {
        game.lives--;
        if (game.lives <= 0) {
            game.gameOver = true;
        } else {
            game.inputText = '';
            game.targetTextIndex = 0;
            game.startTime = performance.now();
        }
    }
}

// Render the game
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.font = '30px Arial';
    ctx.fillStyle = 'black';

    if (!game.gameOver) {
        ctx.fillText(`Score: ${game.score}`, 10, 50);
        ctx.fillText(`Level: ${game.level}`, 10, 80);
        ctx.fillText(`Lives: ${game.lives}`, 10, 110);

        const targetText = game.typingText.substring(0, game.targetTextIndex);
        const remainingText = game.typingText.substring(game.targetTextIndex);
        ctx.fillText(`${targetText}${remainingText}`, 10, 180);
        ctx.fillText(`Input: ${game.inputText}`, 10, 210);
        ctx.fillText(`Time: ${Math.ceil(10 - game.elapsedTime)}s`, 10, 240);
    } else {
        ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2 - 10);
        ctx.fillText(`Final Score: ${game.score}`, canvas.width / 2 - 100, canvas.height / 2 + 20);
    }
}

// Game loop
function gameLoop(timestamp) {
    update();
    render();
    if (!game.gameOver) {
        requestAnimationFrame(gameLoop);
    }
}

// Start the game
requestAnimationFrame(gameLoop);

// Input handling
document.addEventListener('keydown', (e) => {
    if (game.gameOver) return;

    if (e.key === 'Backspace') {
        game.inputText = game.inputText.slice(0, -1);
    } else if (e.key.length === 1) {
        game.inputText += e.key;
    }
});
