// Load card images
const cardImages = [];
for (let i = 1; i <= cardPairs; i++) {
  cardImages.push(`image${i}.png`);
  cardImages.push(`image${i}.png`);
}

// Shuffle card images
for (let i = cardImages.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [cardImages[i], cardImages[j]] = [cardImages[j], cardImages[i]];
}

// Create cards
for (let i = 0; i < rows; i++) {
  for (let j = 0; j < cols; j++) {
    const x = j * (cardWidth + cardSpacing) + (canvas.width - (cols * (cardWidth + cardSpacing))) / 2;
    const y = i * (cardHeight + cardSpacing) + (canvas.height - (rows * (cardHeight + cardSpacing))) / 2;
    cards.push({
      x,
      y,
      image: cardImages.shift(),
      flipped: false,
      matched: false
    });
  }
}

function drawCard(card) {
  if (card.flipped || card.matched) {
    const img = new Image();
    img.src = card.image;
    ctx.drawImage(img, card.x, card.y, cardWidth, cardHeight);
  } else {
    ctx.fillStyle = '#ccc';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  }
}

function drawEnemies() {
  ctx.fillStyle = 'red';
  for (let i = 0; i < enemyCount; i++) {
    const x = Math.random() * (canvas.width - 20);
    const y = Math.random() * (canvas.height - 20);
    ctx.fillRect(x, y, 20, 20);
  }
}

function update(deltaTime) {
  if (performance.now() - lastSpawnTime >= spawnInterval) {
    lastSpawnTime = performance.now();
    enemyCount++;
    spawnInterval = Math.max(1000, spawnInterval - 100); // Decrease spawn interval to increase difficulty
  }
}

function flipCard(card) {
  if (flippedCards.length < 2 && !card.flipped && !card.matched) {
    card.flipped = true;
    flippedCards.push(card);
    if (flippedCards.length === 2) {
      setTimeout(() => {
        if (flippedCards[0].image === flippedCards[1].image) {
          flippedCards[0].matched = true;
          flippedCards[1].matched = true;
          matchedCards += 2;
        }
        flippedCards[0].flipped = false;
        flippedCards[1].flipped = false;
        flippedCards.length = 0;
      }, 500);
    }
  }
}

function gameLoop() {
  const now = performance.now();
  const deltaTime = now - lastUpdateTime;
  lastUpdateTime = now;

  update(deltaTime);

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  cards.forEach(drawCard);
  drawEnemies();

