const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const gravity = 0.5;
const jumpSpeed = -10;
const playerWidth = 32;
const playerHeight = 32;
const playerColor = 'blue';
const groundY = canvas.height - playerHeight;

let playerX = 100;
let playerY = groundY;
let playerVelocityY = 0;
let playerJumping = false;

let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

let currentState = 'menu';

const states = {
  menu: {
    update() {
      if (keys['Enter']) {
        currentState = 'playing';
      }
    },
    render() {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.font = '32px Arial';
      ctx.fillStyle = 'white';
      ctx.fillText('Press Enter to Play', canvas.width / 2 - 150, canvas.height / 2);
    }
  },
  playing: {
    update() {
      if (keys['ArrowLeft']) {
        playerX -= 5;
      }
      if (keys['ArrowRight']) {
        playerX += 5;
      }
      if (keys['ArrowUp'] && !playerJumping) {
        playerVelocityY = jumpSpeed;
        playerJumping = true;
      }

      playerVelocityY += gravity;
      playerY += playerVelocityY;

      if (playerY > groundY) {
        playerY = groundY;
        playerVelocityY = 0;
        playerJumping = false;
      }

      score++;
    },
    render() {
      ctx.fillStyle = 'lightgray';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = playerColor;
      ctx.fillRect(playerX, playerY, playerWidth, playerHeight);

      ctx.font = '16px Arial';
      ctx.fillStyle = 'black';
      ctx.fillText(`Score: ${score}`, 10, 20);
    }
  },
  paused: {
    update() {
      if (keys['Enter']) {
        currentState = 'playing';
      }
    },
    render() {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.font = '32px Arial';
      ctx.fillStyle = 'white';
      ctx.fillText('Paused', canvas.width / 2 - 50, canvas.height / 2);
    }
  },
  gameover: {
    update() {
      if (keys['Enter']) {
        score = 0;
        currentState = 'playing';
      }
    },
    render() {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.font = '32px Arial';
      ctx.fillStyle = 'white';
      ctx.fillText('Game Over', canvas.width / 2 - 70, canvas.height / 2);
      ctx.fillText(`Score: ${score}`, canvas.width / 2 - 50, canvas.height / 2 + 40);
      ctx.fillText(`High Score: ${highScore}`, canvas.width / 2 - 75, canvas.height / 2 + 80);
    }
  }
};

const keys = {};
document.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});
document.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

const fixedTimeStep = 1 / 60;
let accumulator = 0;
let lastTime = performance.now();

function gameLoop(time) {
  const frameTime = time - lastTime;
  lastTime = time;
  accumulator += frameTime;

  while (accumulator >= fixedTimeStep) {
    states[currentState].update();
    accumulator -= fixedTimeStep;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  states[currentState].render();

  if (currentState === 'playing' && playerY === groundY) {
    currentState = 'gameover';
    if (score > highScore) {
      highScore = score;
      localStorage.setItem('highScore', highScore);
    }
  }

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
