(function() {
  const canvas = document.createElement('canvas');
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');
  let dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);

  const enemies = [];
  const towers = [];
  const bullets = [];
  let score = 0;
  let gameOver = false;

  class Entity {
    constructor(x, y, width, height) {
      this.x = x;
      this.y = y;
      this.width = width;
      this.height = height;
    }

    draw() {
      ctx.fillStyle = this.color;
      ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    isColliding(entity) {
      return this.x < entity.x + entity.width &&
             this.x + this.width > entity.x &&
             this.y < entity.y + entity.height &&
             this.y + this.height > entity.y;
    }
  }

  class Enemy extends Entity {
    constructor(x, y) {
      super(x, y, 20, 20);
      this.color = 'red';
      this.speed = 1;
    }

    update() {
      this.x -= this.speed;
      if (this.x + this.width < 0) {
        gameOver = true;
      }
    }
  }

  class Tower extends Entity {
    constructor(x, y) {
      super(x, y, 30, 30);
      this.color = 'green';
      this.range = 100;
      this.cooldown = 0;
    }

    update() {
      if (this.cooldown > 0) {
        this.cooldown--;
        return;
      }
      for (let enemy of enemies) {
        if (this.isColliding(enemy)) {
          bullets.push(new Bullet(this.x + this.width / 2, this.y + this.height / 2, enemy.x, enemy.y));
          this.cooldown = 30;
          break;
        }
      }
    }
  }

  class Bullet extends Entity {
    constructor(x, y, targetX, targetY) {
      super(x, y, 5, 5);
      this.color = 'blue';
      this.speed = 5;
      this.targetX = targetX;
      this.targetY = targetY;
      const dx = targetX - x;
      const dy = targetY - y;
      this.angle = Math.atan2(dy, dx);
    }

    update() {
      this.x += Math.cos(this.angle) * this.speed;
      this.y += Math.sin(this.angle) * this.speed;
      for (let enemy of enemies) {
        if (this.isColliding(enemy)) {
          enemies.splice(enemies.indexOf(enemy), 1);
          score += 10;
          return;
        }
      }
      if (this.x < 0 || this.x > canvas.width || this.y < 0 || this.y > canvas.height) {
        bullets.splice(bullets.indexOf(this), 1);
      }
    }
  }

  function spawnEnemy() {
    enemies.push(new Enemy(canvas.width, Math.random() * (canvas.height - 20)));
  }

  function spawnTower(x, y) {
    towers.push(new Tower(x, y));
  }

  canvas.addEventListener('click', (event) => {
    if (!gameOver) {
      const rect = canvas.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      spawnTower(x, y);
    }
  });

  function update() {
    if (gameOver) return;
    if (Math.random() < 0.02) spawnEnemy();
    for (let enemy of enemies) enemy.update();
    for (let tower of towers) tower.update();
    for (let bullet of bullets) bullet.update();
    requestAnimationFrame(update);
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let enemy of enemies) enemy.draw();
    for (let tower of towers) tower.draw();
    for (let bullet of bullets) bullet.draw();
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (gameOver) {
      ctx.font = '48px Arial';
      ctx.fillStyle = 'red';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
    requestAnimationFrame(draw);
  }

  update();
  draw();

  window.addEventListener('resize', () => {
    dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
  });
})();
