    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
    ctx.font = '24px Arial';

    let countdown = 5;
    let startTime;
    let inputText = '';
    let textToType = 'The quick brown fox jumps over the lazy dog.';
    let inputIndex = 0;
    let timerId;

    function startGame() {
        startTime = Date.now();
        timerId = setInterval(update, 1000);
    }

    function update() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillText(`Time: ${countdown}s`, 10, 30);
        ctx.fillText(textToType, 10, 80);
        ctx.fillText(inputText, 10, 130);

        if (countdown > 0) {
            countdown--;
        } else {
            clearInterval(timerId);
            ctx.fillText('Game Over', canvas.width / 2 - 50, 180);
        }
    }

    function checkInput(event) {
        if (event.key === textToType[inputIndex]) {
            inputText += event.key;
            inputIndex++;
        } else if (event.key === 'Backspace' && inputText.length > 0) {
            inputText = inputText.slice(0, -1);
            inputIndex--;
        }

        if (inputText === textToType) {
            clearInterval(timerId);
            ctx.fillText('You Win!', canvas.width / 2 - 50, 180);
        }
    }

    window.addEventListener('resize', () => {
        canvas.width = window.innerWidth * dpr;
        canvas.height = window.innerHeight * dpr;
        ctx.scale(dpr, dpr);
    });

    window.addEventListener('keydown', checkInput);

    startGame();
})();
