// Output: ['apple', 'banana', 'orange', 'grape']

// Real-world example: Remove duplicate objects by property
console.log('\n=== Remove Duplicates from Objects ===');

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
