// Fishing Mini-Game
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fish = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 20,
    speed: 1.5,
    angle: 0,
    dx: 0,
    dy: 0
};

const rod = {
    length: 150,
    angle: 0,
    color: '#000'
};

const hook = {
    length: 20,
    color: '#000'
};

const bait = {
    x: 0,
    y: 0,
    size: 10,
    color: '#ff0'
};

function drawFish() {
    ctx.save();
    ctx.translate(fish.x, fish.y);
    ctx.rotate(fish.angle);
    ctx.fillStyle = '#00f';
    ctx.fillRect(-fish.size / 2, -fish.size / 2, fish.size, fish.size);
    ctx.restore();
}

function drawRod() {
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2, canvas.height);
    ctx.lineTo(canvas.width / 2 + rod.length * Math.cos(rod.angle), canvas.height + rod.length * Math.sin(rod.angle));
    ctx.strokeStyle = rod.color;
    ctx.stroke();
}

function drawHook() {
    const endX = canvas.width / 2 + rod.length * Math.cos(rod.angle);
    const endY = canvas.height + rod.length * Math.sin(rod.angle);
    ctx.beginPath();
    ctx.moveTo(endX, endY);
    ctx.lineTo(endX + hook.length * Math.cos(rod.angle + Math.PI / 2), endY + hook.length * Math.sin(rod.angle + Math.PI / 2));
    ctx.strokeStyle = hook.color;
    ctx.stroke();
}

function drawBait() {
    ctx.beginPath();
    ctx.arc(bait.x, bait.y, bait.size, 0, Math.PI * 2);
    ctx.fillStyle = bait.color;
    ctx.fill();
}

function updateFish() {
    fish.x += fish.dx * fish.speed;
    fish.y += fish.dy * fish.speed;
    fish.angle += Math.random() * 0.1 - 0.05;
}

function updateBait() {
    bait.x = canvas.width / 2 + rod.length * Math.cos(rod.angle);
    bait.y = canvas.height + rod.length * Math.sin(rod.angle);
}

function checkCollision() {
    const dx = fish.x - bait.x;
    const dy = fish.y - bait.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < fish.size / 2 + bait.size) {
        fish.x = canvas.width / 2;
        fish.y = canvas.height / 2;
        fish.angle = 0;
        fish.dx = 0;
        fish.dy = 0;
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawFish();
    drawRod();
    drawHook();
    drawBait();
}

function update() {
    updateFish();
    updateBait();
    checkCollision();
}

function mainLoop(timestamp) {
    const delta = timestamp - lastTime;
    if (delta >= 1000 / 60) { // 60 FPS
        lastTime = timestamp;
        update();
        render();
    }
    requestAnimationFrame(mainLoop);
}

let lastTime = performance.now();
requestAnimationFrame(mainLoop);

canvas.addEventListener('mousemove', (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;
    rod.angle = Math.atan2(mouseY - canvas.height, mouseX - canvas.width / 2);
});

document.addEventListener('keydown', (event) => {
    switch (event.key) {
        case 'ArrowUp':
            fish.dy = -1;
            break;
        case 'ArrowDown':
            fish.dy = 1;
            break;
        case 'ArrowLeft':
            fish.dx = -1;
            break;
        case 'ArrowRight':
            fish.dx = 1;
            break;
    }
});

document.addEventListener('keyup', (event) => {
