        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      }
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(playerX * cellSize + (cellSize - playerSize) / 2, playerY * cellSize + (cellSize - playerSize) / 2, playerSize, playerSize);
