const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;
let tiles = [];
let health = 3;
let score = 0;
const tileColors = ['#EEE4DA', '#EDE0C8', '#F2B179', '#F59563', '#F67C5F', '#F65E3B', '#EDCF72', '#EDCC61', '#EDC850', '#EDC53F'];

function init() {
    tiles = [];
    for (let i = 0; i < 16; i++) {
        tiles.push({ value: 0 });
    }
    spawnTile();
    spawnTile();
}

function spawnTile() {
    const emptyTiles = tiles.filter(t => t.value === 0).map((_, i) => i);
    if (emptyTiles.length > 0) {
        const randomIndex = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        tiles[randomIndex].value = Math.random() < 0.9 ? 2 : 4;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < 16; i++) {
        const x = (i % 4) * 100 + 5;
        const y = Math.floor(i / 4) * 100 + 5;
        ctx.fillStyle = tileColors[Math.log2(tiles[i].value) - 1] || '#CDC1B4';
        ctx.fillRect(x, y, 90, 90);
        if (tiles[i].value > 0) {
            ctx.fillStyle = tiles[i].value >= 8 ? '#F9F6F2' : '#776E65';
            ctx.font = 'bold 24px Arial';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(tiles[i].value, x + 45, y + 45);
        }
    }
    ctx.fillStyle = '#776E65';
    ctx.font = 'bold 18px Arial';
    ctx.fillText(`Health: ${health}`, 20, 20);
    ctx.fillText(`Score: ${score}`, 20, 40);
}

function slide(row) {
    let newRow = row.filter(t => t.value !== 0);
    for (let i = 0; i < newRow.length - 1; i++) {
        if (newRow[i].value === newRow[i + 1].value) {
            newRow[i].value *= 2;
            newRow[i + 1].value = 0;
            score += newRow[i].value;
        }
    }
    newRow = newRow.filter(t => t.value !== 0);
    while (newRow.length < 4) {
        newRow.push({ value: 0 });
    }
    return newRow;
}

function move(direction) {
    let moved = false;
    let newTiles = [];
    if (direction === 'UP' || direction === 'DOWN') {
        for (let i = 0; i < 4; i++) {
            let column = [];
            for (let j = 0; j < 4; j++) {
                column.push(direction === 'UP' ? tiles[j * 4 + i] : tiles[(3 - j) * 4 + i]);
            }
            const newColumn = slide(column);
            for (let j = 0; j < 4; j++) {
                if (direction === 'UP') {
                    newTiles[j * 4 + i] = newColumn[j];
                    if (!moved && tiles[j * 4 + i].value !== newColumn[j].value) moved = true;
                } else {
                    newTiles[(3 - j) * 4 + i] = newColumn[j];
                    if (!moved && tiles[(3 - j) * 4 + i].value !== newColumn[j].value) moved = true;
                }
            }
        }
    } else {
        for (let i = 0; i < 4; i++) {
            let row = [];
            for (let j = 0; j < 4; j++) {
                row.push(direction === 'LEFT' ? tiles[i * 4 + j] : tiles[i * 4 + (3 - j)]);
            }
            const newRow = slide(row);
            for (let j = 0; j < 4; j++) {
                if (direction === 'LEFT') {
                    newTiles[i * 4 + j] = newRow[j];
                    if (!moved && tiles[i * 4 + j].value !== newRow[j].value) moved = true;
                } else {
                    newTiles[i * 4 + (3 - j)] = newRow[j];
                    if (!moved && tiles[i * 4 + (3 - j)].value !== newRow[j].value) moved = true;
                }
            }
        }
    }
    if (moved) {
        tiles = newTiles;
        spawnTile();
        if (!hasMoves()) {
            health--;
            if (health <= 0) {
                alert(`Game Over! Your final score was ${score}.`);
                init();
            } else {
                alert(`You lost a life! Remaining health: ${health}`);
            }
        }
    }
}

function hasMoves() {
    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (tiles[i * 4 + j].value === 0) return true;
            if (i > 0 && tiles[i * 4 + j].value === tiles[(i - 1) * 4 + j].value) return true;
            if (j > 0 && tiles[i * 4 + j].value === tiles[i * 4 + j - 1].value) return true;
        }
    }
    return false;
}

function gameLoop() {
    draw();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            move('UP');
            break;
        case 'ArrowDown':
            move('DOWN');
            break;
        case 'ArrowLeft':
            move('LEFT');
            break;
        case 'ArrowRight':
            move('RIGHT');
            break;
        case 'r':
        case 'R':
            init();
            break;
    }
});

init();
gameLoop();
```

