canvas.width = 400;
canvas.height = 400;

const boardSize = 8;
const tileWidth = canvas.width / boardSize;
const tileHeight = canvas.height / boardSize;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];
let board = [];
let health = 3;
let animationFrameId;

function createBoard() {
    for (let i = 0; i < boardSize; i++) {
        board[i] = [];
        for (let j = 0; j < boardSize; j++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function drawBoard() {
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            ctx.fillStyle = colors[board[i][j]];
            ctx.fillRect(j * tileWidth, i * tileHeight, tileWidth, tileHeight);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(j * tileWidth, i * tileHeight, tileWidth, tileHeight);
        }
    }
}

function drawHealthBar() {
    ctx.fillStyle = 'green';
    ctx.fillRect(0, canvas.height - 20, (health / 3) * canvas.width, 20);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(0, canvas.height - 20, canvas.width, 20);
}

function checkMatches() {
    let matchesFound = false;
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            if (board[i][j] !== null) {
                let matches = [];
                // Check horizontal
                if (j > 0 && board[i][j] === board[i][j - 1] && (j < boardSize - 1 && board[i][j] === board[i][j + 1])) {
                    matches = [board[i][j - 1], board[i][j], board[i][j + 1]];
                }
                // Check vertical
                if (i > 0 && board[i][j] === board[i - 1][j] && (i < boardSize - 1 && board[i][j] === board[i + 1][j])) {
                    matches = [board[i - 1][j], board[i][j], board[i + 1][j]];
                }
                if (matches.length > 0) {
                    matchesFound = true;
                    for (let match of matches) {
                        let index = board[i].indexOf(match);
                        while (index !== -1) {
                            board[i][index] = null;
                            index = board[i].indexOf(match, index + 1);
                        }
                    }
                }
            }
        }
    }
    return matchesFound;
}

function fillGaps() {
    for (let j = 0; j < boardSize; j++) {
        let nullCount = 0;
        for (let i = boardSize - 1; i >= 0; i--) {
            if (board[i][j] === null) {
                nullCount++;
            } else if (nullCount > 0) {
                board[i + nullCount][j] = board[i][j];
                board[i][j] = null;
            }
        }
        for (let i = 0; i < nullCount; i++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    drawHealthBar();
    if (checkMatches()) {
        fillGaps();
    } else {
        health--;
        if (health <= 0) {
            cancelAnimationFrame(animationFrameId);
            alert('Game Over!');
            return;
        }
    }
    animationFrameId = requestAnimationFrame(gameLoop);
}

createBoard();
gameLoop();
