const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 400;
canvas.height = 400;
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF69B4', '#FFD700', '#32CD32', '#1E90FF', '#FF4500', '#7B68EE', '#ADFF2F', '#FF1493'];

let board = [];
let score = 0;
let timeLeft = 60;

function initBoard() {
    for (let i = 0; i < boardSize; i++) {
        board[i] = [];
        for (let j = 0; j < boardSize; j++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            ctx.fillStyle = colors[board[i][j]];
            ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(i * cellSize, j * cellSize, cellSize, cellSize);
        }
    }
}

function updateBoard() {
    let matches = findMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        dropTiles();
        fillBoard();
        score += matches.length;
    }
}

function findMatches() {
    let matches = [];
    for (let i = 0; i < boardSize; i++) {
        for (let j = 0; j < boardSize; j++) {
            if (i < boardSize - 2 && board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
            if (j < boardSize - 2 && board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    for (let [i, j] of matches) {
        board[i][j] = -1;
    }
}

function dropTiles() {
    for (let j = 0; j < boardSize; j++) {
        for (let i = boardSize - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                for (let k = i; k > 0; k--) {
                    board[k][j] = board[k - 1][j];
                }
                board[0][j] = -1;
