const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const gravity = 0.98;
const enemies = [];
const balls = [];
let enemySpawnInterval = 2000;
let lastEnemySpawn = Date.now();

function spawnEnemy() {
    const x = Math.random() * canvas.width;
    const y = -50;
    const radius = 10 + Math.random() * 20;
    enemies.push({ x, y, radius, velocityY: 2 + Math.random() * 2 });
}

function update() {
    const now = Date.now();
    if (now - lastEnemySpawn > enemySpawnInterval) {
        spawnEnemy();
        lastEnemySpawn = now;
        enemySpawnInterval = Math.max(1000, enemySpawnInterval * 0.95); // Increase difficulty by reducing spawn interval
    }

    // Update enemies
    enemies.forEach(enemy => {
        enemy.y += enemy.velocityY;
        enemy.velocityY += gravity;
        if (enemy.y > canvas.height + enemy.radius) {
            enemies.shift(); // Remove enemies that fall off screen
        }
    });

    // Update balls
    balls.forEach(ball => {
        ball.y += ball.velocityY;
        ball.velocityY += gravity;
        if (ball.y > canvas.height - ball.radius) {
            ball.y = canvas.height - ball.radius;
            ball.velocityY *= -0.5; // Bounce
        }
    });

    // Check for collisions
    balls.forEach(ball => {
        enemies.forEach((enemy, index) => {
            const dx = ball.x - enemy.x;
            const dy = ball.y - enemy.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < ball.radius + enemy.radius) {
                enemies.splice(index, 1); // Remove hit enemy
            }
        });
    });

    // Render
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.fillStyle = 'blue';
    balls.forEach(ball => {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
        ctx.fill();
    });

    requestAnimationFrame(update);
}

function handleMouseMove(event) {
    const x = event.clientX;
    const y = event.clientY;
    const ball = { x, y, radius: 15, velocityY: -10 };
    balls.push(ball);
}

canvas.addEventListener('mousemove', handleMouseMove);
update();
