const bird = {
    x: 50,
    y: 150,
    width: 30,
    height: 30,
    velocity: 0,
    gravity: 0.5,
    lift: -10
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 200;
let pipeSpawnTimer = 0;
const pipeSpawnInterval = 1500;

function drawBird() {
    ctx.fillStyle = 'red';
    ctx.fillRect(bird.x, bird.y, bird.width, bird.height);
}

function drawPipes() {
    ctx.fillStyle = 'green';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, 0, pipeWidth, pipe.height);
        ctx.fillRect(pipe.x, pipe.height + pipeGap, pipeWidth, canvas.height - pipe.height - pipeGap);
    });
}

function updateBird() {
    bird.velocity += bird.gravity;
    bird.y += bird.velocity;

    if (bird.y + bird.height > canvas.height || bird.y < 0) {
        resetGame();
    }

    pipes.forEach(pipe => {
        if (bird.x < pipe.x + pipeWidth && bird.x + bird.width > pipe.x &&
            (bird.y < pipe.height || bird.y + bird.height > pipe.height + pipeGap)) {
            resetGame();
        }
    });
}

function updatePipes(deltaTime) {
    pipeSpawnTimer += deltaTime;
    if (pipeSpawnTimer >= pipeSpawnInterval) {
        const pipeHeight = Math.random() * (canvas.height - pipeGap);
        pipes.push({ x: canvas.width, height: pipeHeight });
        pipeSpawnTimer = 0;
    }

    pipes.forEach(pipe => {
        pipe.x -= 2;
    });

    pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);
}

function resetGame() {
    pipes.length = 0;
    bird.y = canvas.height / 2;
    bird.velocity = 0;
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    updateBird();
    updatePipes(deltaTime);

    drawBird();
    drawPipes();

    requestAnimationFrame(gameLoop);
}

let lastTime = 0;
requestAnimationFrame(gameLoop);

window.addEventListener('keydown', event => {
    if (event.code === 'Space') {
        bird.velocity = bird.lift;
    }
});

