canvas.height = height * dpr;
canvas.style.width = width + 'px';
canvas.style.height = height + 'px';
ctx.scale(dpr, dpr);

const mazeSize = 20;
const maze = [];
let player = { x: mazeSize / 2, y: mazeSize / 2 };
let powerUps = [];
let score = 0;

function generateMaze() {
    for (let i = 0; i < mazeSize; i++) {
        maze[i] = [];
        for (let j = 0; j < mazeSize; j++) {
            maze[i][j] = Math.random() > 0.5 ? 1 : 0;
        }
    }
    maze[player.x][player.y] = 0;
    placePowerUps();
}

function placePowerUps() {
    powerUps = [];
    for (let i = 0; i < 10; i++) {
        let x, y;
        do {
            x = Math.floor(Math.random() * mazeSize);
            y = Math.floor(Math.random() * mazeSize);
        } while (maze[x][y] === 1 || (x === player.x && y === player.y));
        powerUps.push({ x, y });
    }
}

function drawMaze() {
    ctx.fillStyle = 'black';
    for (let i = 0; i < mazeSize; i++) {
        for (let j = 0; j < mazeSize; j++) {
            if (maze[i][j] === 1) {
                ctx.fillRect(i * 30, j * 30, 30, 30);
            }
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * 30, player.y * 30, 30, 30);
}

function drawPowerUps() {
    ctx.fillStyle = 'red';
    powerUps.forEach(pu => ctx.fillRect(pu.x * 30, pu.y * 30, 30, 30));
}

function drawScore() {
    ctx.fillStyle = 'white';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + score, 10, 20);
}

function updatePlayer(dx, dy) {
    const nx = player.x + dx;
    const ny = player.y + dy;
    if (nx >= 0 && nx < mazeSize && ny >= 0 && ny < mazeSize && maze[nx][ny] === 0) {
        player.x = nx;
        player.y = ny;
        checkPowerUpCollision();
    }
}

function checkPowerUpCollision() {
    powerUps = powerUps.filter(pu => !(pu.x === player.x && pu.y === player.y));
    if (powerUps.length < 10) {
        placePowerUps();
    }
    score++;
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMaze();
    drawPlayer();
    drawPowerUps();
    drawScore();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', e => {
    switch (e.key) {
        case 'ArrowUp': updatePlayer(0, -1); break;
        case 'ArrowDown': updatePlayer(0, 1); break;
        case 'ArrowLeft': updatePlayer(-1, 0); break;
        case 'ArrowRight': updatePlayer(1, 0); break;
    }
});

generateMaze();
gameLoop();
