const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const states = {
    menu: 'menu',
    playing: 'playing',
    paused: 'paused',
    gameover: 'gameover'
};

let currentState = states.menu;
let score = 0;
let lives = 3;
let wave = 1;
let enemies = [];
let towers = [];
let bullets = [];
const enemySpeed = 1;
const towerRange = 100;
const towerDamage = 1;
const enemyHealth = 10;

function menuState() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '30px Arial';
    ctx.fillText('Tower Defense', canvas.width / 2 - 100, canvas.height / 2);
    ctx.fillText('Click to Start', canvas.width / 2 - 100, canvas.height / 2 + 50);
}

function playingState() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Lives: ${lives}`, 10, 50);
    ctx.fillText(`Wave: ${wave}`, 10, 70);

    enemies.forEach((enemy, index) => {
        enemy.x += enemySpeed;
        if (enemy.x > canvas.width) {
            lives--;
            enemies.splice(index, 1);
        } else {
            ctx.fillStyle = 'red';
            ctx.fillRect(enemy.x, enemy.y, 20, 20);
        }
    });

    towers.forEach(tower => {
        ctx.fillStyle = 'blue';
        ctx.beginPath();
        ctx.arc(tower.x, tower.y, towerRange, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = 'green';
        ctx.fillRect(tower.x - 5, tower.y - 5, 10, 10);

        const target = enemies.find(enemy => Math.hypot(tower.x - enemy.x, tower.y - enemy.y) < towerRange);
        if (target) {
            bullets.push({ x: tower.x, y: tower.y, target });
        }
    });

    bullets.forEach((bullet, index) => {
        ctx.fillStyle = 'yellow';
        ctx.fillRect(bullet.x, bullet.y, 5, 5);

        const dx = bullet.target.x - bullet.x;
        const dy = bullet.target.y - bullet.y;
        const dist = Math.hypot(dx, dy);
        const speed = 5;
        bullet.x += dx / dist * speed;
        bullet.y += dy / dist * speed;

        if (Math.hypot(bullet.x - bullet.target.x, bullet.y - bullet.target.y) < 5) {
            enemies = enemies.filter(enemy => enemy !== bullet.target);
            score += 10;
            bullets.splice(index, 1);
        }
    });
}

function pausedState() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '30px Arial';
    ctx.fillText('Paused', canvas.width / 2 - 50, canvas.height / 2);
}

function gameoverState() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
    ctx.fillText(`Score: ${score}`, canvas.width / 2 - 50, canvas.height / 2 + 50);
}

function update() {
    switch (currentState) {
        case states.menu:
            menuState();
            break;
        case states.playing:
            playingState();
            break;
        case states.paused:
            pausedState();
            break;
        case states.gameover:
            gameoverState();
            break;
    }
    requestAnimationFrame(update);
}

function startGame() {
    currentState = states.playing;
    wave = 1;
    score = 0;
    lives = 3;
    enemies = [];
    towers = [];
    bullets = [];
    for (let i = 0; i < wave; i++) {
        enemies.push({ x: -20, y: Math.random() * canvas.height });
    }
}

function handleMouseClick(event) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    switch (currentState) {
        case states.menu:
            startGame();
            break;
        case states.playing:
            towers.push({ x, y });
            break;
        case states.paused:
            currentState = states.playing;
            break;
        case states.gameover:
            startGame();
