// 2048-style slide game with scoring and game-over state
const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileSize = 100;
const gridSize = 4;
const tilePadding = 5;
const colors = {
  0: '#ccc',
  2: '#eee',
  4: '#ddd',
  8: '#bfb',
  16: '#a9a',
  32: '#979',
  64: '#858',
  128: '#737',
  256: '#616',
  512: '#4f4',
  1024: '#3d3',
  2048: '#2b2',
};

let tiles = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
let score = 0;
let gameOver = false;

function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function spawnTile() {
  const emptyTiles = [];
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (tiles[i][j] === 0) {
        emptyTiles.push({ x: i, y: j });
      }
    }
  }
  if (emptyTiles.length > 0) {
    const { x, y } = emptyTiles[getRandomInt(0, emptyTiles.length - 1)];
    tiles[x][y] = Math.random() > 0.9 ? 4 : 2;
  }
}

function move(direction) {
  let moved = false;
  for (let row = 0; row < gridSize; row++) {
    for (let col = 0; col < gridSize; col++) {
      if (tiles[row][col] === 0) continue;
      let { x, y, value } = { x: row, y: col, value: tiles[row][col] };
      tiles[row][col] = 0;
      while (true) {
        let nx = x, ny = y;
        if (direction === 'up') ny--;
        if (direction === 'down') ny++;
        if (direction === 'left') nx--;
        if (direction === 'right') nx++;
        if (nx < 0 || nx >= gridSize || ny < 0 || ny >= gridSize) break;
        if (tiles[nx][ny] === 0) {
          x = nx; y = ny;
          moved = true;
        } else if (tiles[nx][ny] === value) {
          x = nx; y = ny;
          tiles[x][y] *= 2;
          score += tiles[x][y];
          moved = true;
          break;
        } else {
          break;
        }
      }
      tiles[x][y] = value;
    }
  }
  return moved;
}

function checkGameOver() {
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (tiles[i][j] === 0) return false;
      if ((i > 0 && tiles[i][j] === tiles[i - 1][j]) ||
          (j > 0 && tiles[i][j] === tiles[i][j - 1])) {
        return false;
      }
    }
  }
  return true;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      ctx.fillStyle = colors[tiles[i][j]] || '#ccc';
      ctx.fillRect(j * tileSize + tilePadding, i * tileSize + tilePadding,
                   tileSize - tilePadding * 2, tileSize - tilePadding * 2);
      if (tiles[i][j] !== 0) {
        ctx.fillStyle = '#000';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '30px Arial';
        ctx.fillText(tiles[i][j].toString(), j * tileSize + tileSize / 2, i * tileSize + tileSize / 2);
      }
    }
  }
  ctx.fillStyle = '#000';
  ctx.fillText(`Score: ${score}`, 20, 40);
}

function update() {
  if (gameOver) return;
  spawnTile();
  gameOver = checkGameOver();
}

const frameRate = 60;
const frameTime = 1000 / frameRate;
let lastFrameTime = 0;

function gameLoop(timestamp) {
  let deltaTime = timestamp - lastFrameTime;
  if (deltaTime > frameTime) {
    lastFrameTime = timestamp - (deltaTime % frameTime);
    update();
  }
  draw();
  requestAnimationFrame(gameLoop);
}

spawnTile();
spawnTile();
requestAnimationFrame(gameLoop);

document.addEventListener('keydown', (e) => {
  if (gameOver) return;
  let moved = false;
  switch (e.key) {
    case 'ArrowUp': moved = move('up'); break;
    case 'ArrowDown': moved = move('down'); break;
    case 'ArrowLeft': moved = move('left'); break;
    case 'ArrowRight': moved = move('right'); break;
  }
  if (moved) {
    spawnTile();
    gameOver = checkGameOver();
  }
});
