class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.range = 100;
    this.damage = 50;
    this.attackSpeed = 1000; // milliseconds
    this.lastAttackTime = 0;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.range, 0, Math.PI * 2);
    ctx.strokeStyle = 'blue';
    ctx.stroke();
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x - 10, this.y - 10, 20, 20);
  }

  attack(enemies) {
    const now = performance.now();
    if (now - this.lastAttackTime >= this.attackSpeed) {
      this.lastAttackTime = now;
      for (const enemy of enemies) {
        if (this.distanceTo(enemy) <= this.range) {
          enemy.health -= this.damage;
          if (enemy.health <= 0) {
            enemies.splice(enemies.indexOf(enemy), 1);
          }
          break; // Assuming combo attack hits one enemy
        }
      }
    }
  }

  distanceTo(enemy) {
    return Math.sqrt((this.x - enemy.x) ** 2 + (this.y - enemy.y) ** 2);
  }
}

class Enemy {
  constructor(x, y, speed, health) {
    this.x = x;
    this.y = y;
    this.speed = speed;
    this.health = health;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
