let score = 0;
let gameOver = false;

function drawTile(x, y, value) {
    const color = { 2: '#eee4da', 4: '#ede0c8', 8: '#f2b179', 16: '#f59563', 32: '#f67c5f', 64: '#f65e3b', 128: '#edcf72', 256: '#edcc61', 512: '#edc850', 1024: '#edc53f', 2048: '#edc22e' }[value] || '#cdc1b4';
    ctx.fillStyle = color;
    ctx.fillRect(x * (tileSize + gap), y * (tileSize + gap), tileSize, tileSize);
    if (value) {
        ctx.font = '50px Arial';
        ctx.fillStyle = value >= 8 ? '#f9f6f2' : '#776e65';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value, x * (tileSize + gap) + tileSize / 2, y * (tileSize + gap) + tileSize / 2);
    }
}

function drawBoard() {
    ctx.fillStyle = '#bbada0';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < grid; y++) {
        for (let x = 0; x < grid; x++) {
            drawTile(x, y, board[y][x]);
        }
    }
}

function spawnTile() {
    const emptyTiles = [];
    for (let y = 0; y < grid; y++) {
        for (let x = 0; x < grid; x++) {
            if (board[y][x] === null) {
                emptyTiles.push({ x, y });
            }
        }
    }
    if (emptyTiles.length) {
        const { x, y } = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        board[y][x] = Math.random() > 0.9 ? 4 : 2;
    }
}

function merge(row) {
    let newRow = row.filter(val => val !== null);
    for (let i = 0; i < newRow.length - 1; i++) {
        if (newRow[i] === newRow[i + 1]) {
            newRow[i] *= 2;
            score += newRow[i];
            newRow.splice(i + 1, 1);
        }
    }
    while (newRow.length < grid) {
        newRow.push(null);
    }
    return newRow;
}

function moveLeft() {
    let moved = false;
    for (let y = 0; y < grid; y++) {
        let newRow = merge(board[y]);
        if (JSON.stringify(board[y]) !== JSON.stringify(newRow)) {
            board[y] = newRow;
            moved = true;
        }
    }
    return moved;
}

function moveRight() {
    let moved = false;
    for (let y = 0; y < grid; y++) {
        let newRow = merge(board[y].slice().reverse()).reverse();
        if (JSON.stringify(board[y]) !== JSON.stringify(newRow)) {
            board[y] = newRow;
            moved = true;
        }
    }
    return moved;
}

function moveUp() {
    let moved = false;
    for (let x = 0; x < grid; x++) {
        let newRow = merge(board.map(row => row[x]));
        if (JSON.stringify(board.map(row => row[x])) !== JSON.stringify(newRow)) {
            for (let y = 0; y < grid; y++) {
                board[y][x] = newRow[y];
            }
            moved = true;
        }
    }
    return moved;
}

function moveDown() {
    let moved = false;
    for (let x = 0; x < grid; x++) {
        let newRow = merge(board.map(row => row[x]).slice().reverse()).reverse();
        if (JSON.stringify(board.map(row => row[x])) !== JSON.stringify(newRow)) {
            for (let y = 0; y < grid; y++) {
                board[y][x] = newRow[y];
            }
            moved = true;
        }
    }
    return moved;
}

function checkGameOver() {
    if (board.some(row => row.some(val => val === null))) {
        return false;
    }
    for (let y = 0; y < grid; y++) {
        for (let x = 0; x < grid; x++) {
            if ((x < grid - 1 && board[y][x] === board[y][x + 1]) ||
                (y < grid - 1 && board[y][x] === board[y + 1][x])) {
                return false;
            }
        }
    }
    return true;
}

function handleInput(event) {
    let moved = false;
    if (event.key === 'ArrowLeft' || event.type === 'touchstart' && event.touches.length === 1 && event.touches[0].clientX < canvas.width / 2) {
        moved = moveLeft();
    } else if (event.key === 'ArrowRight' || event.type === 'touchstart' && event.touches.length === 1 && event.touches[0].clientX >= canvas.width / 2) {
        moved = moveRight();
    } else if (event.key === 'ArrowUp') {
        moved = moveUp();
    } else if (event.key === 'ArrowDown') {
        moved = moveDown();
    }
    if (moved) {
        spawnTile();
        gameOver = checkGameOver();
    }
}

document.addEventListener('keydown', handleInput);
canvas.addEventListener('touchstart', handleInput);
canvas.addEventListener('touchend', handleInput);

function gameLoop() {
