        this.x = x;
        this.y = y;
        this.radius = 10;
        this.type = type;
        this.color = this.getColor(type);
    }

    getColor(type) {
        switch (type) {
            case 'bounce': return 'green';
            case 'slow': return 'purple';
            case 'speed': return 'orange';
            default: return 'gray';
        }
    }

