// Constants
const POWER_UPS = ['heart', 'star', 'bolt', 'coin'];
const CANVAS_ID = 'gameCanvas';
const GAME_SPEED = 200;
const TILE_SIZE = 64;
const GRID_SIZE = 4;
const POWER_UP_CHANCE = 5; // 5% chance for a power-up

// DOM Elements
const canvas = document.createElement('canvas');
canvas.id = CANVAS_ID;
canvas.style.position = 'absolute';
canvas.style.top = '0';
canvas.style.left = '0';
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.imageRendering = 'pixelated';
document.body.appendChild(canvas);

// Context
const ctx = canvas.getContext('2d');

// State
let tiles = [];
let score = 0;
let powerUps = [];
let gameOver = false;

// Game setup
function setupGame() {
    canvas.width = window.innerWidth * window.devicePixelRatio;
    canvas.height = window.innerHeight * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    tiles = Array(GRID_SIZE * GRID_SIZE).fill(0);
    addRandomTile();
    addRandomTile();
}

// Game loop
function gameLoop() {
    if (gameOver) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawTiles();
    drawPowerUps();
    requestAnimationFrame(gameLoop);
}

// Add a random tile
function addRandomTile() {
    const emptyTiles = tiles.map((tile, index) => tile === 0 ? index : null).filter(index => index !== null);
    if (emptyTiles.length === 0) {
        gameOver = true;
        alert('Game Over! Your final score: ' + score);
        return;
    }
    const randomIndex = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    tiles[randomIndex] = Math.random() > 0.9 ? 4 : 2;
}

// Add a random power-up
function addRandomPowerUp() {
    const emptyTiles = tiles.map((tile, index) => tile === 0 ? index : null).filter(index => index !== null);
    if (emptyTiles.length === 0) return;
    const randomIndex = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
    if (Math.random() * 100 < POWER_UP_CHANCE) {
        powerUps.push({ index: randomIndex, type: POWER_UPS[Math.floor(Math.random() * POWER_UPS.length)] });
    }
}

// Draw tiles
function drawTiles() {
    for (let i = 0; i < GRID_SIZE * GRID_SIZE; i++) {
        const x = (i % GRID_SIZE) * TILE_SIZE;
        const y = Math.floor(i / GRID_SIZE) * TILE_SIZE;
        ctx.fillStyle = tiles[i] === 0 ? '#CDC1B4' : `rgb(${255 - tiles[i] * 10}, ${255 - tiles[i] * 10}, 255)`;
        ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);
        ctx.fillStyle = '#776E65';
        if (tiles[i] !== 0) ctx.fillText(tiles[i], x + TILE_SIZE / 2 - ctx.measureText(tiles[i]).width / 2, y + TILE_SIZE / 2 + 5);
    }
}

// Draw power-ups
function drawPowerUps() {
    ctx.fillStyle = '#FFD700';
    powerUps.forEach(powerUp => {
        const x = (powerUp.index % GRID_SIZE) * TILE_SIZE + TILE_SIZE / 2;
        const y = Math.floor(powerUp.index / GRID_SIZE) * TILE_SIZE + TILE_SIZE / 2;
        ctx.beginPath();
        ctx.arc(x, y, TILE_SIZE / 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#000';
        ctx.fillText(powerUp.type[0], x - 5, y + 5);
    });
}

// Handle input
document.addEventListener('keydown', (e) => {
    if (gameOver) return;
    let moved = false;
    switch (e.key) {
        case 'ArrowUp':
            moved = moveTiles(0, -1);
            break;
        case 'ArrowDown':
            moved = moveTiles(0, 1);
            break;
        case 'ArrowLeft':
            moved = moveTiles(-1, 0);
            break;
        case 'ArrowRight':
            moved = moveTiles(1, 0);
            break;
    }
    if (moved) {
        addRandomTile();
        addRandomPowerUp();
        checkPowerUps();
    }
});

// Move tiles
function moveTiles(dx, dy) {
    let moved = false;
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            const fromX = x;
            const fromY = y;
            let toX = x + dx;
            let toY = y + dy;
            while (toX >= 0 && toX < GRID_SIZE && toY >= 0 && toY < GRID_SIZE && tiles[toY * GRID_SIZE + toX] === 0) {
                tiles[toY * GRID_SIZE + toX] = tiles[fromY * GRID_SIZE + fromX];
                tiles[fromY * GRID_SIZE + fromX] = 0;
                fromX = toX;
                fromY = toY;
                toX += dx;
                toY += dy;
                moved = true;
            }
            if (toX >= 0 && toX < GRID_SIZE && toY >= 0 && toY < GRID_SIZE && tiles[toY * GRID_SIZE + toX] === tiles[fromY * GRID_SIZE + fromX]) {
                tiles[toY * GRID_SIZE + toX] *= 2;
                tiles[fromY * GRID_SIZE + fromX] = 0;
                score += tiles[toY * GRID_SIZE + toX];
                moved = true;
            }
        }
    }
    return moved;
}

// Check for power-ups
function checkPowerUps() {
    for (let i = powerUps.length - 1; i >= 0; i--) {
        const powerUp = powerUps[i];
        if (tiles[powerUp.index] !== 0) {
            applyPowerUp(powerUp);
            powerUps.splice(i, 1);
        }
    }
}

// Apply power-up
function applyPowerUp(powerUp) {
    switch (powerUp.type) {
        case 'heart':
            score += 100;
            break;
        case 'star':
            tiles = tiles.map(tile => tile === 0 ? tile : tile * 2);
            score += 500;
            break;
        case 'bolt':
            score += 200;
            break;
        case 'coin':
            score += 300;
            break;
    }
}

// Start the game
setupGame();
gameLoop();
