// Plot class
class Plot {
  constructor(x, y, width, height) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.state = 'empty';
    this.plantType = null;
    this.growth = 0;
  }

  draw() {
    ctx.fillStyle = this.state === 'empty' ? 'brown' : (this.state === 'grown' ? 'green' : 'yellow');
    ctx.fillRect(this.x, this.y, this.width, this.height);
    if (this.plantType) {
      ctx.fillStyle = 'black';
      ctx.fillText(this.plantType, this.x + this.width / 2, this.y + this.height / 2);
    }
  }

  update() {
    if (this.state === 'plowed' && this.growth < 1) {
      this.growth += 0.01;
      if (this.growth >= 1) {
        this.state = 'grown';
      }
    }
  }
}

// Initialize plots
function initPlots() {
  const plotSize = 50;
  for (let i = 0; i < canvas.width / plotSize; i++) {
    for (let j = 0; j < canvas.height / plotSize; j++) {
      gameState.plots.push(new Plot(i * plotSize, j * plotSize, plotSize, plotSize));
    }
  }
}

// Input handling
canvas.addEventListener('mousemove', (e) => {
  gameState.mouse.x = e.clientX;
  gameState.mouse.y = e.clientY;
});

canvas.addEventListener('mousedown', (e) => {
  const plot = gameState.plots.find(p => 
    gameState.mouse.x >= p.x && gameState.mouse.x <= p.x + p.width &&
    gameState.mouse.y >= p.y && gameState.mouse.y <= p.y + p.height
  );
  if (plot) {
    gameState.selectedPlot = plot;
    switch (gameState.tool) {
      case 'plow':
        if (plot.state === 'empty') {
          plot.state = 'plowed';
          plot.plantType = null;
          plot.growth = 0;
        }
        break;
      case 'harvest':
        if (plot.state === 'grown') {
          plot.state = 'empty';
          plot.plantType = null;
          plot.growth = 0;
        }
        break;
      case 'plant':
        if (plot.state === 'plowed') {
          plot.state = 'planted';
          plot.plantType = gameState.currentPlant;
          plot.growth = 0;
        }
        break;
    }
  }
});

document.addEventListener('keydown', (e) => {
  gameState.keys[e.key] = true;
  if (e.key === '1') gameState.tool = 'plow';
  if (e.key === '2') gameState.tool = 'harvest';
  if (e.key === '3') gameState.tool = 'plant';
  if (e.key === '4') gameState.currentPlant = 'corn';
  if (e.key === '5') gameState.currentPlant = 'wheat';
  if (e.key === '6') gameState.currentPlant = 'carrot';
});

document.addEventListener('keyup', (e) => {
  delete gameState.keys[e.key];
});

// Game loop
function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  gameState.plots.forEach(plot => {
    plot.update();
    plot.draw();
  });

  requestAnimationFrame(gameLoop);
}

// Initialize game
initPlots();
gameLoop();
