const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TPS = 60; // Ticks Per Second
const STEP = 1000 / TPS;

let lastTime = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let score = 0;

const enemies = [];
const towers = [];

class Enemy {
  constructor(x, y, speed) {
    this.x = x;
    this.y = y;
    this.speed = speed;
  }

  update() {
    this.x -= this.speed;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  update() {
    // Placeholder for tower logic
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

function spawnEnemy() {
  const y = Math.random() * (canvas.height - 20);
  enemies.push(new Enemy(canvas.width, y, 1));
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  if (deltaTime < STEP) {
    requestAnimationFrame(gameLoop);
    return;
  }

  lastTime = timestamp;
  const numSteps = Math.floor(deltaTime / STEP);

  for (let i = 0; i < numSteps; i++) {
    // Update game state
    enemies.forEach(enemy => enemy.update());
    enemies = enemies.filter(enemy => enemy.x > 0);

    // Collision detection
    enemies.forEach(enemy => {
      towers.forEach(tower => {
        if (Math.abs(enemy.x - tower.x) < 20 && Math.abs(enemy.y - tower.y) < 20) {
          score++;
          enemies = enemies.filter(e => e !== enemy);
        }
      });
    });

    // Spawn new enemies
    if (Math.random() < 0.02) {
      spawnEnemy();
    }
  }

  // Draw game
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  enemies.forEach(enemy => enemy.draw());
  towers.forEach(tower => tower.draw());

  // Draw score and high score
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`High Score: ${highScore}`, 10, 40);

  // Update high score
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }

  requestAnimationFrame(gameLoop);
}

// Add a tower for simplicity
towers.push(new Tower(100, 100));

requestAnimationFrame(gameLoop);
