const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const ENEMY_SPAWN_INTERVAL = 1000; // milliseconds
const MAX_ENEMIES = 10;

let lastTime = 0;
let deltaTime = 0;
let enemies = [];
let spawnTimer = ENEMY_SPAWN_INTERVAL;

class Tile {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.type = type;
    }

    draw() {
        ctx.fillStyle = this.type === 'wall' ? '#555' : '#ddd';
        ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.health = 3;
    }

    draw() {
        ctx.fillStyle = '#f00';
        ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    }

    update() {
        // Simple enemy movement logic
        if (Math.random() < 0.05) {
            this.x += Math.random() < 0.5 ? -1 : 1;
            this.y += Math.random() < 0.5 ? -1 : 1;
        }
    }
}

function generateRoom() {
    const room = [];
    for (let y = 0; y < ROOM_HEIGHT; y++) {
        for (let x = 0; x < ROOM_WIDTH; x++) {
            if (x === 0 || x === ROOM_WIDTH - 1 || y === 0 || y === ROOM_HEIGHT - 1) {
                room.push(new Tile(x, y, 'wall'));
            } else {
                room.push(new Tile(x, y, 'floor'));
            }
        }
    }
    return room;
}

function update() {
    deltaTime = (performance.now() - lastTime) / 1000;
    lastTime = performance.now();

    spawnTimer -= deltaTime * 1000;
    if (spawnTimer <= 0 && enemies.length < MAX_ENEMIES) {
        spawnEnemy();
        spawnTimer = ENEMY_SPAWN_INTERVAL;
    }

    enemies.forEach(enemy => {
        enemy.update();
    });
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    room.forEach(tile => {
        tile.draw();
    });
    enemies.forEach(enemy => {
        enemy.draw();
    });
}

function spawnEnemy() {
    const x = Math.floor(Math.random() * (ROOM_WIDTH - 2)) + 1;
    const y = Math.floor(Math.random() * (ROOM_HEIGHT - 2)) + 1;
    enemies.push(new Enemy(x, y));
}

function mainLoop(timestamp) {
    update();
    render();
    requestAnimationFrame(mainLoop);
}

const room = generateRoom();
mainLoop(performance.now());
