// Constants
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Player settings
const player = {
  health: 100,
  maxHealth: 100,
  respawnCooldown: 5, // seconds
  respawnTimer: 0,
  alive: true
};

// Enemy settings
const enemy = {
  health: 50,
  maxHealth: 50,
  speed: 2
};

// Game state
let gameOver = false;
let lastTime = performance.now();

// Draw player health bar
function drawHealthBar(x, y, width, height, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, width, height);
}

// Draw player
function drawPlayer() {
  if (player.alive) {
    ctx.fillStyle = 'blue';
    ctx.fillRect(100, 500, 50, 50);
  }
}

// Draw enemy
function drawEnemy() {
  ctx.fillStyle = 'red';
  ctx.fillRect(600, 500, 50, 50);
}

// Move enemy
function moveEnemy() {
  if (player.alive) {
    if (Math.abs(enemy.health - player.health) > 0) {
      enemy.health -= enemy.speed;
      if (enemy.health <= 0) {
        enemy.health = enemy.maxHealth;
      }
    }
  }
}

// Update player health bar
function updatePlayerHealthBar() {
  const barWidth = 200;
  const barHeight = 20;
  const barX = 50;
  const barY = 50;
  ctx.clearRect(barX, barY, barWidth, barHeight);
  const healthPercentage = player.health / player.maxHealth;
  drawHealthBar(barX, barY, healthPercentage * barWidth, barHeight, 'green');
}

// Check for game over
function checkGameOver() {
  if (player.health <= 0) {
    player.alive = false;
    player.respawnTimer = player.respawnCooldown;
  }
}

// Respawn player
function respawnPlayer() {
  if (!player.alive) {
    player.respawnTimer -= (performance.now() - lastTime) / 1000;
    if (player.respawnTimer <= 0) {
      player.health = player.maxHealth;
      player.alive = true;
    }
  }
}

// Game loop
function gameLoop(time) {
  if (gameOver) return;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  moveEnemy();
  drawPlayer();
  drawEnemy();
  updatePlayerHealthBar();
  checkGameOver();
  respawnPlayer();

  lastTime = time;
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
