      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
    }
  }
};

function update() {
  states[gameState].update();
}

function draw() {
  states[gameState].draw();
}

function gameLoop() {
