const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TPS = 60;
const MS_PER_UPDATE = 1000 / TPS;
let lastUpdate = 0;

const ENEMY_SPAWN_INTERVAL_BASE = 1000;
const ENEMY_SPAWN_INTERVAL_DECAY = 0.995;
let nextEnemySpawn = ENEMY_SPAWN_INTERVAL_BASE;

const ENEMY_SPEED_BASE = 1;
const ENEMY_SPEED_INCREASE = 0.001;

const TOWER_RADIUS = 10;
const TOWER_COST = 10;
const TOWER_DMG = 1;
let gold = 100;

const enemies = [];
const towers = [];

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.speed = ENEMY_SPEED_BASE;
  }

  update(dt) {
    this.y += this.speed * dt;
    this.speed += ENEMY_SPEED_INCREASE * dt;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 10, 10);
  }
}

class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  update(dt) {
    // Simple targeting: first enemy in range
    for (let i = 0; i < enemies.length; i++) {
      const enemy = enemies[i];
      const dx = enemy.x - this.x;
      const dy = enemy.y - this.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < TOWER_RADIUS) {
        enemy.health -= TOWER_DMG;
        if (enemy.health <= 0) {
          enemies.splice(i, 1);
          i--;
        }
        break;
      }
    }
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(this.x, this.y, TOWER_RADIUS, 0, Math.PI * 2);
    ctx.fill();
  }
}

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  enemies.push(new Enemy(x, 0));
  nextEnemySpawn *= ENEMY_SPAWN_INTERVAL_DECAY;
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  if (gold >= TOWER_COST) {
    towers.push(new Tower(x, y));
    gold -= TOWER_COST;
  }
});

function update(dt) {
  if (Date.now() - lastUpdate >= MS_PER_UPDATE) {
    lastUpdate = Date.now();
    if (Date.now() >= nextEnemySpawn) {
      spawnEnemy();
    }
    enemies.forEach(enemy => enemy.update(dt));
    towers.forEach(tower => tower.update(dt));
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  enemies.forEach(enemy => enemy.draw());
  towers.forEach(tower => tower.draw());
  ctx.fillStyle = 'black';
  ctx.fillText(`Gold: ${gold}`, 10, 20);
}

function gameLoop(timestamp) {
  const dt = timestamp - lastUpdate;
  update(dt);
  draw();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
