const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;

function resize() {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}
window.addEventListener('resize', resize);
resize();

const player = {
    x: 50,
    y: canvas.height / 2,
    width: 20,
    height: 20,
    color: 'blue',
    speed: 5,
    isJumping: false,
    velocity: 0,
    gravity: 0.5
};

const obstacles = [];
const obstacleSpeed = 5;
const obstacleWidth = 30;
const obstacleHeight = 50;
const score = {
    value: 0,
    color: 'black',
    fontSize: 20
};

let gameRunning = true;

function createObstacle() {
    const y = Math.random() * (canvas.height - obstacleHeight);
    obstacles.push({ x: canvas.width, y, width: obstacleWidth, height: obstacleHeight });
}

function updateObstacles() {
    for (let i = obstacles.length - 1; i >= 0; i--) {
        obstacles[i].x -= obstacleSpeed;
        if (obstacles[i].x + obstacles[i].width < 0) {
            obstacles.splice(i, 1);
            score.value++;
        }
    }
}

function checkCollision() {
    for (const obstacle of obstacles) {
        if (player.x < obstacle.x + obstacle.width &&
            player.x + player.width > obstacle.x &&
            player.y < obstacle.y + obstacle.height &&
            player.y + player.height > obstacle.y) {
            gameRunning = false;
        }
    }
}

function drawPlayer() {
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawObstacles() {
    ctx.fillStyle = 'red';
    for (const obstacle of obstacles) {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    }
}

function drawScore() {
    ctx.font = `${score.fontSize}px Arial`;
    ctx.fillStyle = score.color;
    ctx.fillText(`Score: ${score.value}`, 10, score.fontSize + 10);
}

function updatePlayer() {
    if (player.isJumping) {
        player.velocity += player.gravity;
        player.y += player.velocity;
        if (player.y + player.height >= canvas.height) {
            player.y = canvas.height - player.height;
            player.isJumping = false;
            player.velocity = 0;
        }
    }
}

function gameLoop() {
    if (!gameRunning) {
        ctx.fillStyle = 'black';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
        return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    updateObstacles();
    checkCollision();
    updatePlayer();

    drawPlayer();
    drawObstacles();
    drawScore();

    if (Math.random() < 0.02) {
        createObstacle();
    }

    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && !player.isJumping) {
        player.isJumping = true;
        player.velocity = -10;
    }
});

gameLoop();
