const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

let particles = [];

const tower = {
  x: canvas.width / 2,
  y: canvas.height - 100,
  radius: 20,
  color: 'blue'
};

const enemies = [];
let enemySpawnRate = 1000; // milliseconds
let lastEnemySpawn = Date.now();

const particleColors = ['#FF0000', '#00FF00', '#0000FF'];

function createParticle(x, y, color) {
  particles.push({
    x,
    y,
    radius: Math.random() * 2 + 1,
    color,
    life: 100
  });
}

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  enemies.push({
    x,
    y: 0,
    radius: 5,
    color: 'red',
    speed: Math.random() * 2 + 1
  });
}

function updateParticles() {
  particles = particles.filter(particle => particle.life > 0);
  particles.forEach(particle => {
    particle.life--;
  });
}

function drawParticles() {
  particles.forEach(particle => {
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.radius, 0, Math.PI * 2);
    ctx.fillStyle = particle.color;
    ctx.fill();
  });
}

function updateEnemies() {
  enemies.forEach(enemy => {
    enemy.y += enemy.speed;
  });
  enemies = enemies.filter(enemy => enemy.y < canvas.height);
}

function drawEnemies() {
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fillStyle = enemy.color;
    ctx.fill();
  });
}

function update() {
  if (Date.now() - lastEnemySpawn > enemySpawnRate) {
    spawnEnemy();
    lastEnemySpawn = Date.now();
  }

  updateParticles();
  updateEnemies();

  // Collision detection
  enemies.forEach((enemy, index) => {
    const distance = Math.sqrt(
      Math.pow(enemy.x - tower.x, 2) + Math.pow(enemy.y - tower.y, 2)
    );
    if (distance < tower.radius + enemy.radius) {
      // Particle burst
      for (let i = 0; i < 50; i++) {
        createParticle(tower.x, tower.y, particleColors[Math.floor(Math.random() * particleColors.length)]);
      }
      enemies.splice(index, 1);
    }
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw tower
  ctx.beginPath();
  ctx.arc(tower.x, tower.y, tower.radius, 0, Math.PI * 2);
  ctx.fillStyle = tower.color;
  ctx.fill();

  drawParticles();
  drawEnemies();
}

function animate() {
  update();
  draw();
  requestAnimationFrame(animate);
}

