// 2048-style slide game with keyboard and pointer controls
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let grid = Array.from({ length: 4 }, () => Array(4).fill(0));
let score = 0;

function setCanvasSize() {
  const scale = window.devicePixelRatio;
  canvas.width = window.innerWidth * scale;
  canvas.height = window.innerHeight * scale;
  ctx.scale(scale, scale);
}

function drawGrid() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      ctx.fillStyle = `#ccc`;
      ctx.fillRect(x * 100, y * 100, 100, 100);
      const tile = grid[y][x];
      if (tile > 0) {
        ctx.fillStyle = tile >= 2048 ? '#f0f0f0' : '#fff';
        ctx.font = 'bold 40px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(tile, x * 100 + 50, y * 100 + 50);
      }
    }
  }
}

function spawnTile() {
  const emptyCells = [];
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      if (grid[y][x] === 0) {
        emptyCells.push({ x, y });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { x, y } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    grid[y][x] = Math.random() > 0.9 ? 4 : 2;
  }
}

function move(direction) {
  let moved = false;
  const newGrid = Array.from({ length: 4 }, () => Array(4).fill(0));
  for (let y = 0; y < 4; y++) {
    const row = [];
    for (let x = 0; x < 4; x++) {
      if (direction === 'left' && grid[y][x] !== 0) row.push(grid[y][x]);
      if (direction === 'right' && grid[y][3 - x] !== 0) row.push(grid[y][3 - x]);
      if (direction === 'up' && grid[x][y] !== 0) row.push(grid[x][y]);
      if (direction === 'down' && grid[3 - x][y] !== 0) row.push(grid[3 - x][y]);
    }
    let merged = false;
    for (let i = 0; i < row.length; i++) {
      if (i > 0 && row[i] === row[i - 1] && !merged) {
        row[i - 1] *= 2;
        row[i] = 0;
        score += row[i - 1];
        merged = true;
      } else if (row[i] !== 0) {
        merged = false;
      }
    }
    const newRow = row.filter(tile => tile !== 0);
    for (let i = 0; i < newRow.length; i++) {
      if (direction === 'left') newGrid[y][i] = newRow[i];
      if (direction === 'right') newGrid[y][3 - i] = newRow[i];
      if (direction === 'up') newGrid[i][y] = newRow[i];
      if (direction === 'down') newGrid[3 - i][y] = newRow[i];
    }
  }
  if (JSON.stringify(newGrid) !== JSON.stringify(grid)) {
    grid = newGrid;
    moved = true;
  }
  return moved;
}

function gameLoop() {
  drawGrid();
  requestAnimationFrame(gameLoop);
}

function startGame() {
  setCanvasSize();
  spawnTile();
  spawnTile();
  gameLoop();
}

window.addEventListener('resize', setCanvasSize);
window.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
      if (move('left')) spawnTile();
      break;
    case 'ArrowRight':
      if (move('right')) spawnTile();
      break;
    case 'ArrowUp':
      if (move('up')) spawnTile();
      break;
    case 'ArrowDown':
      if (move('down')) spawnTile();
      break;
  }
});

let startX, startY;
canvas.addEventListener('pointerdown', (e) => {
  startX = e.clientX;
  startY = e.clientY;
});

canvas.addEventListener('pointerup', (e) => {
  const endX = e.clientX;
  const endY = e.clientY;
  const deltaX = endX - startX;
  const deltaY = endY - startY;
  if (Math.abs(deltaX) > Math.abs(deltaY)) {
    if (deltaX > 0) {
      if (move('right')) spawnTile();
    } else {
      if (move('left')) spawnTile();
    }
  } else {
    if (deltaY > 0) {
      if (move('down')) spawnTile();
    } else {
      if (move('up')) spawnTile();
    }
  }
});

startGame();
