// Rhythm Tap Game with Difficulty Ramp

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
let actualWidth = Math.floor(window.innerWidth * dpr);
let actualHeight = Math.floor(window.innerHeight * dpr);
canvas.width = actualWidth;
canvas.height = actualHeight;
ctx.scale(dpr, dpr);

let gameRunning = false;
let score = 0;
let difficulty = 1;
let enemies = [];
let spawnInterval = 2000; // milliseconds

function spawnEnemy() {
    enemies.push({
        x: Math.random() * (canvas.width - 50),
        y: 0,
        speed: 5 + Math.random() * difficulty
    });
}

function update() {
    if (!gameRunning) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Move enemies
    enemies.forEach((enemy, index) => {
        enemy.y += enemy.speed;
        ctx.fillStyle = 'red';
        ctx.fillRect(enemy.x, enemy.y, 50, 50);

        // Check for tap
        if (enemy.y + 50 > canvas.height) {
            gameRunning = false;
            alert(`Game Over! Your score: ${score}`);
        }
    });

    // Remove enemies that have been tapped
    enemies = enemies.filter(enemy => enemy.y + 50 <= canvas.height);

    // Increase difficulty
    if (score % 10 === 0 && score !== 0) {
        difficulty += 0.5;
        spawnInterval *= 0.95;
    }

    setTimeout(update, 16); // Roughly 60 FPS
}

function startGame() {
    gameRunning = true;
    score = 0;
    difficulty = 1;
    enemies = [];
    spawnInterval = 2000;
    spawnEnemy();
    update();

    setInterval(spawnEnemy, spawnInterval);
}

// Listen for taps
canvas.addEventListener('click', function(event) {
    if (!gameRunning) return;

    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    enemies = enemies.filter(enemy => {
        if (x > enemy.x && x < enemy.x + 50 && y > enemy.y && y < enemy.y + 50) {
            score++;
            return false;
        }
        return true;
    });
});

// Start the game
startGame();
