const roomHeight = 10;

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let tiles = [];
let playerPos = { x: 5, y: 5 };

function init() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

  tiles = Array.from({ length: roomHeight }, () =>
    Array.from({ length: roomWidth }, () => 0)
  );

  requestAnimationFrame(gameLoop);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  switch (currentState) {
    case states.MENU:
      renderMenu();
      break;
    case states.PLAYING:
      renderGame();
      updateGame();
      break;
    case states.PAUSED:
      renderPaused();
      break;
    case states.GAMEOVER:
      renderGameOver();
      break;
  }

  requestAnimationFrame(gameLoop);
}

function renderMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Menu', canvas.width / 2, canvas.height / 2);
}

function renderGame() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  tiles.forEach((row, y) => {
    row.forEach((tile, x) => {
      ctx.fillStyle = tile ? 'blue' : 'gray';
      ctx.fillRect(x * tileWidth, y * tileHeight, tileWidth, tileHeight);
    });
  });

  ctx.fillStyle = 'red';
  ctx.fillRect(
    playerPos.x * tileWidth,
    playerPos.y * tileHeight,
    tileWidth,
    tileHeight
  );
}

function updateGame() {
  // Simple player movement
  if (keys.ArrowUp && playerPos.y > 0) playerPos.y--;
  if (keys.ArrowDown && playerPos.y < roomHeight - 1) playerPos.y++;
  if (keys.ArrowLeft && playerPos.x > 0) playerPos.x--;
  if (keys.ArrowRight && playerPos.x < roomWidth - 1) playerPos.x++;
}

function renderPaused() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function renderGameOver() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
}

const keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.key] = true;

  switch (e.key) {
    case 'Escape':
      currentState = states.MENU;
      break;
    case 'p':
      currentState = currentState === states.PLAYING ? states.PAUSED : states.PLAYING;
      break;
  }
});

window.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

window.addEventListener('resize', init);

