```js
const canvas = document.createElement('canvas');
canvas.width = 300;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const COLUMN_COUNT = 10;
const ROW_COUNT = 20;
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF', '#FFFFFF'];

let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let gameOver = false;
let currentBlock;
let grid = Array.from({ length: ROW_COUNT }, () => Array(COLUMN_COUNT).fill(0));

function drawBlock(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(x, y, BLOCK_SIZE, BLOCK_SIZE);
}

function drawGrid() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let row = 0; row < ROW_COUNT; row++) {
        for (let col = 0; col < COLUMN_COUNT; col++) {
            if (grid[row][col]) {
                drawBlock(col * BLOCK_SIZE, row * BLOCK_SIZE, COLORS[grid[row][col] - 1]);
            }
        }
    }
    currentBlock.draw();
}

function createBlock() {
    const types = [
        { shape: [[1, 1], [1, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 1 },
        { shape: [[1, 1, 1, 1]], x: COLUMN_COUNT / 2 - 2, y: 0, color: 2 },
        { shape: [[0, 1, 0], [1, 1, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 3 },
        { shape: [[1, 0, 0], [1, 1, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 4 },
        { shape: [[0, 0, 1], [1, 1, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 5 },
        { shape: [[1, 1, 0], [0, 1, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 6 },
        { shape: [[1, 1], [0, 1], [0, 1]], x: COLUMN_COUNT / 2 - 1, y: 0, color: 7 }
    ];
    return new Block(types[Math.floor(Math.random() * types.length)]);
}

class Block {
    constructor({ shape, x, y, color }) {
        this.shape = shape;
        this.x = x;
        this.y = y;
        this.color = color;
    }

    draw() {
        this.shape.forEach((row, i) => {
            row.forEach((cell, j) => {
                if (cell) {
                    drawBlock((this.x + j) * BLOCK_SIZE, (this.y + i) * BLOCK_SIZE, COLORS[this.color - 1]);
                }
            });
        });
    }

    move(dx, dy) {
        if (!this.collision(dx, dy)) {
            this.x += dx;
            this.y += dy;
        }
    }

    rotate() {
        const newShape = this.shape[0].map((_, index) => this.shape.map(row => row[index]).reverse());
        if (!this.collision(0, 0, newShape)) {
            this.shape = newShape;
        }
    }

    collision(dx = 0, dy = 0, newShape = this.shape) {
        return newShape.some((row, i) => {
            return row.some((cell, j) => {
                if (cell) {
                    const newX = this.x + j + dx;
                    const newY = this.y + i + dy;
                    return newX < 0 || newX >= COLUMN_COUNT || newY >= ROW_COUNT || (newY >= 0 && grid[newY][newX]);
                }
                return false;
            });
        });
    }

    lock() {
        this.shape.forEach((row, i) => {
            row.forEach((cell, j) => {
                if (cell) {
                    grid[this.y + i][this.x + j] = this.color;
                }
            });
        });
        this.clearLines();
        currentBlock = createBlock();
    }

    clearLines() {
        let linesCleared = 0;
        for (let row = ROW_COUNT - 1; row >= 0; row--) {
            if (grid[row].every(cell => cell)) {
                linesCleared++;
                grid.splice(row, 1);
                grid.unshift(Array(COLUMN_COUNT).fill(0));
            }
        }
        score += linesCleared * 100;
        if (score > highScore) {
            highScore = score;
            localStorage.setItem('highScore', highScore);
        }
    }
}

function gameLoop() {
    if (gameOver) return;
    ctx.font = '20px Arial';
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`High Score: ${highScore}`, 10, 40);

    currentBlock.move(0, 1);
    if (currentBlock.collision(0, 1)) {
        currentBlock.lock();
        if (currentBlock.collision(0, 0)) {
            gameOver = true;
        }
    }

    drawGrid();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (gameOver) return;
    switch (e.key) {
        case 'ArrowLeft': currentBlock.move(-1, 0); break;
        case 'ArrowRight': currentBlock.move(1, 0); break;
        case 'ArrowDown': currentBlock.move(0, 1); break;
        case 'ArrowUp': currentBlock.rotate(); break;
    }
});

currentBlock = createBlock();
gameLoop();
