const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let gameRunning = false;
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let player = { x: canvas.width / 2, y: canvas.height / 2, r: 10, angle: Math.PI / 2, speed: 5 };
let bullets = [];
let asteroids = [];
let asteroidSpeed = 2;
let asteroidCount = 5;
let keys = {};

function resizeCanvas() {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

window.addEventListener('keydown', (e) => { keys[e.key] = true; });
window.addEventListener('keyup', (e) => { keys[e.key] = false; });

function createAsteroid() {
  let r = Math.floor(Math.random() * 50) + 20;
  let x = Math.random() * (canvas.width - r * 2) + r;
  let y = Math.random() * (canvas.height - r * 2) + r;
  asteroids.push({ x, y, r, angle: Math.random() * Math.PI * 2, speed: asteroidSpeed });
}

function spawnAsteroids() {
  for (let i = 0; i < asteroidCount; i++) {
    createAsteroid();
  }
}

function updatePlayer() {
  if (keys['ArrowLeft']) player.angle -= 0.05;
  if (keys['ArrowRight']) player.angle += 0.05;
  if (keys['ArrowUp']) {
    player.x += Math.cos(player.angle) * player.speed;
    player.y -= Math.sin(player.angle) * player.speed;
  }
  if (keys['ArrowDown']) {
    player.x -= Math.cos(player.angle) * player.speed;
    player.y += Math.sin(player.angle) * player.speed;
  }
  player.x = (player.x + canvas.width) % canvas.width;
  player.y = (player.y + canvas.height) % canvas.height;
}

function updateBullets() {
  bullets.forEach(bullet => {
    bullet.x += Math.cos(bullet.angle) * 5;
    bullet.y -= Math.sin(bullet.angle) * 5;
    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets = bullets.filter(b => b !== bullet);
    }
  });
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += Math.cos(asteroid.angle) * asteroid.speed;
    asteroid.y -= Math.sin(asteroid.angle) * asteroid.speed;
    asteroid.x = (asteroid.x + canvas.width) % canvas.width;
    asteroid.y = (asteroid.y + canvas.height) % canvas.height;
  });
}

function checkCollisions() {
  bullets.forEach(bullet => {
    asteroids.forEach(asteroid => {
      let dx = bullet.x - asteroid.x;
      let dy = bullet.y - asteroid.y;
      let distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < asteroid.r) {
        asteroids = asteroids.filter(a => a !== asteroid);
        bullets = bullets.filter(b => b !== bullet);
        score += 10;
      }
    });
  });

  asteroids.forEach(asteroid => {
    let dx = player.x - asteroid.x;
    let dy = player.y - asteroid.y;
    let distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < asteroid.r + player.r) {
      gameRunning = false;
    }
  });
}

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.angle);
  ctx.beginPath();
  ctx.moveTo(0, -player.r);
  ctx.lineTo(-player.r / 2, player.r / 2);
  ctx.lineTo(player.r / 2, player.r / 2);
  ctx.closePath();
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.restore();
}

function drawBullets() {
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = 'white';
    ctx.fill();
  });
}

function drawAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.r, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
  });
}

function drawScore() {
  ctx.font = '20px Arial';
  ctx.fillStyle = 'white';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function gameLoop() {
  if (!gameRunning) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updatePlayer();
  updateBullets();
  updateAsteroids();
  checkCollisions();
  drawPlayer();
  drawBullets();
  drawAsteroids();
  drawScore();
  requestAnimationFrame(gameLoop);
}

function startGame() {
  gameRunning = true;
  score = 0;
  bullets = [];
  asteroids = [];
  spawnAsteroids();
  gameLoop();
}

function endGame() {
  gameRunning = false;
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
}

window.addEventListener('click', () => {
  if (!gameRunning) {
    startGame();
  } else {
    bullets.push({ x: player.x, y: player.y, angle: player.angle });
  }
});

window.addEventListener('keypress', (e) => {
  if (e.code === 'Space') {
    if (!gameRunning) {
      startGame();
    } else {
      bullets.push({ x: player.x, y: player.y, angle: player.angle });
    }
  }
});

window.addEventListener('gameover', endGame);

startGame();
