const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tile = 20;
const speed = 150; // pixels per second
const gridWidth = canvas.width / tile;
const gridHeight = canvas.height / tile;

let snake = [{ x: gridWidth / 2, y: gridHeight / 2 }];
let direction = { x: 0, y: 0 };
let food = { x: 0, y: 0 };
let particles = [];
let score = 0;
let lastTime = 0;

function getRandomFood() {
  return {
    x: Math.floor(Math.random() * gridWidth),
    y: Math.floor(Math.random() * gridHeight),
  };
}

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * tile, y * tile, tile, tile);
}

function drawCircle(x, y, radius, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(x * tile + tile / 2, y * tile + tile / 2, radius, 0, Math.PI * 2);
  ctx.fill();
}

function updateSnake() {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    food = getRandomFood();
    particles = particles.concat(snake.map(segment => ({ ...segment, age: 0 })));
  } else {
    snake.pop();
  }

  if (head.x < 0 || head.x >= gridWidth || head.y < 0 || head.y >= gridHeight || snake.slice(1).some(segment => segment.x === head.x && segment.y === head.y)) {
    resetGame();
  }
}

function resetGame() {
  snake = [{ x: gridWidth / 2, y: gridHeight / 2 }];
  direction = { x: 0, y: 0 };
  food = getRandomFood();
  particles = [];
  score = 0;
}

function updateParticles() {
  particles.forEach(particle => particle.age++);
  particles = particles.filter(particle => particle.age < 30);
}

function drawParticles() {
  particles.forEach(particle => drawCircle(particle.x, particle.y, (30 - particle.age) * 0.5, `rgba(255, 255, 255, ${1 - particle.age / 30})`));
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
  drawRect(food.x, food.y, 'red');
  drawParticles();
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function update(deltaTime) {
  updateSnake();
  updateParticles();
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;
  update(deltaTime);
  draw();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
  }
});

resetGame();
requestAnimationFrame(gameLoop);
