const ctx = canvas.getContext('2d');

const gridSize = 4;
const tileWidth = canvas.width / gridSize;
const tileHeight = canvas.height / gridSize;
let board = Array(gridSize).fill().map(() => Array(gridSize).fill(0));
let combo = 0;
let score = 0;

function getRandomTileValue() {
    return Math.random() > 0.9 ? 4 : 2;
}

function addRandomTile() {
    const emptyTiles = [];
    for (let i = 0; i < gridSize; i++) {
        for (let j = 0; j < gridSize; j++) {
            if (board[i][j] === 0) {
                emptyTiles.push({ x: i, y: j });
            }
        }
    }
    if (emptyTiles.length > 0) {
        const randomTile = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        board[randomTile.x][randomTile.y] = getRandomTileValue();
    }
}

function slideAndMerge(row) {
    let newRow = row.filter(num => num !== 0);
    for (let i = 0; i < newRow.length - 1; i++) {
        if (newRow[i] === newRow[i + 1]) {
            newRow[i] *= 2;
            newRow[i + 1] = 0;
            score += newRow[i];
            combo++;
        }
    }
    newRow = newRow.filter(num => num !== 0);
    while (newRow.length < gridSize) {
        newRow.push(0);
    }
    return newRow;
}

function slideUp() {
    for (let col = 0; col < gridSize; col++) {
        let column = [];
        for (let row = 0; row < gridSize; row++) {
            column.push(board[row][col]);
        }
        column = slideAndMerge(column);
        for (let row = 0; row < gridSize; row++) {
            board[row][col] = column[row];
        }
    }
}

function slideDown() {
    for (let col = 0; col < gridSize; col++) {
        let column = [];
        for (let row = 0; row < gridSize; row++) {
            column.push(board[row][col]);
        }
        column = slideAndMerge(column.reverse());
        column.reverse();
        for (let row = 0; row < gridSize; row++) {
            board[row][col] = column[row];
        }
    }
}

function slideLeft() {
    for (let row = 0; row < gridSize; row++) {
        board[row] = slideAndMerge(board[row]);
    }
}

function slideRight() {
    for (let row = 0; row < gridSize; row++) {
        board[row] = slideAndMerge(board[row].reverse());
        board[row].reverse();
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < gridSize; i++) {
        for (let j = 0; j < gridSize; j++) {
            const value = board[i][j];
            ctx.fillStyle = '#ccc';
            ctx.fillRect(j * tileWidth, i * tileHeight, tileWidth, tileHeight);
            if (value !== 0) {
                ctx.fillStyle = value === 2 ? '#eee' : '#000';
                ctx.font = '30px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(value.toString(), j * tileWidth + tileWidth / 2, i * tileHeight + tileHeight / 2);
            }
        }
    }
    ctx.fillStyle = '#000';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Combo: ${combo}`, 10, 60);
}

function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (event) => {
    switch (event.key) {
        case 'ArrowUp':
            slideUp();
            break;
        case 'ArrowDown':
            slideDown();
            break;
        case 'ArrowLeft':
            slideLeft();
            break;
        case 'ArrowRight':
            slideRight();
            break;
    }
    addRandomTile();
    combo = 0;
});

function startGame() {
    addRandomTile();
    addRandomTile();
    gameLoop();
}

startGame();
