  y: canvas.height / 2,
  radius: 10,
  angle: Math.PI / 2,
  speed: 5,
  dx: 0,
  dy: 0,
  maxSpeed: 10,
  friction: 0.9,
  accelerating: false,
  rotatingLeft: false,
  rotatingRight: false,
  fireCooldown: 0,
  firepower: 1,
  shoot: function() {
    if (this.fireCooldown <= 0) {
      bullets.push({
        x: this.x,
        y: this.y,
        angle: this.angle,
        speed: this.speed * 2,
        radius: 3
      });
      this.fireCooldown = 30;
    }
  }
};

const asteroids = [];
const bullets = [];
const powerUps = [];

function spawnAsteroid() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  const radius = Math.random() * (20 - 10) + 10;
  const speed = Math.random() * (3 - 1) + 1;
  const angle = Math.random() * Math.PI * 2;
  asteroids.push({ x, y, radius, speed, angle });
}

function spawnPowerUp() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  powerUps.push({ x, y, radius: 5, type: Math.random() > 0.5 ? 'speed' : 'firepower' });
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (ship.accelerating) {
    ship.dx += Math.cos(ship.angle) * ship.speed;
    ship.dy += Math.sin(ship.angle) * ship.speed;
  }

  if (ship.rotatingLeft) {
    ship.angle -= 0.05;
  }
  if (ship.rotatingRight) {
    ship.angle += 0.05;
  }

  ship.dx *= ship.friction;
  ship.dy *= ship.friction;
  ship.x += ship.dx;
  ship.y += ship.dy;

  if (ship.x < 0) ship.x = canvas.width;
  if (ship.x > canvas.width) ship.x = 0;
  if (ship.y < 0) ship.y = canvas.height;
  if (ship.y > canvas.height) ship.y = 0;

  if (ship.fireCooldown > 0) ship.fireCooldown--;

  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(ship.x, ship.y, ship.radius, 0, Math.PI * 2);
  ctx.fill();

  bullets.forEach((bullet, i) => {
    bullet.x += Math.cos(bullet.angle) * bullet.speed;
    bullet.y += Math.sin(bullet.angle) * bullet.speed;

    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
    ctx.fill();

    if (bullet.x < 0 || bullet.x > canvas.width || bullet.y < 0 || bullet.y > canvas.height) {
      bullets.splice(i, 1);
    }
  });

  asteroids.forEach((asteroid, i) => {
    asteroid.x += Math.cos(asteroid.angle) * asteroid.speed;
    asteroid.y += Math.sin(asteroid.angle) * asteroid.speed;

    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;

    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.fill();

    bullets.forEach((bullet, bi) => {
      const dx = asteroid.x - bullet.x;
      const dy = asteroid.y - bullet.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < asteroid.radius + bullet.radius) {
        bullets.splice(bi, 1);
        asteroids.splice(i, 1);
        spawnAsteroid();
      }
    });

    const dx = asteroid.x - ship.x;
    const dy = asteroid.y - ship.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < asteroid.radius + ship.radius) {
      // Game over
      alert('Game Over!');
      document.location.reload();
    }
  });

  powerUps.forEach((powerUp, i) => {
    ctx.fillStyle = powerUp.type === 'speed' ? 'blue' : 'red';
    ctx.beginPath();
    ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
    ctx.fill();

    const dx = powerUp.x - ship.x;
    const dy = powerUp.y - ship.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance < powerUp.radius + ship.radius) {
      powerUps.splice(i, 1);
      if (powerUp.type === 'speed') {
        ship.maxSpeed += 2;
      } else if (powerUp.type === 'firepower') {
        ship.firepower++;
      }
    }
  });

  if (Math.random() < 0.01) spawnAsteroid();
  if (Math.random() < 0.005) spawnPowerUp();

  requestAnimationFrame(update);
}

document.addEventListener('keydown', (e) => {
  if (e.code === 'ArrowUp') ship.accelerating = true;
  if (e.code === 'ArrowLeft') ship.rotatingLeft = true;
  if (e.code === 'ArrowRight') ship.rotatingRight = true;
