const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const gravity = 0.981;
const drag = 0.99;
const bounce = -0.7;
const ballRadius = 20;
let ball = { x: canvas.width / 2, y: canvas.height / 2, vx: 0, vy: 0 };
let lastTime = performance.now();
const fixedTimestep = 1 / 60; // 60 FPS

function update(dt) {
  ball.vx *= drag;
  ball.vy *= drag;
  ball.vy += gravity * dt;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  if (ball.x - ballRadius < 0 || ball.x + ballRadius > canvas.width) {
    ball.vx *= bounce;
    ball.x = ball.x < ballRadius ? ballRadius : canvas.width - ballRadius;
  }

  if (ball.y - ballRadius < 0 || ball.y + ballRadius > canvas.height) {
    ball.vy *= bounce;
    ball.y = ball.y < ballRadius ? ballRadius : canvas.height - ballRadius;
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ballRadius, 0, Math.PI * 2);
  ctx.fillStyle = 'red';
  ctx.fill();
  ctx.closePath();
}

function mainLoop() {
  const now = performance.now();
  let dt = (now - lastTime) / 1000;
  lastTime = now;

  // Clamp dt to a maximum value to prevent large time steps
  dt = Math.min(dt, 0.1);

  // Fixed time step update
  let accumulator = 0;
  accumulator += dt;

  while (accumulator >= fixedTimestep) {
    update(fixedTimestep);
    accumulator -= fixedTimestep;
  }

  render();
  requestAnimationFrame(mainLoop);
}

mainLoop();

// Keyboard controls
document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
