canvas.height = 400;

let board = Array.from({length: 4}, () => Array(4).fill(0));
let score = 0;
let enemyInterval = 2000;
let lastEnemySpawn = 0;
let gameOver = false;

function spawnEnemy() {
  if (gameOver) return;
  const emptyCells = [];
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      if (board[i][j] === 0) {
        emptyCells.push({i, j});
      }
    }
  }
  if (emptyCells.length > 0) {
    const {i, j} = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    board[i][j] = Math.random() > 0.9 ? 4 : 2;
  }
}

function updateDifficulty() {
  if (score >= 2048) {
    enemyInterval = 1500;
  } else if (score >= 1024) {
    enemyInterval = 1800;
  } else if (score >= 512) {
    enemyInterval = 2000;
  } else if (score >= 256) {
    enemyInterval = 2200;
  }
}

function merge(row) {
  for (let i = 3; i > 0; i--) {
    if (row[i] === row[i - 1]) {
      row[i] += row[i - 1];
      row[i - 1] = 0;
      score += row[i];
    }
  }
  return row.filter(n => n).concat(Array(4 - row.filter(n => n).length).fill(0));
}

function moveLeft() {
  board = board.map(merge);
}

function moveRight() {
  board = board.map(row => merge(row.reverse()).reverse());
}

function moveUp() {
  board = transpose(board.map(merge));
}

function moveDown() {
  board = transpose(board.map(row => merge(row.reverse()).reverse()));
}

function transpose(matrix) {
  return matrix[0].map((_, colIndex) => matrix.map(row => row[colIndex]));
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      ctx.fillStyle = board[i][j] === 0 ? '#ccc' : `hsl(${board[i][j] * 10}, 100%, 50%)`;
      ctx.fillRect(j * 100, i * 100, 100, 100);
      if (board[i][j] !== 0) {
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(board[i][j], j * 100 + 50, i * 100 + 50);
      }
    }
  }
  ctx.fillStyle = '#000';
  ctx.font = 'bold 20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function gameLoop(timestamp) {
  if (gameOver) return;
  if (timestamp - lastEnemySpawn >= enemyInterval) {
    spawnEnemy();
    lastEnemySpawn = timestamp;
    updateDifficulty();
  }
  render();
  requestAnimationFrame(gameLoop);
}

spawnEnemy();
requestAnimationFrame(gameLoop);

document.addEventListener('keydown', (e) => {
