// Initialize canvas and context
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Constants
const FIXED_TIMESTEP = 1 / 60; // 60 FPS
const GRAVITY = 9.8;
const FISH_SPEED = 5;
const BAIT_SIZE = 10;

// Game state
let lastTime = 0;
let fish = { x: canvas.width / 2, y: canvas.height / 2, vy: 0 };
let bait = { x: canvas.width / 2, y: canvas.height - 50 };
let score = 0;
let gameOver = false;

// Main loop
function gameLoop(timestamp) {
    if (gameOver) return;

    const deltaTime = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Fixed timestep integration
    let steps = 0;
    while (deltaTime >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        steps++;
        deltaTime -= FIXED_TIMESTEP;
    }

    render();
    requestAnimationFrame(gameLoop);
}

// Update game state
function update(dt) {
    // Move fish
    fish.vy += GRAVITY * dt;
    fish.y += fish.vy * dt;

    // Check for fish catching bait
    if (Math.abs(fish.x - bait.x) < BAIT_SIZE && Math.abs(fish.y - bait.y) < BAIT_SIZE) {
        score++;
        resetBait();
    }

    // Reset fish position if it goes out of bounds
    if (fish.y > canvas.height || fish.x < 0 || fish.x > canvas.width) {
        resetFish();
    }
}

// Render game state
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw fish
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(fish.x, fish.y, 10, 0, Math.PI * 2);
    ctx.fill();

    // Draw bait
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(bait.x, bait.y, BAIT_SIZE, 0, Math.PI * 2);
    ctx.fill();

    // Draw score
    ctx.font = '20px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText('Score: ' + score, 10, 30);

    // Draw game over if necessary
    if (gameOver) {
        ctx.font = '40px Arial';
        ctx.fillStyle = 'red';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over!', canvas.width / 2, canvas.height / 2);
    }
}

// Reset fish position
function resetFish() {
    fish.x = canvas.width / 2;
    fish.y = canvas.height / 2;
    fish.vy = 0;
}

// Reset bait position
function resetBait() {
    bait.x = Math.random() * canvas.width;
    bait.y = canvas.height - 50;
}

// Game over condition
function checkGameOver() {
    if (score >= 10) {
        gameOver = true;
    }
}

// Event listeners for mouse movement
canvas.addEventListener('mousemove', (e) => {
    if (!gameOver) {
        fish.x = e.clientX - canvas.offsetLeft;
    }
});

// Start the game loop
requestAnimationFrame(gameLoop);
