const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;
let board = [];
let flipped = [];
let matches = 0;
let timer;
let seconds = 60;

function init() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
  board = createBoard();
  shuffleBoard();
  drawBoard();
  startTimer();
}

function createBoard() {
  const icons = ['🐶', '🐱', '🐭', '🐹', '🐰', '🦊', '🐻', '🐼'];
  return icons.concat(icons).map(icon => ({ icon, revealed: false }));
}

function shuffleBoard() {
  for (let i = board.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [board[i], board[j]] = [board[j], board[i]];
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const cardWidth = canvas.width / 8;
  const cardHeight = canvas.height / 8;
  board.forEach((card, index) => {
    const x = (index % 8) * cardWidth;
    const y = Math.floor(index / 8) * cardHeight;
    if (card.revealed || flipped.includes(index)) {
      ctx.font = '48px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(card.icon, x + cardWidth / 2, y + cardHeight / 2);
    } else {
      ctx.fillStyle = '#ccc';
      ctx.fillRect(x, y, cardWidth, cardHeight);
    }
  });
}

function flipCard(index) {
  if (flipped.length >= 2 || board[index].revealed) return;
  board[index].revealed = true;
  flipped.push(index);
  drawBoard();
  if (flipped.length === 2) {
    setTimeout(checkForMatch, 500);
  }
}

function checkForMatch() {
  const [index1, index2] = flipped;
  if (board[index1].icon === board[index2].icon) {
    matches++;
    if (matches === board.length / 2) {
      alert('Congratulations! You won!');
      resetGame();
    }
  } else {
    board[index1].revealed = false;
    board[index2].revealed = false;
  }
  flipped = [];
  drawBoard();
}

function startTimer() {
  timer = setInterval(() => {
    seconds--;
    if (seconds <= 0) {
      clearInterval(timer);
      alert('Time\'s up! You lost.');
      resetGame();
    }
    drawTimer();
  }, 1000);
}

function drawTimer() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#000';
  ctx.fillText(`Time: ${seconds}s`, 10, 30);
}

function resetGame() {
  clearInterval(timer);
  board.forEach(card => card.revealed = false);
  matches = 0;
  seconds = 60;
  shuffleBoard();
  drawBoard();
  startTimer();
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  const cardWidth = canvas.width / 8;
  const cardHeight = canvas.height / 8;
  const index = Math.floor(y / cardHeight) * 8 + Math.floor(x / cardWidth);
  flipCard(index);
});

window.addEventListener('resize', init);
init();
