const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let lastTime = 0;
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let isRunning = false;
let player = { x: 50, y: 100, width: 20, height: 20, speed: 5 };
let obstacles = [];

function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
}

function startGame() {
    isRunning = true;
    score = 0;
    obstacles = [];
    requestAnimationFrame(gameLoop);
}

function gameLoop(timestamp) {
    if (!isRunning) return;
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    update(deltaTime);
    render();

    requestAnimationFrame(gameLoop);
}

function update(deltaTime) {
    player.y += player.speed;

    if (player.y + player.height > canvas.height) {
        player.y = canvas.height - player.height;
    }

    if (Math.random() < 0.02) {
        obstacles.push({ x: canvas.width, y: Math.random() * (canvas.height - 50), width: 30, height: 50, speed: 5 });
    }

    for (let i = 0; i < obstacles.length; i++) {
        obstacles[i].x -= obstacles[i].speed;
        if (obstacles[i].x + obstacles[i].width < 0) {
            obstacles.splice(i, 1);
            score++;
        }
        if (isColliding(player, obstacles[i])) {
            isRunning = false;
            if (score > highScore) {
                highScore = score;
                localStorage.setItem('highScore', highScore);
            }
            alert(`Game Over! Your score: ${score}. High Score: ${highScore}`);
        }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    });

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function isColliding(a, b) {
    return !(a.x > b.x + b.width || a.x + a.width < b.x || a.y > b.y + b.height || a.y + a.height < b.y);
}

function handleKeyDown(event) {
    if (event.code === 'Space' && !isRunning) {
        startGame();
    }
}

window.addEventListener('keydown', handleKeyDown);
resizeCanvas();
window.addEventListener('resize', resizeCanvas);
