const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

class Entity {
  constructor(x, y, radius, color) {
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.color = color;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
    ctx.closePath();
  }
}

class Asteroid extends Entity {
  constructor(x, y, radius, color, velocity) {
    super(x, y, radius, color);
    this.velocity = velocity;
  }

  update() {
    this.x += this.velocity.x;
    this.y += this.velocity.y;
    if (this.x < -this.radius || this.x > canvas.width + this.radius ||
        this.y < -this.radius || this.y > canvas.height + this.radius) {
      this.respawn();
    }
  }

  respawn() {
    this.x = Math.random() * canvas.width;
    this.y = Math.random() * canvas.height;
  }
}

class Player extends Entity {
  constructor(x, y, radius, color, speed) {
    super(x, y, radius, color);
    this.speed = speed;
    this.keys = { ArrowUp: false, ArrowDown: false, ArrowLeft: false, ArrowRight: false };
  }

  update() {
    if (this.keys.ArrowUp) this.y -= this.speed;
    if (this.keys.ArrowDown) this.y += this.speed;
    if (this.keys.ArrowLeft) this.x -= this.speed;
    if (this.keys.ArrowRight) this.x += this.speed;

    if (this.x < 0) this.x = 0;
    if (this.x > canvas.width) this.x = canvas.width;
    if (this.y < 0) this.y = 0;
    if (this.y > canvas.height) this.y = canvas.height;
  }
}

const player = new Player(canvas.width / 2, canvas.height / 2, 10, 'blue', 5);
const asteroids = [];

for (let i = 0; i < 10; i++) {
  const radius = Math.random() * 20 + 10;
  const x = Math.random() * (canvas.width - radius * 2) + radius;
  const y = Math.random() * (canvas.height - radius * 2) + radius;
  const velocity = {
    x: (Math.random() - 0.5) * 3,
    y: (Math.random() - 0.5) * 3
  };
  asteroids.push(new Asteroid(x, y, radius, 'gray', velocity));
}

let combo = 0;
let score = 0;
let highScore = 0;

function handleCollision(asteroid) {
  const dx = player.x - asteroid.x;
  const dy = player.y - asteroid.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  if (distance < player.radius + asteroid.radius) {
    combo = 0;
    score = 0;
    asteroid.respawn();
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player.update();
  player.draw();

  for (let asteroid of asteroids) {
    asteroid.update();
    asteroid.draw();
    handleCollision(asteroid);
  }

  combo++;
  score += combo;
  highScore = Math.max(highScore, score);

  ctx.font = '20px Arial';
  ctx.fillStyle = 'white';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
  ctx.fillText(`Combo: ${combo}`, 10, 90);

