// Snake Game on HTML5 Canvas with Health Bar and Respawn

const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const scale = 20;
const rows = canvas.height / scale;
const columns = canvas.width / scale;

let snake;
let food;
let health;
let gameRunning = true;
let lastTime = 0;
const fixedTimeStep = 1000 / 10; // 10 frames per second

function Snake() {
  this.x = 0;
  this.y = 0;
  this.xSpeed = scale * 1;
  this.ySpeed = 0;
  this.total = 0;
  this.tail = [];
  this.health = 5;

  this.draw = function() {
    ctx.fillStyle = '#00FF00';
    for (let i = 0; i < this.tail.length; i++) {
      ctx.fillRect(this.tail[i].x, this.tail[i].y, scale, scale);
    }
    ctx.fillRect(this.x, this.y, scale, scale);
  };

  this.update = function() {
    for (let i = 0; i < this.tail.length - 1; i++) {
      this.tail[i] = this.tail[i + 1];
    }
    this.tail[this.total - 1] = { x: this.x, y: this.y };

    this.x += this.xSpeed;
    this.y += this.ySpeed;

    if (this.x > canvas.width - scale) this.x = 0;
    if (this.y > canvas.height - scale) this.y = 0;
    if (this.x < 0) this.x = canvas.width - scale;
    if (this.y < 0) this.y = canvas.height - scale;
  };

  this.changeDirection = function(direction) {
    switch (direction) {
      case 'Up':
        if (this.ySpeed === 0) {
          this.xSpeed = 0;
          this.ySpeed = -scale * 1;
        }
        break;
      case 'Down':
        if (this.ySpeed === 0) {
          this.xSpeed = 0;
          this.ySpeed = scale * 1;
        }
        break;
      case 'Left':
        if (this.xSpeed === 0) {
          this.xSpeed = -scale * 1;
          this.ySpeed = 0;
        }
        break;
      case 'Right':
        if (this.xSpeed === 0) {
          this.xSpeed = scale * 1;
          this.ySpeed = 0;
        }
        break;
    }
  };

  this.checkCollision = function() {
    for (let i = 0; i < this.tail.length; i++) {
      if (this.x === this.tail[i].x && this.y === this.tail[i].y) {
        this.total = 0;
        this.tail = [];
        this.health--;
        if (this.health <= 0) {
          this.health = 5;
          gameRunning = false;
          setTimeout(() => {
            gameRunning = true;
            this.x = 0;
            this.y = 0;
            this.xSpeed = scale * 1;
            this.ySpeed = 0;
          }, 1000);
        }
      }
    }
  };

  this.eat = function() {
    if (this.x === food.x && this.y === food.y) {
      this.total++;
      food = new Food();
    }
  };
}

function Food() {
  this.x = (Math.floor(Math.random() * columns) + 1) * scale;
  this.y = (Math.floor(Math.random() * rows) + 1) * scale;

  this.draw = function() {
    ctx.fillStyle = '#FF0000';
    ctx.fillRect(this.x, this.y, scale, scale);
  };
}

function drawHealthBar() {
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, canvas.height - 20, canvas.width, 20);
  ctx.fillStyle = '#FF0000';
  ctx.fillRect(0, canvas.height - 20, (canvas.width / 5) * snake.health, 20);
}

function update() {
  if (!gameRunning) return;

  snake.update();
  snake.eat();
  snake.checkCollision();
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  snake.draw();
  food.draw();
  drawHealthBar();
}

function gameLoop(currentTime) {
  let deltaTime = currentTime - lastTime;
  if (deltaTime >= fixedTimeStep) {
    lastTime = currentTime - (deltaTime % fixedTimeStep);
    update();
    draw();
  }
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', function(e) {
  const key = e.code;
  switch (key) {
    case 'ArrowUp':
      snake.changeDirection('Up');
      break;
    case 'ArrowDown':
      snake.changeDirection('Down');
      break;
    case 'ArrowLeft':
      snake.changeDirection('Left');
      break;
    case 'ArrowRight':
      snake.changeDirection('Right');
      break;
  }
});

snake = new Snake();
food = new Food();
requestAnimationFrame(gameLoop);
