  obstacles.forEach(obstacle => {
    ctx.fillRect(obstacle.x, 0, playerSize, obstacle.gapTop);
    ctx.fillRect(obstacle.x, obstacle.gapTop + gapSize, playerSize, canvas.height);
  });
}

function drawGameOver() {
