  const delta = timestamp - lastTimestamp;
  playerVelocity += gravity;
  playerY += playerVelocity * (delta / fixedTimestep);

  if (playerY + playerSize > canvas.height || playerY < 0) {
    playerHealth--;
    if (playerHealth <= 0) {
      gameRunning = false;
    } else {
      respawnPlayer();
    }
  }
}

