    obstacle.x -= obstacleSpeed * (timestamp - lastTimestamp) / fixedTimestep;
  });

  if (obstacles.length === 0 || obstacles[obstacles.length - 1].x < canvas.width - 200) {
    const gapTop = gapMin + Math.random() * (gapMax - gapMin);
    obstacles.push({ x: canvas.width, gapTop });
  }

  obstacles = obstacles.filter(obstacle => obstacle.x + playerSize > 0);

  if (obstacles.some(obstacle => 
      playerX < obstacle.x + playerSize &&
      playerX + playerSize > obstacle.x &&
      (playerY < obstacle.gapTop || playerY + playerSize > obstacle.gapTop + gapSize)
