const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

const pixelRatio = window.devicePixelRatio || 1;
let gridSize = 20;
let gridWidth = Math.floor(window.innerWidth / gridSize);
let gridHeight = Math.floor(window.innerHeight / gridSize);

canvas.width = gridWidth * gridSize * pixelRatio;
canvas.height = gridHeight * gridSize * pixelRatio;
ctx.scale(pixelRatio, pixelRatio);

let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: Math.floor(Math.random() * gridWidth), y: Math.floor(Math.random() * gridHeight) };
let score = 0;
let combo = 1;
let gameOver = false;

function drawRect(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function drawText(text, x, y, color) {
  ctx.fillStyle = color;
  ctx.font = '24px Arial';
  ctx.fillText(text, x, y);
}

function resetGame() {
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  food = { x: Math.floor(Math.random() * gridWidth), y: Math.floor(Math.random() * gridHeight) };
  score = 0;
  combo = 1;
  gameOver = false;
}

function updateSnake() {
  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
  if (head.x < 0 || head.x >= gridWidth || head.y < 0 || head.y >= gridHeight || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
    gameOver = true;
    return;
  }
  snake.unshift(head);
  if (head.x === food.x && head.y === food.y) {
    score += combo;
    combo++;
    food = { x: Math.floor(Math.random() * gridWidth), y: Math.floor(Math.random() * gridHeight) };
  } else {
    snake.pop();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
  drawRect(food.x, food.y, 'red');
  drawText(`Score: ${score}`, 10, 30, 'black');
  drawText(`Combo: x${combo}`, 10, 60, 'black');
  if (gameOver) {
    drawText('Game Over', gridWidth * gridSize / 2 - 60, gridHeight * gridSize / 2, 'black');
    drawText('Press R to restart', gridWidth * gridSize / 2 - 90, gridHeight * gridSize / 2 + 30, 'black');
  }
}

function gameLoop() {
  if (!gameOver) {
    updateSnake();
  }
  draw();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':
      if (direction.y === 0) direction = { x: 0, y: -1 };
      break;
    case 'ArrowDown':
      if (direction.y === 0) direction = { x: 0, y: 1 };
      break;
    case 'ArrowLeft':
      if (direction.x === 0) direction = { x: -1, y: 0 };
      break;
    case 'ArrowRight':
      if (direction.x === 0) direction = { x: 1, y: 0 };
      break;
    case 'r':
    case 'R':
      if (gameOver) {
        resetGame();
      }
      break;
  }
});

gameLoop();
