canvas.style.height = height + 'px';

ctx.scale(DPR, DPR);

const bird = {
  x: 50,
  y: height / 2,
  width: 30,
  height: 30,
  velocity: 0,
  jumpPower: -10,
  gravity: 0.5
};

const pipes = [];
const pipeWidth = 75;
const gapHeight = 150;
const pipeSpawnInterval = 1500;
let lastPipeSpawn = 0;
let score = 0;
let combo = 0;

function drawBird() {
  ctx.fillStyle = 'yellow';
  ctx.fillRect(bird.x, bird.y, bird.width, bird.height);
}

function drawPipes() {
  ctx.fillStyle = 'green';
  pipes.forEach(pipe => {
    ctx.fillRect(pipe.x, 0, pipe.width, pipe.y);
    ctx.fillRect(pipe.x, pipe.y + gapHeight, pipe.width, height - pipe.y - gapHeight);
  });
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: ${combo}`, 10, 60);
}

function updateBird() {
  bird.velocity += bird.gravity;
  bird.y += bird.velocity;

  if (bird.y + bird.height > height || bird.y < 0) {
    resetGame();
  }
}

function updatePipes() {
  if (Date.now() - lastPipeSpawn > pipeSpawnInterval) {
    lastPipeSpawn = Date.now();
    pipes.push({
      x: width,
      y: Math.random() * (height - gapHeight)
    });
  }

  pipes.forEach(pipe => {
    pipe.x -= 3;
  });

  pipes = pipes.filter(pipe => pipe.x + pipe.width > 0);
}

function checkCollisions() {
  pipes.forEach(pipe => {
    if (bird.x + bird.width > pipe.x &&
        bird.x < pipe.x + pipe.width &&
        (bird.y < pipe.y || bird.y + bird.height > pipe.y + gapHeight)) {
      resetGame();
    }
  });

  if (pipes.length > 0 && bird.x > pipes[0].x + pipeWidth) {
    score++;
    combo++;
    if (combo >= 10) {
      score += combo - 9; // Add combo multiplier
    }
    pipes.shift();
  }
}

function resetGame() {
  bird.y = height / 2;
  bird.velocity = 0;
  pipes.length = 0;
  score = 0;
  combo = 0;
  lastPipeSpawn = 0;
}

function gameLoop() {
  ctx.clearRect(0, 0, width, height);

  updateBird();
  updatePipes();
  checkCollisions();

  drawBird();
  drawPipes();
  drawScore();

  requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', e => {
  if (e.code === 'Space') {
    bird.velocity = bird.jumpPower;
  }
});

gameLoop();
