const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let gameRunning = true;
let score = 0;
let enemies = [];
let player = { x: canvas.width / 2, y: canvas.height - 30, width: 20, height: 20, speed: 5 };
let bullets = [];

canvas.width = window.innerWidth * window.devicePixelRatio;
canvas.height = window.innerHeight * window.devicePixelRatio;
ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

function createEnemy() {
    return { x: Math.random() * canvas.width, y: 0, width: 20, height: 20, speed: 2 + Math.random() * 2 };
}

function update() {
    if (!gameRunning) return;

    // Move player
    if (keys.ArrowLeft && player.x > 0) player.x -= player.speed;
    if (keys.ArrowRight && player.x < canvas.width - player.width) player.x += player.speed;

    // Move enemies
    enemies.forEach(enemy => {
        enemy.y += enemy.speed;
        if (enemy.y > canvas.height) enemies = enemies.filter(e => e !== enemy);
    });

    // Move bullets
    bullets.forEach(bullet => {
        bullet.y -= bullet.speed;
        if (bullet.y < 0) bullets = bullets.filter(b => b !== bullet);
    });

    // Collision detection
    bullets.forEach(bullet => {
        enemies.forEach(enemy => {
            if (bullet.x < enemy.x + enemy.width &&
                bullet.x + bullet.width > enemy.x &&
                bullet.y < enemy.y + enemy.height &&
                bullet.y + bullet.height > enemy.y) {
                enemies = enemies.filter(e => e !== enemy);
                bullets = bullets.filter(b => b !== bullet);
                score++;
            }
        });
    });

    if (enemies.some(enemy => enemy.y + enemy.height > canvas.height)) {
        gameRunning = false;
    }

    requestAnimationFrame(update);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw enemies
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height));

    // Draw bullets
    ctx.fillStyle = 'green';
    bullets.forEach(bullet => ctx.fillRect(bullet.x, bullet.y, bullet.width, bullet.height));

    // Draw score
    ctx.fillStyle = 'white';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    if (!gameRunning) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }

    requestAnimationFrame(draw);
}

function shoot() {
    bullets.push({ x: player.x + player.width / 2, y: player.y, width: 2, height: 5, speed: 10 });
}

function handleKeys(event) {
    if (event.type === 'keydown') keys[event.key] = true;
    if (event.type === 'keyup') keys[event.key] = false;
}

const keys = {};
document.addEventListener('keydown', handleKeys);
document.addEventListener('keyup', handleKeys);
document.addEventListener('click', shoot);

setInterval(() => enemies.push(createEnemy()), 1000);

update();
draw();
