    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.strokeRect(x + 1, y + 1, door.w - 2, door.h - 2);
    // Glowing portal inside.
    if (!locked) {
      const g = ctx.createLinearGradient(x, y, x, y + door.h);
      g.addColorStop(0, "rgba(255,216,107,0.35)");
