const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const CARD_WIDTH = 100;
const CARD_HEIGHT = 100;
const CARD_GAP = 20;
const ROWS = 4;
const COLS = 4;
const TOTAL_CARDS = ROWS * COLS;
const CARDS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P'];
const SHUFFLED_CARDS = shuffle([...CARDS, ...CARDS]);

let selectedCards = [];
let flippedCards = [];
let isFlipping = false;
let lastFlipTime = 0;
const FLIP_TIME = 500;

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
}

function drawCard(x, y, card, flipped) {
    ctx.fillStyle = 'white';
    ctx.fillRect(x, y, CARD_WIDTH, CARD_HEIGHT);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(x, y, CARD_WIDTH, CARD_HEIGHT);
    if (flipped) {
        ctx.font = '30px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(card, x + CARD_WIDTH / 2, y + CARD_HEIGHT / 2);
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            const cardIndex = i * COLS + j;
            const card = SHUFFLED_CARDS[cardIndex];
            drawCard(j * (CARD_WIDTH + CARD_GAP), i * (CARD_HEIGHT + CARD_GAP), card, flippedCards.includes(cardIndex));
        }
    }
}

function flipCard(index) {
    if (isFlipping || flippedCards.includes(index) || selectedCards.includes(index)) return;
    selectedCards.push(index);
    flippedCards.push(index);
    drawBoard();
    if (selectedCards.length === 2) {
        isFlipping = true;
        lastFlipTime = performance.now();
    }
}

function checkMatch() {
    const [index1, index2] = selectedCards;
    if (SHUFFLED_CARDS[index1] !== SHUFFLED_CARDS[index2]) {
        flippedCards = flippedCards.filter(cardIndex => cardIndex !== index1 && cardIndex !== index2);
    }
    selectedCards = [];
    isFlipping = false;
    drawBoard();
}

function update() {
    const now = performance.now();
    if (isFlipping && now - lastFlipTime > FLIP_TIME) {
        checkMatch();
    }
}

function handlePointerClick(event) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const col = Math.floor(x / (CARD_WIDTH + CARD_GAP));
    const row = Math.floor(y / (CARD_HEIGHT + CARD_GAP));
    const index = row * COLS + col;
    if (index >= 0 && index < TOTAL_CARDS) {
        flipCard(index);
    }
}

function handleKeyPress(event) {
    const key = event.key;
    if (key >= 'A' && key <= 'P') {
        const index = SHUFFLED_CARDS.indexOf(key);
        if (index !== -1 && !selectedCards.includes(index)) {
            flipCard(index);
        }
    }
}

canvas.addEventListener('click', handlePointerClick);
document.addEventListener('keydown', handleKeyPress);

function gameLoop(timestamp) {
    update();
    requestAnimationFrame(gameLoop);
}

drawBoard();
requestAnimationFrame(gameLoop);
