        bricks[c][r].y = brickY;
        ctx.beginPath();
        ctx.rect(brickX, brickY, brickWidth, brickHeight);
        ctx.fillStyle = '#0095DD';
        ctx.fill();
        ctx.closePath();
      }
    }
  }
}

function drawScore() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Score: ${score}`, 8, 20);
}

function drawLives() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Lives: ${lives}`, canvas.width - 65, 20);
}

function collisionDetection() {
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      const b = bricks[c][r];
      if (b.status === 1) {
        if (ball.x > b.x && ball.x < b.x + brickWidth && ball.y > b.y && ball.y < b.y + brickHeight) {
          ball.speedY = -ball.speedY;
          b.status = 0;
          score++;
          if (score === rows * cols) {
            state = 'gameover';
          }
        }
      }
    }
  }
}

function drawMenu() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Press Space to Start', canvas.width / 2 - 100, canvas.height / 2);
}

function drawGameOver() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
  ctx.fillText('Press Space to Restart', canvas.width / 2 - 100, canvas.height / 2 + 30);
}

function drawPaused() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Paused', canvas.width / 2 - 30, canvas.height / 2);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (state === 'menu') {
    drawMenu();
  } else if (state === 'playing') {
    drawPaddle();
    drawBall();
    drawBricks();
    drawScore();
    drawLives();
    collisionDetection();
    ball.x += ball.speedX;
    ball.y += ball.speedY;
    if (ball.x + ball.speedX > canvas.width - ball.radius || ball.x + ball.speedX < ball.radius) {
      ball.speedX = -ball.speedX;
    }
    if (ball.y + ball.speedY < ball.radius) {
      ball.speedY = -ball.speedY;
    } else if (ball.y + ball.speedY > canvas.height - ball.radius) {
      if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
        ball.speedY = -ball.speedY;
      } else {
        lives--;
        if (!lives) {
          state = 'gameover';
        } else {
          state = 'menu';
        }
      }
    }
  } else if (state === 'paused') {
    drawPaddle();
    drawBall();
    drawBricks();
    drawScore();
    drawLives();
    drawPaused();
  } else if (state === 'gameover') {
    drawGameOver();
  }
}

function gameLoop() {
  if (state === 'playing') {
    if (leftPressed && paddle.x > 0) {
      paddle.x -= paddle.speed;
    } else if (rightPressed && paddle.x < canvas.width - paddle.width) {
      paddle.x += paddle.speed;
    }
  }
  draw();
  requestAnimationFrame(gameLoop);
}

let leftPressed = false;
let rightPressed = false;

document.addEventListener('keydown', keyDownHandler, false);
