    score = 0;
    lives = 3;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        bricks[c][r].status = 1;
      }
    }
  } else if (e.key === 'p' && state === 'playing') {
    state = 'paused';
  } else if (e.key === 'p' && state === 'paused') {
