function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid() {
  if (asteroids.length < maxAsteroids) {
    asteroids.push({
      x: random(0, canvas.width),
      y: random(0, canvas.height),
      radius: random(10, 40),
      angle: random(0, 2 * Math.PI),
      speed: asteroidSpeed
    });
  }
}

function drawCircle(x, y, radius, color) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, 2 * Math.PI);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.closePath();
}

function drawShip(x, y, angle, radius) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(radius, 0);
  ctx.lineTo(-radius / 2, radius / 2);
  ctx.lineTo(-radius / 2, -radius / 2);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();
}

function drawAsteroid(asteroid) {
  drawCircle(asteroid.x, asteroid.y, asteroid.radius, colors[Math.floor(random(0, colors.length))]);
}

function drawBullet(bullet) {
  drawCircle(bullet.x, bullet.y, 2, 'white');
}

function updateShip() {
  const dx = ship.speed * Math.cos(ship.angle);
  const dy = ship.speed * Math.sin(ship.angle);
  ship.x += dx;
  ship.y += dy;
  if (ship.x < 0) ship.x = canvas.width;
  if (ship.x > canvas.width) ship.x = 0;
  if (ship.y < 0) ship.y = canvas.height;
  if (ship.y > canvas.height) ship.y = 0;
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle);
    asteroid.y += asteroid.speed * Math.sin(asteroid.angle);
    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;
  });
}

function updateBullets() {
  bullets.forEach(bullet => {
    bullet.x += bulletSpeed * Math.cos(bullet.angle);
    bullet.y += bulletSpeed * Math.sin(bullet.angle);
  });
}

function checkCollisions() {
  asteroids.forEach((asteroid, index) => {
    bullets.forEach((bullet, bulletIndex) => {
      const dx = asteroid.x - bullet.x;
      const dy = asteroid.y - bullet.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < asteroid.radius) {
        bullets.splice(bulletIndex, 1);
        asteroids.splice(index, 1);
        score += 10;
      }
    });
  });
}

function checkAsteroidCollision() {
