  handleInput();
  updateShip();
  updateAsteroids();
  updateBullets();
  checkCollisions();
  checkAsteroidCollision();
  drawShip(ship.x, ship.y, ship.angle, ship.radius);
  asteroids.forEach(drawAsteroid);
  bullets.forEach(drawBullet);
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
