            taps.splice(i, 1);
            score++;
            tapThreshold = Math.max(50, tapThreshold - 5);
            break;
        }
    }
}

function update() {
    if (!gameRunning) return;
    tapTimer++;
    if (tapTimer >= tapThreshold) {
        createTap();
        tapTimer = 0;
    }

    for (let i = taps.length - 1; i >= 0; i--) {
        taps[i].update();
        if (taps[i].y < 0) {
            taps.splice(i, 1);
            wave++;
            tapThreshold = Math.max(50, tapThreshold - 5);
            if (wave > 10) {
                gameRunning = false;
                alert(`Game Over! Final Score: ${score}`);
            }
        }
    }
}

function render() {
