let nextBeatTime = 0;
const beatInterval = 1000; // 1 second between beats

// Initialize game state
function init() {
  score = 0;
  isGameOver = false;
  nextBeatTime = Date.now() + beatInterval;
}

// Game loop
function gameLoop() {
  if (isGameOver) {
    return;
  }

  update();
  draw();
  requestAnimationFrame(gameLoop);
}

// Update game state
function update() {
  const now = Date.now();
  if (now >= nextBeatTime) {
    beatTime = now;
    nextBeatTime = now + beatInterval;
  }
}

// Draw to the canvas
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (isGameOver) {
    ctx.fillStyle = 'white';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 50);
  } else {
    const beatX = beatTime % canvas.width;
    ctx.fillStyle = 'red';
    ctx.fillRect(beatX, canvas.height / 2 - 10, 20, 20);
  }
}

// Handle tap events
function handleTap(event) {
  if (isGameOver) {
    return;
  }

  const tapX = event.clientX - canvas.offsetLeft;
  const distanceToBeat = Math.abs(tapX - (beatTime % canvas.width));

  if (distanceToBeat < tapThreshold) {
    score++;
    console.log('Hit!', score);
  } else {
    isGameOver = true;
    console.log('Game Over!');
  }
}

// Listen for taps
canvas.addEventListener('click', handleTap);

// Start the game
init();
gameLoop();
