```javascript
function partition(value) {
  let head = this.head, tail = this.head;

  // partition list
  let current = this.head;
  while(current) {
    const next = current.next;

    if(current.data < value) {
      current.next = head;
      head = current;
    } else {
      tail.next = current;
      tail = current;
    }

    current = next;
  }
  tail.next = null;

  this.head = head;
}
