const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 300;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const COLS = canvas.width / BLOCK_SIZE;
const ROWS = canvas.height / BLOCK_SIZE;
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

class Block {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  }

  moveDown() {
    this.y++;
  }
}

class Board {
  constructor() {
    this.grid = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
    this.currentBlock = this.createBlock();
    this.comboMultiplier = 1;
  }

  createBlock() {
    const x = Math.floor(COLS / 2);
    const y = 0;
    const color = COLORS[Math.floor(Math.random() * COLORS.length)];
    return new Block(x, y, color);
  }

  draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let row of this.grid) {
      for (let block of row) {
        if (block) block.draw();
      }
    }
    this.currentBlock.draw();
  }

  moveBlockDown() {
    if (this.checkCollision(this.currentBlock.x, this.currentBlock.y + 1)) {
      this.lockBlock();
      this.clearLines();
      this.currentBlock = this.createBlock();
      if (this.checkCollision(this.currentBlock.x, this.currentBlock.y)) {
        alert('Game Over!');
        document.location.reload();
      }
    } else {
      this.currentBlock.moveDown();
    }
  }

  checkCollision(x, y) {
    if (x < 0 || x >= COLS || y >= ROWS) return true;
    if (this.grid[y][x]) return true;
    return false;
  }

  lockBlock() {
    this.grid[this.currentBlock.y][this.currentBlock.x] = this.currentBlock;
  }

  clearLines() {
    let linesCleared = 0;
    for (let row = ROWS - 1; row >= 0; row--) {
      if (this.grid[row].every(block => block)) {
        this.grid.splice(row, 1);
        this.grid.unshift(Array(COLS).fill(null));
        linesCleared++;
      }
    }
    if (linesCleared > 0) {
      this.comboMultiplier = Math.min(this.comboMultiplier + linesCleared, 4);
      alert(`Combo x${this.comboMultiplier}!`);
    }
  }
}

const board = new Board();

function gameLoop() {
  board.moveBlockDown();
  board.draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();

document.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowLeft':
      if (!board.checkCollision(board.currentBlock.x - 1, board.currentBlock.y)) {
        board.currentBlock.x--;
      }
      break;
    case 'ArrowRight':
      if (!board.checkCollision(board.currentBlock.x + 1, board.currentBlock.y)) {
        board.currentBlock.x++;
      }
      break;
    case 'ArrowDown':
      board.moveBlockDown();
      break;
  }
});
