const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const fixedTimestep = 1000 / 60; // 60 FPS
let lastTime = performance.now();
let accumulator = 0;

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: 20,
    speed: 5,
    angle: 0,
    bullets: []
};

const enemies = [];
const numEnemies = 10;
for (let i = 0; i < numEnemies; i++) {
    enemies.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        size: 10,
        speed: 2
    });
}

let score = localStorage.getItem('highScore') || 0;
let gameOver = false;

function updatePlayer(delta) {
    const speed = player.speed * delta;
    if (keys['ArrowUp']) player.y -= speed;
    if (keys['ArrowDown']) player.y += speed;
    if (keys['ArrowLeft']) player.x -= speed;
    if (keys['ArrowRight']) player.x += speed;

    if (keys[' ']) {
        const bullet = {
            x: player.x + Math.cos(player.angle) * player.size,
            y: player.y + Math.sin(player.angle) * player.size,
            size: 3,
            speed: 10,
            angle: player.angle
        };
        player.bullets.push(bullet);
        keys[' '] = false; // Prevent rapid fire
    }

    player.bullets.forEach(bullet => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed * delta;
        bullet.y += Math.sin(bullet.angle) * bullet.speed * delta;
    });

    // Remove bullets that go off-screen
    player.bullets = player.bullets.filter(bullet =>
        bullet.x > 0 && bullet.x < canvas.width &&
        bullet.y > 0 && bullet.y < canvas.height
    );
}

function updateEnemies(delta) {
    enemies.forEach(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance > 0) {
            enemy.x += dx / distance * enemy.speed * delta;
            enemy.y += dy / distance * enemy.speed * delta;
        }
    });
}

function checkCollisions() {
    player.bullets.forEach((bullet, bulletIndex) => {
        enemies.forEach((enemy, enemyIndex) => {
            const dx = bullet.x - enemy.x;
            const dy = bullet.y - enemy.y;
            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < bullet.size + enemy.size) {
                player.bullets.splice(bulletIndex, 1);
                enemies.splice(enemyIndex, 1);
                score++;
                if (score > localStorage.getItem('highScore')) {
                    localStorage.setItem('highScore', score);
                }
            }
        });
    });

    if (enemies.some(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        return distance < player.size + enemy.size;
    })) {
        gameOver = true;
    }
}

function render() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'red';
    player.bullets.forEach(bullet => {
        ctx.beginPath();
        ctx.arc(bullet.x, bullet.y, bullet.size, 0, Math.PI * 2);
        ctx.fill();
    });

    ctx.fillStyle = 'blue';
    enemies.forEach(enemy => {
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
        ctx.fill();
    });

    ctx.fillStyle = 'green';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'white';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
    ctx.fillText('High Score: ' + localStorage.getItem('highScore'), 10, 60);
}

function gameLoop() {
    const now = performance.now();
    const delta = now - lastTime;
    lastTime = now;
    accumulator += delta;

    while (accumulator >= fixedTimestep) {
        updatePlayer(fixedTimestep / 1000);
        updateEnemies(fixedTimestep / 1000);
        checkCollisions();
        accumulator -= fixedTimestep;
    }

    render();

    if (!gameOver) {
        requestAnimationFrame(gameLoop);
    } else {
        ctx.fillStyle = 'red';
        ctx.font = '40px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

gameLoop();
