      showMsg('📊 Market event ended — prices returning to normal.');
    }
  }
  // Chance of new event
  if (!economy.event && Math.random() < .28) {
    const ev = MARKET_EVENTS[Math.floor(Math.random()*MARKET_EVENTS.length)];
    economy.event = ev; economy.evDaysLeft = ev.dur;
    economy.mult = { carrot:1, corn:1, pumpkin:1, glowroot:1, tomato:1, dustwheat:1, sunblossom:1, pepper:1, melon:1, potato:1, lavender:1, cactusFruit:1, blueberry:1, stone:1, wood:1, herb:1, egg:1, wool:1, milk:1, pork:1, rabbitFur:1, goatMilk:1, horseshoe:1, banditScarf:1, wolfPelt:1, burrowerCarapace:1, raiderBadge:1, snakeFang:1, scorpionStinger:1, coyoteHide:1, woolBlanket:1, copperFitting:1, ironSpike:1, leatherStrip:1, plank:1, rope:1, cloth:1, pepperStew:1, potatoMash:1, berryJam:1, lavenderTea:1, porkRoast:1, goatCheese:1 };
    for (const k in ev.effect) economy.mult[k] = ev.effect[k];
    showMsg(`📢 MARKET EVENT: ${ev.name} — ${ev.desc}`);
  }
  // Recalculate prices
  for (const k in economy.prices) {
    const base = BASE_PRICES[k]||10;
    const vol  = VOLATILITY[k]||.2;
    const noise = 1 + (Math.random()*2-1)*vol;
    economy.prices[k] = Math.max(1, Math.round(base * noise * (economy.mult[k]||1)));
  }
  // Seed prices also fluctuate slightly
  for (const k in economy.seedPrices) {
    const base = BASE_SEED_PRICES[k]||2;
    economy.seedPrices[k] = Math.max(1, Math.round(base * (1+(Math.random()*.3-.1))));
  }
  updateFarmPanelPrices();
}
