  for(let y=0;y<MAP_H;y++) for(let x=0;x<MAP_W;x++) {
    const n=Math.random();
    setT(x,y, n<.62?TL.GRASS:n<.76?TL.DIRT:n<.84?TL.FLOWERS:TL.BUSH);
  }
  for(let y=2;y<33;y++) for(let x=2;x<33;x++) setT(x,y,TL.DIRT);
