function drawTile(tx,ty,sx,sy) {
  const t=getT(tx,ty), c=TC[t]||TC[TL.GRASS];
  ctx.fillStyle=c[0]; ctx.fillRect(sx,sy,T,T);
  if(t===TL.GRASS){ctx.fillStyle=c[1];if((tx+ty)%3===0){ctx.fillRect(sx+4,sy+2,2,4);ctx.fillRect(sx+10,sy+6,2,3);}}
  else if(t===TL.FARM_DRY){ctx.fillStyle='#7a4820';for(let i=0;i<3;i++)ctx.fillRect(sx+2,sy+5+i*9,T-4,2);}
  else if(t===TL.FARM_TILLED){ctx.fillStyle='#4a2808';for(let i=0;i<3;i++)ctx.fillRect(sx+2,sy+5+i*9,T-4,2);ctx.fillStyle='#3a1800';for(let i=0;i<3;i++)ctx.fillRect(sx+2,sy+6+i*9,T-4,1);}
  else if(t===TL.FARM_WATERED){ctx.fillStyle='#2a1800';for(let i=0;i<3;i++)ctx.fillRect(sx+2,sy+5+i*9,T-4,2);ctx.fillStyle='rgba(40,80,160,.3)';ctx.fillRect(sx,sy,T,T);}
  else if(t===TL.TREE){ctx.fillStyle='#1a4010';ctx.beginPath();ctx.arc(sx+T/2,sy+T/2,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2a6020';ctx.beginPath();ctx.arc(sx+T/2-3,sy+T/2-3,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#604030';ctx.fillRect(sx+T/2-2,sy+T-7,4,7);}
  else if(t===TL.WATER){const w=Math.sin(Date.now()*.0015+tx*.5+ty*.3)*1.5;ctx.fillStyle='#2050a8';ctx.fillRect(sx,sy+7+w,T,3);ctx.fillRect(sx,sy+18+w,T,2);}
  else if(t===TL.BUILDING){ctx.fillStyle='#503020';ctx.fillRect(sx+2,sy+2,T-4,T-4);ctx.fillStyle='#180e08';ctx.fillRect(sx+5,sy+5,T-10,T-10);if(gameState.isNight){ctx.fillStyle='rgba(255,200,80,.15)';ctx.fillRect(sx+8,sy+8,T-16,T-16);}}
  else if(t===TL.FENCE){ctx.fillStyle='#c09060';ctx.fillRect(sx+T/2-2,sy,4,T);ctx.fillRect(sx,sy+6,T,3);ctx.fillRect(sx,sy+18,T,3);}
  else if(t===TL.WELL){ctx.fillStyle='#707880';ctx.fillRect(sx+6,sy+8,T-12,T-12);ctx.fillStyle='#3040b0';ctx.fillRect(sx+9,sy+11,T-18,T-18);ctx.fillStyle='#909898';ctx.fillRect(sx+4,sy+6,T-8,4);}
  else if(t===TL.CRATE){ctx.fillStyle='#c08040';ctx.fillRect(sx+4,sy+4,T-8,T-8);ctx.strokeStyle='#806020';ctx.lineWidth=1;ctx.strokeRect(sx+4,sy+4,T-8,T-8);}
  else if(t===TL.FORGE){
    // Base / stone surround
    ctx.fillStyle='#3a2a20';ctx.fillRect(sx,sy,T,T);
    ctx.fillStyle='#584030';ctx.fillRect(sx+3,sy+3,T-6,T-6);
    // Firebox opening
    ctx.fillStyle='#1a0c08';ctx.fillRect(sx+8,sy+14,T-16,T-20);
    // Fire glow — flickers using time
    const flicker=0.5+0.5*Math.sin(Date.now()*.008+sx);
    const r=Math.floor(220+35*flicker), g=Math.floor(80+60*flicker);
    ctx.fillStyle=`rgb(${r},${g},20)`;ctx.fillRect(sx+10,sy+16,T-20,T-24);
    // Ember highlights
    ctx.fillStyle='rgba(255,200,80,.6)';ctx.fillRect(sx+12,sy+18,4,3);ctx.fillRect(sx+T-16,sy+20,3,3);
    // Chimney stub top
    ctx.fillStyle='#2a1e18';ctx.fillRect(sx+10,sy,12,7);
    ctx.fillStyle='#1a0e0a';ctx.fillRect(sx+12,sy+1,8,5);
    // Smoke wisps
    const sm=Date.now()*.002;
    ctx.fillStyle='rgba(180,160,140,.35)';
    ctx.fillRect(sx+13+(Math.sin(sm)*2|0), sy-4+(Math.sin(sm*.7)*1|0), 3,4);
    ctx.fillRect(sx+17+(Math.sin(sm+1)*2|0),sy-7+(Math.sin(sm*.5)*1|0),2,4);
  }
  else if(t===TL.WORKBENCH){
    // Table surface
    ctx.fillStyle='#a07040';ctx.fillRect(sx+2,sy+6,T-4,T-10);
    // Legs
    ctx.fillStyle='#7a5028';ctx.fillRect(sx+3,sy+T-8,4,8);ctx.fillRect(sx+T-7,sy+T-8,4,8);
    // Tool details on surface
    ctx.fillStyle='#c09050';ctx.fillRect(sx+5,sy+9,T-10,3);
    ctx.fillStyle='#e0b060';ctx.fillRect(sx+6,sy+10,6,2);ctx.fillRect(sx+T-12,sy+10,5,2);
    // Icon
    ctx.font='11px serif';ctx.textAlign='center';ctx.fillText('🪚',sx+T/2,sy+T/2+2);
  }
  else if(t===TL.ROAD){ctx.fillStyle=c[1];ctx.fillRect(sx,sy+T/2-1,T,2);}
