    if (!raw) { showMsg('No save found.'); return; }
    const d = JSON.parse(raw);

    gameState.day = d.day;
    gameState.timeOfDay = d.timeOfDay;
    gameState.season = d.season || 'Dry Summer';

    Object.assign(player, d.player);

    inventory.slots = d.inventory.slots;
