function useTool(wx, wy) {
  if (player.actionCooldown > 0) return;
  const tx = Math.floor(wx/T), ty = Math.floor(wy/T);
  const key = plotKey(tx,ty);

  // Check interact zones first (market, general store)
  const ptx = Math.floor(player.x/T), pty = Math.floor(player.y/T);

  // Mine interior interactions
  if (gameState.inMine) {
    const fl = gameState.mineFloor;
    const mineChecks = [[ptx,pty],[ptx,pty+1],[ptx,pty-1],[ptx+1,pty],[ptx-1,pty]];
    for (const [cx2,cy2] of mineChecks) {
      const mt = getMineT(fl, cx2, cy2);
      if (mt === TL.MINE_EXIT) { exitMine(); return; }
      if (mt === TL.MINE_SHAFT_DOWN) { mineDescend(); return; }
      if (mt === TL.MINE_SHAFT_UP) { mineAscend(); return; }
    }
    // Resource gathering in mine
    const mineNearby = getMineNearbyNode();
    if (mineNearby) { gatherMineNode(mineNearby.key); player.actionCooldown=.5; return; }
    return;
  }

  // Traveling merchant interaction
  if (merchantPresent && Math.hypot(player.x - MERCHANT_X, player.y - MERCHANT_Y) < 72) {
    openMerchantShop(); return;
  }

  // Overworld: enter mine via TL.MINE tile
  const mineEntryChecks = [[ptx,pty],[ptx,pty+1],[ptx,pty-1],[ptx+1,pty],[ptx-1,pty]];
  for (const [cx0,cy0] of mineEntryChecks) {
    if (getT(cx0,cy0) === TL.MINE) { enterMine(); return; }
  }

  // Fishing — near water or fishing spot with rod equipped
  if (isNearFishingSpot() && countItem('fishingRod')) {
    castFishing(); return;
  }

  // Forge sprite (x=29,y=26) — open smelt overlay (requires Mine Forge upgrade)
  const forgeChecks = [[ptx,pty],[ptx,pty+1],[ptx,pty-1],[ptx+1,pty],[ptx-1,pty]];
  for (const [fx,fy] of forgeChecks) {
    if (getT(fx,fy) === TL.FORGE) {
      if (!player._mineForge) { showMsg('🔒 Upgrade the Mine Forge first (Market → Upgrades → Mine).'); return; }
      openSmeltForge(); return;
    }
  }

  const checks = [[ptx,pty],[ptx,pty+1],[ptx,pty-1],[ptx+1,pty],[ptx-1,pty],[ptx+2,pty],[ptx-2,pty],[ptx,pty+2]];
  for (const [cx,cy] of checks) {
    if (cy>=3&&cy<=12 && cx>=47&&cx<=60) { openMarket(); setMktTab('buysell'); return; }
    if (cy>=15&&cy<=24 && cx>=61&&cx<=72) { openMarket(); setMktTab('buysell'); return; }
  }

  // Phase 5: Resource gathering handled at keydown level for E key;
  // canvas click still needs to handle it here
  if ((gameState.zone==='Wilderness' || gameState.zone==='Mine') && arguments.length===2) {
    const nearby = getNearbyNode();
    if (nearby) { gatherNode(nearby.key); player.actionCooldown=.5; return; }
  }

  // Fix 5: Pen repair — E near gate of a broken pen
  for (const pen of pens) {
    if (pen.hp > 0) continue;
    const gateX = pen.x + Math.floor(pen.w/2);
    const gateY = pen.y + pen.h - 1;
    if (Math.abs(tx-gateX)<=1 && Math.abs(ty-gateY)<=1) {
      repairPen(pen); return;
    }
  }

  // Ranch: barn door toggle (E near barn door row)
  if (ty>=50&&ty<=54 && tx>=16&&tx<=19) {
    // If products ready nearby, collect all first
    if (products.length > 0) {
      const nearProds = products.filter(p => {
        const pen = getPenById(pens.find(pen2 => pen2.animals.includes(p.animalId))?.id);
        return true; // collect all ranch products when near barn
      });
      if (nearProds.length > 0) {
        let collected = 0;
        for (const prod of [...nearProds]) {
          if (inventory.totalWeight >= getEffectiveWeightCap()) break;
          const itemMap = { chicken:'egg', sheep:'wool', cow:'milk', pig:'pork', rabbit:'rabbitFur', goat:'goatMilk', horse:'horseshoe' };
          const itemId = itemMap[prod.type];
          if (itemId) { addItem(itemId, 1); products = products.filter(p => p.id !== prod.id); collected++; }
        }
        if (collected > 0) {
          spawnParticles(player.x, player.y, '#f0d060', 6, '🧺');
          showMsg(`🧺 Collected ${collected} product${collected>1?'s':''} from all animals!`);
          refreshInvUI(); updateRanchPanel(); return;
        }
      }
    }
    toggleBarn(); return;
  }

  // Ranch: fill trough (E near any pen trough)
  for (const pen of pens) {
    const { tx: ptx2, ty: pty2 } = getPenTroughPos(pen);
    if (Math.abs(tx - ptx2) <= 1 && Math.abs(ty - pty2) <= 1) { fillPenTrough(pen); return; }
  }
  // Legacy barn trough at (9,42)
  if (tx===9&&ty===42) { fillTrough(); return; }

  // Ranch: collect product (E near floating product)
  const nearProd = products.find(p => Math.hypot(player.x-p.x, player.y-p.y) < T*1.5);
  if (nearProd) { collectProduct(nearProd); return; }

  // Ranch well (x24-25, y54)
  if ((tx===24||tx===25) && ty===54) {
    inventory.water = inventory.waterCap;
    spawnParticles(wx,wy,'#4090c0',6,'💧');
    showMsg('💧 Ranch well — watering can refilled!'); refreshInvUI(); return;
  }

  // Well: refill water
  if ((tx===13||tx===14) && ty===26) {
    inventory.water = inventory.waterCap;
    spawnParticles(wx,wy,'#4090c0',6,'💧');
    showMsg('💧 Watering can refilled!');
    refreshInvUI(); return;
  }

  // Farm Chest (tx=16, ty=26) — open/close storage
  if (tx === CHEST_TX && ty === CHEST_TY) {
    if (chestOpen) { closeChest(); } else { openChest(); }
    return;
  }

  // Campfire (tx=27, ty=4) — open crafting → cooking recipes
  if (Math.abs(tx-27)<=2 && Math.abs(ty-4)<=2 && getT(27,4)===TL.CAMPFIRE) {
    if (!player._campfireUnlocked) { showMsg('🔥 This campfire needs building — buy the Cooking Campfire upgrade at market (Farm tab, $120).'); return; }
    openMarket(); setMktTab('crafting'); return;
  }

  // Forge sprite (tx=29, ty=26) — open smelt overlay (requires Mine Forge upgrade)
  if (Math.abs(tx-29)<=1 && Math.abs(ty-26)<=1 && getT(29,26)===TL.FORGE) {
    if (!player._mineForge) { showMsg('🔒 Upgrade the Mine Forge first (Market → Upgrades → Mine).'); return; }
    openSmeltForge(); return;
  }

  // Workbench (tx=26, ty=26) — open crafting tab
  if (Math.abs(tx-WORKBENCH_TX)<=1 && Math.abs(ty-WORKBENCH_TY)<=1) {
    if (!player._workbenchUnlocked) { showMsg('🔒 Upgrade the Crafting Workbench first (Market → Upgrades → Farm).'); return; }
    openMarket(); setMktTab('crafting');
    showMsg('🪚 Workbench — craft items from your materials.');
    return;
  }

  if (player.tool==='till') {
    if (!isFarmTile(tx,ty)) { showMsg('⚠️ Till only on the brown farm plots!'); return; }
    if (!plots[key]) plots[key]={tilled:false,watered:false,crop:null,growthProgress:0,wateredToday:false,wilted:false,harvestReady:false};
    if (plots[key].tilled&&!plots[key].crop) { showMsg('Already tilled.'); return; }
    if (plots[key].crop) { showMsg('⚠️ Crop is here — harvest it first.'); return; }
    // Block double-trigger while timer active for same tile
    if (actionTimer.active && actionTimer._nodeKey === key+'_till') return;
    if (actionTimer.active) cancelAction('');
    const hW = getEffectiveHoeW(), hH = getEffectiveHoeH();
    const aoeLabel = hW>1 ? ` (${hW}×${hH})` : '';
    actionTimer._nodeKey = key+'_till';
    startAction('⛏ Tilling'+aoeLabel+'…', getTillDuration(), () => {
      dSound('tool');
      let tilled = 0;
      for (let dy = 0; dy < hH; dy++) {
        for (let dx = 0; dx < hW; dx++) {
          const ttx = tx + dx, tty = ty + dy;
          const tkey = plotKey(ttx, tty);
          if (!isFarmTile(ttx, tty)) continue;
          if (!plots[tkey]) plots[tkey]={tilled:false,watered:false,crop:null,growthProgress:0,wateredToday:false,wilted:false,harvestReady:false};
          if (plots[tkey].tilled && !plots[tkey].crop) continue;
          if (plots[tkey].crop) continue;
          plots[tkey].tilled = true;
          setT(ttx, tty, TL.FARM_TILLED);
          tilled++;
        }
      }
      if (tilled > 0) {
        spawnParticles(wx,wy,'#8a6030',Math.min(tilled*2,8),'✦');
        showMsg(`Tilled ${tilled} plot${tilled>1?'s':''}${aoeLabel}! Buy seeds at [M].`);
      } else {
        showMsg('Nothing to till here.');
      }
      player.actionCooldown = 0.1;
      player.stamina = Math.max(0, player.stamina - 3*Math.max(1,tilled));
      actionTimer._nodeKey = null;
    });

  } else if (player.tool==='water') {
    if (inventory.water<=0) { showMsg('⚠️ Can is empty — walk to the well to refill!'); return; }
    if (actionTimer.active && actionTimer._nodeKey === key+'_water') return;
    if (actionTimer.active) cancelAction('');
    const cW = getEffectiveCanW(), cH = getEffectiveCanH();
    const aoeWLabel = cW>1 ? ` (${cW}×${cH})` : '';
    actionTimer._nodeKey = key+'_water';
    startAction('💧 Watering'+aoeWLabel+'…', getWaterDuration(), () => {
      let watered = 0;
      for (let dy = 0; dy < cH; dy++) {
        for (let dx = 0; dx < cW; dx++) {
          if (inventory.water <= 0) break;
          const ttx = tx + dx, tty = ty + dy;
          const tkey = plotKey(ttx, tty);
          const p2 = plots[tkey];
          if (!p2||!p2.tilled||p2.wateredToday) continue;
          p2.watered = p2.wateredToday = true; p2.wilted = false;
          inventory.water--;
          setT(ttx, tty, TL.FARM_WATERED);
          watered++;
        }
      }
      if (watered > 0) {
        spawnParticles(wx, wy, '#4090c0', Math.min(watered*2, 8), '💧');
        showMsg(`💧 Watered ${watered} plot${watered>1?'s':''}${aoeWLabel}! (${inventory.water} left)`);
      } else {
        const p = plots[key];
        if (!p||!p.tilled) showMsg('⚠️ Till this soil first!');
        else showMsg('Already watered today.');
      }
      player.actionCooldown = 0.1;
      refreshInvUI();
      actionTimer._nodeKey = null;
    });

  } else if (player.tool==='plant') {
    const p = plots[key];
    if (!p||!p.tilled) { showMsg('⚠️ Till this soil first!'); return; }
    if (p.crop) { showMsg('Already planted here.'); return; }
    const sk = SEED_MAP[player.selectedSeed];
    if ((inventory.seeds[sk]||0)<=0) { showMsg(`⚠️ No ${CROPS[player.selectedSeed].name} seeds! Buy at market [M].`); return; }
    p.crop = player.selectedSeed; p.growthProgress=0; p.wilted=false; p.harvestReady=false;
    inventory.seeds[sk]--;
    setT(tx,ty, p.watered?TL.FARM_WATERED:TL.FARM_TILLED);
    spawnParticles(wx,wy,'#60a040',4,CROPS[player.selectedSeed].icon);
    showMsg(`${CROPS[player.selectedSeed].icon} ${CROPS[player.selectedSeed].name} planted!`);
    player.actionCooldown=.32; refreshInvUI(); buildHotbar();

  } else if (player.tool==='harvest') {
    const p = plots[key];
    if (!p||!p.crop) { showMsg('Nothing to harvest here.'); return; }
    if (!p.harvestReady) { showMsg(`${CROPS[p.crop].icon} ${Math.floor(p.growthProgress*100)}% grown — not ready yet.`); return; }
    if (inventory.totalWeight >= getEffectiveWeightCap()) { showMsg('⚠️ Bag too heavy to harvest! Sell goods or use the chest [M].'); return; }
    if (actionTimer.active && actionTimer._nodeKey === key+'_harvest') return;
    if (actionTimer.active) cancelAction('');
    const cropNow = p.crop;
    actionTimer._nodeKey = key+'_harvest';
    startAction(`🌾 Harvesting ${CROPS[cropNow].icon}…`, getHarvestDuration(), () => {
      // re-validate after timer
      if (!p.crop || !p.harvestReady) { showMsg('Plot changed.'); return; }
      const qty = (p.wilted ? 1 : 2+Math.floor(Math.random()*2)) + getEffectiveHarvestBonus();
      const added = addItem(cropNow, qty);
      if (added <= 0) { showMsg('⚠️ Bag full — open chest to store goods!'); return; }
      spawnParticles(wx,wy,CROPS[cropNow].color,6,CROPS[cropNow].icon);
      spawnParticles(wx,wy,'#f0d060',2,'+'+added);
      showMsg(added < qty ? `🌾 ${added}/${qty} ${CROPS[cropNow].name} — bag too heavy for rest!` : `🌾 Harvested ${added}× ${CROPS[cropNow].name}! [M] to sell.`);
      p.crop=null; p.growthProgress=0; p.harvestReady=false; p.wateredToday=false;
      dSound('harvest');
      setT(tx,ty,TL.FARM_TILLED);
      player.actionCooldown = 0.1;
      player.stamina = Math.max(0, player.stamina-4);
      actionTimer._nodeKey = null;
    });
  }
}
