function _handleOCInteraction() {
  if (!gameState.inOcean) return false;
  if (ocTalkOpen) { closeOCTalk(); return true; }

  // NPC proximity
  for (const npc of OC_NPCS) {
    const nx = npc.tx*OC_T+OC_T/2, ny = npc.ty*OC_T+OC_T/2;
    if (Math.hypot(player.x-nx, player.y-ny) < 80) {
      openOCTalk(npc.id, 'root');
      return true;
    }
  }

  // Board / disembark boat — near gangplank tile
  const ptx=Math.floor(player.x/OC_T), pty=Math.floor(player.y/OC_T);
  const nearGangplank = [
    [ptx,pty],[ptx+1,pty],[ptx-1,pty],[ptx,pty+1],[ptx,pty-1]
  ].some(([cx,cy])=>getOCT(cx,cy)===OC.GANGPLANK);

  if (nearGangplank && hasBoat()) {
    player._onBoat = !player._onBoat;
    if (player._onBoat) {
      // Place player at centre of boat deck
      player.x = 24*OC_T + OC_T/2;
      player.y = 38*OC_T + OC_T/2;
      showMsg(`${getBoatTier().icon} Aboard the ${getBoatTier().name}. Move freely on deep water.`);
    } else {
      // Step back onto gangplank
      player.x = 21*OC_T + OC_T/2;
      player.y = 38*OC_T + OC_T/2;
      showMsg('⚓ Disembarked.');
    }
    return true;
  }

  // Fishing — dock, gangplank, boat deck, or on boat
  const onFishable = [OC.DOCK,OC.GANGPLANK,OC.BOAT_DECK].includes(getOCT(ptx,pty)) || player._onBoat;
  if (onFishable && player.tool==='fish') {
    castOceanFishing();
    return true;
  }

  return false;
}
