```javascript
function drawTile(ctx,t,px,py,dark,fc){
  const fl=Math.floor(fc/20)%2;
  switch(t){
    case T.FLOOR:{
      ctx.fillStyle=dark?'#12081a':'#0e1030';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle=dark?'#180a22':'#10122e';
      ctx.fillRect(px,py,1,TW); ctx.fillRect(px,py,TW,1);
      break;}
    case T.WALL:{
      ctx.fillStyle=dark?'#160516':'#101014';
      ctx.fillRect(px,py,TW,TW);
      const alt=((px/TW)+(py/TW))%2===0;
      ctx.fillStyle=dark?'#28082a':'#1e1e24';
      ctx.fillRect(px+(alt?0:8),py,8,7);
      ctx.fillRect(px+(alt?8:0),py+8,8,7);
      ctx.fillStyle=dark?'#380a3a':'#26263a';
      ctx.fillRect(px+(alt?0:8),py,7,1);
      ctx.fillRect(px+(alt?8:0),py+8,7,1);
      break;}
    case T.BRICK:{
      const alt2=Math.floor(py/TW)%2===0;
      ctx.fillStyle='#140e06';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle='#221408';
      ctx.fillRect(px+(alt2?0:8),py,8,7);
      ctx.fillRect(px+(alt2?8:0),py+8,8,7);
      ctx.fillStyle='#3a2210';
      ctx.fillRect(px+(alt2?0:8),py,7,1);
      ctx.fillRect(px+(alt2?8:0),py+8,7,1);
      break;}
    case T.DOOR:{
      ctx.fillStyle='#5c2a00';
      ctx.fillRect(px,py,TW,TW);
      ctx.fillStyle='#7a3800';
      ctx.fillRect(px+2,py+2,12,12);
      ctx.fillStyle='#b88000';
      ctx.fillRect(px+7,py+7,2,2);
      ctx.fillStyle='#d8b000';
      ctx.fillRect(px+7,py+7,1,1);
      break;}
    case T.ALTAR:{
      ctx.fillStyle=dark?'#200808':'#181010';
