function damagePlayer(dmg,ex,ey){
  const p=S.player;
  if(p.inv>0) return;
  p.hp=Math.max(0,p.hp-dmg);
  p.inv=80;
  p.curse=Math.min(p.maxCurse,p.curse+6);
  // knockback away from enemy
  if(ex!==undefined){
    const dx=p.x-ex, dy=p.y-ey;
    const d=Math.hypot(dx,dy)||1;
    p.knockX=dx/d*4; p.knockY=dy/d*4;
  }
  shake(7); playHit();
  if(p.hp<=0) S.scene=SC.GAMEOVER;
}
