function drawSanctumDecorations(ctx, cols) {
  const ROWS  = 14;
  const T     = NES.TILE;
  const zpal  = ZONE_PAL[ZONE_ID.SANCTUM];

  /* ── Pew backs — drawn behind the platform tiles in the static layer ──
     Each pew: tall back (6px) sitting on the platform (r5), facing inward.
     GDD: "pews turned inward" — backs face the altar (right side), not the wall. */
  const pewCols = [8, 24, 40];  /* left edge of each pew platform */
  pewCols.forEach(col => {
    const px = col * T;
    /* Pew back at r4 (above the seat at r5) — 16px wide, 10px tall */
    const backY = 4 * T + 4;
    ctx.fillStyle = zpal.solidBase;
    ctx.fillRect(px, backY, T * 2, 10);
    /* Dark wood grain */
    ctx.fillStyle = zpal.solidShad;
    ctx.fillRect(px + 2, backY + 2, T * 2 - 4, 2);
    ctx.fillRect(px + 2, backY + 6, T * 2 - 4, 1);
    /* Top rail highlight */
    ctx.fillStyle = zpal.solidTop;
    ctx.fillRect(px, backY, T * 2, 2);
    /* Kneeling cushion at base of pew (below seat) */
    ctx.fillStyle = zpal.platformMid;
    ctx.fillRect(px + 2, 5 * T + T, T * 2 - 4, 3);
  });

  /* ── Altar ── right side raised section cols 38-54 ── */
  /* Altar table: dark stone slab at r6-r7 transition */
  const altarX = 42 * T;
  const altarY = 6 * T;
  ctx.fillStyle = zpal.solidBase;
  ctx.fillRect(altarX, altarY - 4, 8 * T, 8);   /* altar slab */
  ctx.fillStyle = zpal.solidTop;
  ctx.fillRect(altarX, altarY - 4, 8 * T, 2);   /* top edge */
  ctx.fillStyle = PAL.GOLD;
  ctx.fillRect(altarX + 4, altarY - 6, 8, 3);   /* altar cloth gold trim */
  ctx.fillRect(altarX + T * 6, altarY - 6, 8, 3);

  /* Altar candles — two on either side */
  [[altarX + 6, altarY - 12], [altarX + T * 7 - 4, altarY - 12]].forEach(([cx, cy]) => {
    ctx.fillStyle = PAL.STONE_HIGH;
    ctx.fillRect(cx, cy + 4, 4, 8);   /* candle body */
    ctx.fillStyle = PAL.PALE_GOLD;
    ctx.fillRect(cx, cy + 2, 4, 3);   /* wax drip */
    ctx.fillStyle = PAL.FIRE_RED;
    ctx.fillRect(cx + 1, cy, 2, 3);   /* flame */
    ctx.fillStyle = PAL.GOLD;
    ctx.fillRect(cx + 1, cy - 1, 2, 1); /* flame tip */
  });

  /* ── Inverted cross on altar back wall (corrupt sanctum) ── */
  const crossX = 47 * T;
  const crossY = 5 * T;
  ctx.fillStyle = PAL.BLOOD_RED;
  ctx.fillRect(crossX + 6, crossY,      4, 12);  /* vertical bar */
  ctx.fillRect(crossX + 2, crossY + 4,  12, 4);  /* horizontal bar */
