  [[10, 9], [22, 9], [30, 9]].forEach(([col, row]) => {
    const cx2 = col * T; const cy2 = row * T;
    ctx.fillStyle = zpal.solidShad;
    ctx.fillRect(cx2 + 3, cy2 + 5, 6, 1);   /* crack line */
    ctx.fillRect(cx2 + 6, cy2 + 3, 1, 4);   /* crack split */
  });

  /* ── Torn canopy remnants above altar ── */
  ctx.fillStyle = zpal.solidBase;
  ctx.fillRect(38 * T, 4 * T, T * 2, 3);     /* canopy left rail */
  ctx.fillRect(52 * T, 4 * T, 2 * T - 4, 3); /* canopy right rail */
  ctx.fillStyle = zpal.solidTop;
